-- Formation type StartupWeek Academy : « Construire son MVP avec l'IA » (générée par scripts/academy-sql.ts).

-- 10 modules, 65 leçons, 3000 minutes.

begin;

insert into crm.academy_courses (id, title, slug, subtitle, description, status, level, personas, audience, objectives, prerequisites, duration_hours, price_cents, vat_rate, in_catalog, access_days, sequential, event_ids, tags, author_ids, speaker_ids, is_training, evaluation_methods, assistance, accessibility, passing_score, certificate_min_progress)
values ($q$crs_mvp_ia$q$, $q$Construire son MVP avec l'IA$q$, $q$construire-son-mvp-avec-l-ia$q$, $q$De l'idée au lancement : la StartupWeek en e-learning, à votre rythme$q$, $q$La StartupWeek en ligne : les mêmes thèmes que le bootcamp de 7 jours, dans un parcours de 50 heures à suivre à votre rythme pendant 6 mois.

Vous construisez **votre propre MVP** du premier au dernier module : cadrage, prompts, choix de la stack, architecture, maquettes, construction avec les outils d'IA, tests utilisateurs, lancement et pitch. Un projet fil rouge, Créno, illustre chaque étape.

## Ce que vous allez faire
- Cadrer votre problème, votre cible et le périmètre de votre MVP dans un cahier des charges léger.
- Rédiger des prompts efficaces et piloter les assistants et agents IA (Claude, ChatGPT, Claude Code, Codex, Cursor, Bolt.new).
- Choisir votre stack et concevoir l'architecture de votre application (Supabase, Next.js, Vercel, Airtable, n8n).
- Construire, versionner (Git, GitHub) et mettre en ligne votre MVP.
- Le tester avec de vrais utilisateurs, préparer son lancement et le présenter dans un pitch (Gamma).

## Adaptée à votre profil
Les contenus s'adaptent à votre profil : technique, non technique ou en reconversion. Les exemples, les outils conseillés et les exercices changent ; les objectifs restent les mêmes.$q$, $q$relecture$q$, $q$debutant$q$, '{}'::text[], $q$Porteurs de projet, entrepreneurs, intrapreneurs et personnes en reconversion qui veulent concevoir, construire et lancer un MVP numérique avec les outils d'IA — avec ou sans compétences en code.$q$, array[$q$Cadrer un problème, une cible et le périmètre d'un MVP dans un cahier des charges léger (PRD).$q$, $q$Rédiger des prompts efficaces et piloter des assistants et agents IA pour produire du contenu et du code.$q$, $q$Choisir une stack adaptée et concevoir l'architecture d'une application (données, authentification, sécurité, intégrations).$q$, $q$Construire, versionner et déployer en ligne un MVP fonctionnel.$q$, $q$Tester le MVP avec des utilisateurs, préparer son lancement et présenter son projet dans un pitch.$q$]::text[], $q$Aucun prérequis technique. Savoir utiliser un ordinateur et un navigateur web, disposer d'une connexion internet stable et d'un projet, même à l'état d'idée. Un questionnaire de positionnement est proposé au démarrage.$q$, 50, 0, 20, false, 183, true, (select coalesce(array_agg(id order by start_at), '{}'::text[]) from crm.sessions where kind = 'startup_week'), array[$q$MVP$q$, $q$IA$q$, $q$No-code$q$, $q$Supabase$q$, $q$Next.js$q$, $q$Prompt$q$]::text[], (select coalesce(array_agg(id order by created_at), '{}'::text[]) from crm.team_members where role = 'admin' and active), '{}'::text[], true, $q$Questionnaire de positionnement à l'entrée ; quiz évalués à la fin de chaque module ; livrables corrigés par un formateur (cahier des charges, fiche stack, modèle de données, dossier d'architecture, prototype, MVP en ligne, protocole et grille de tests, landing page, pitch vidéo, roadmap) ; évaluation finale des acquis (quiz transversal et revue des livrables).$q$, $q$Assistance pédagogique : un formateur référent répond aux questions posées depuis Mon espace sous 48 h ouvrées et corrige les livrables. Assistance technique (accès, vidéos, compte) : contact@startupweek.tech, réponse sous 48 h ouvrées. Les connexions et les activités réalisées sont enregistrées pour le suivi de la progression et le certificat de réalisation.$q$, $q$Accès en ligne 24 h/24 pendant 6 mois, sur ordinateur (recommandé) ou tablette. Vidéos sous-titrées avec transcription. Rythme libre. Adaptations possibles (durée d'accès, format des évaluations, accompagnement renforcé) : contactez la référente handicap avant ou pendant la formation.$q$, 70, 80)
on conflict (id) do nothing;

insert into crm.academy_modules (id, course_id, position, title, summary, objectives)
values ($q$crs_mvp_ia_m00$q$, $q$crs_mvp_ia$q$, 0, $q$Bienvenue et positionnement$q$, $q$Comprendre le fonctionnement de la formation, faire le point sur votre profil et votre projet, et préparer un environnement de travail sûr et opérationnel.$q$, array[$q$Être capable d’expliquer le fonctionnement de la formation : progression séquentielle, assistance, évaluations et conditions d’obtention du certificat de réalisation.$q$, $q$Être capable d’identifier ses points forts et ses points d’attention de départ (numérique, IA, notions produit, maturité du projet) grâce au positionnement.$q$, $q$Être capable de présenter son projet, son profil et ses attentes de façon structurée.$q$, $q$Être capable de configurer un environnement de travail sécurisé et adapté à son profil : comptes, double authentification, gestionnaire de mots de passe, dossier projet.$q$]::text[])
on conflict (id) do nothing;

insert into crm.academy_modules (id, course_id, position, title, summary, objectives)
values ($q$crs_mvp_ia_m01$q$, $q$crs_mvp_ia$q$, 1, $q$Cadrer son problème et son MVP$q$, $q$Passer d’une idée à un MVP cadré : un problème étayé, une cible précise, une proposition de valeur claire, un périmètre réduit à un parcours clé, un PRD léger et une organisation agile du projet.$q$, array[$q$Être capable de formuler un énoncé de problème étayé par des preuves et d’identifier ses hypothèses les plus risquées.$q$, $q$Être capable de définir une cible et ses early adopters, puis de mener et synthétiser des entretiens de découverte en limitant les biais.$q$, $q$Être capable de rédiger une proposition de valeur, un one-liner et une différenciation crédibles.$q$, $q$Être capable de délimiter le périmètre d’un MVP (type de MVP, parcours clé, MoSCoW, hors périmètre) et de le formaliser dans un PRD d’une à deux pages.$q$, $q$Être capable d’organiser son projet en sprints d’une semaine à l’aide d’un backlog dans Notion.$q$]::text[])
on conflict (id) do nothing;

insert into crm.academy_modules (id, course_id, position, title, summary, objectives)
values ($q$crs_mvp_ia_m02$q$, $q$crs_mvp_ia$q$, 2, $q$Bien prompter$q$, $q$Comprendre ce que fait (et ne fait pas) un assistant IA, puis rédiger des prompts précis pour produire des textes, du code et des tâches déléguées à des agents. Vous repartez avec votre propre bibliothèque de prompts.$q$, array[$q$Être capable d'expliquer le fonctionnement et les limites d'un assistant IA (contexte, hallucinations, confidentialité) pour décider quoi lui confier.$q$, $q$Être capable de rédiger un prompt structuré (rôle, contexte, tâche, contraintes, format, exemples, critères de qualité) et de l'améliorer par itérations.$q$, $q$Être capable de piloter un outil de code assisté par IA à partir d'une spécification, en exigeant un plan, des étapes courtes, des tests et une relecture des modifications.$q$, $q$Être capable de déléguer une tâche à un agent IA en appliquant des règles de sécurité (permissions minimales, absence de secrets, validation humaine).$q$, $q$Être capable de constituer et de maintenir une bibliothèque de prompts réutilisables et versionnés pour son projet.$q$]::text[])
on conflict (id) do nothing;

insert into crm.academy_modules (id, course_id, position, title, summary, objectives)
values ($q$crs_mvp_ia_m03$q$, $q$crs_mvp_ia$q$, 3, $q$Choisir sa stack$q$, $q$Découvrir les familles d'outils pour construire un MVP, les critères de choix, trois stacks de référence et la méthode pour estimer coûts et limites. Vous repartez avec une fiche stack argumentée pour votre projet.$q$, array[$q$Être capable de situer un outil dans sa famille (base no-code, automatisation, générateur d'application, code assisté, framework, backend, hébergement, pilotage) et d'expliquer son rôle dans une application.$q$, $q$Être capable de comparer des options techniques à l'aide d'une matrice de décision pondérée adaptée à son projet.$q$, $q$Être capable de choisir une stack de départ parmi trois stacks de référence selon son profil, son délai et l'hypothèse à valider.$q$, $q$Être capable de construire un tableau de coûts prévisionnels à partir des pages tarifs officielles, en identifiant coûts à l'usage et coûts cachés.$q$, $q$Être capable de rédiger et de justifier la fiche stack de son MVP, avec sa trajectoire d'évolution.$q$]::text[])
on conflict (id) do nothing;

insert into crm.academy_modules (id, course_id, position, title, summary, objectives)
values ($q$crs_mvp_ia_m04$q$, $q$crs_mvp_ia$q$, 4, $q$Architecturer son app$q$, $q$Concevoir le plan de votre application avant de la construire : couches, modèle de données, rôles et règles d'accès, intégrations, sécurité, RGPD, et une documentation que vos outils IA sauront exploiter.$q$, array[$q$Être capable de décrire l'architecture de son MVP (front, back, base de données, services externes) et le trajet d'une requête clé.$q$, $q$Être capable de modéliser les données de son MVP (entités, types, relations, contraintes) en tableau, puis en SQL ou dans Airtable.$q$, $q$Être capable de définir les rôles, le mode d'authentification et les règles d'accès (RLS) de son application.$q$, $q$Être capable d'identifier les intégrations, les secrets et les obligations de sécurité et de RGPD de son MVP.$q$, $q$Être capable de rédiger un dossier d'architecture (ARCHITECTURE.md, instructions pour agents, décisions) exploitable par les outils IA.$q$]::text[])
on conflict (id) do nothing;

insert into crm.academy_modules (id, course_id, position, title, summary, objectives)
values ($q$crs_mvp_ia_m05$q$, $q$crs_mvp_ia$q$, 5, $q$Parcours utilisateur et maquettes$q$, $q$Décrire le parcours clé de votre MVP, le dessiner en wireframes, appliquer les bases d'une interface claire et accessible, puis générer un prototype cliquable avec l'IA et le tester rapidement.$q$, array[$q$Être capable de décrire le parcours utilisateur clé de son MVP, avec son chemin nominal, les états de chaque écran et ses cas limites.$q$, $q$Être capable de produire des wireframes basse fidélité des écrans du parcours clé, sur papier, dans Figma ou avec l'aide de l'IA.$q$, $q$Être capable d'appliquer les bases d'interface (hiérarchie, typographie, espacements, contraste, accessibilité) et de définir un système de design minimal.$q$, $q$Être capable de générer et d'améliorer par itérations un prototype cliquable avec un outil d'IA.$q$, $q$Être capable de conduire trois tests rapides de maquette et d'en tirer une liste de frictions priorisées.$q$]::text[])
on conflict (id) do nothing;

insert into crm.academy_modules (id, course_id, position, title, summary, objectives)
values ($q$crs_mvp_ia_m06$q$, $q$crs_mvp_ia$q$, 6, $q$Construire avec l'IA$q$, $q$Le module de production : vous organisez vos sprints de build, versionnez votre code, mettez en place Supabase, construisez le parcours clé avec un outil ou un agent de code IA, automatisez avec n8n, intégrez un LLM côté serveur et mettez votre MVP en ligne sur Vercel.$q$, array[$q$Être capable de planifier deux sprints de build en user stories livrables, avec une définition de « fini » explicite et vérifiable.$q$, $q$Être capable de versionner son projet avec Git et GitHub sans jamais exposer de secret, et de revenir à une version qui fonctionne.$q$, $q$Être capable de mettre en place une base Supabase sécurisée (tables, RLS, authentification) et d'en vérifier les règles avec deux comptes de test.$q$, $q$Être capable de construire et de débugger le parcours clé de son MVP en pilotant un outil ou un agent de code IA, en relisant chaque modification.$q$, $q$Être capable de déployer son MVP sur Vercel avec au moins une automatisation n8n et, si c'est pertinent, une fonctionnalité LLM appelée côté serveur.$q$]::text[])
on conflict (id) do nothing;

insert into crm.academy_modules (id, course_id, position, title, summary, objectives)
values ($q$crs_mvp_ia_m07$q$, $q$crs_mvp_ia$q$, 7, $q$Tester avec de vrais utilisateurs$q$, $q$Préparer, mener et analyser des tests utilisateurs sur votre MVP, puis mesurer l’usage réel pour décider quoi améliorer en priorité.$q$, array[$q$Être capable de distinguer un test d’utilisabilité d’un test de valeur et de choisir le test adapté à ce que vous voulez apprendre.$q$, $q$Être capable de rédiger un protocole de test complet : objectifs, hypothèses, tâches, script neutre, recrutement et consentement conforme au RGPD.$q$, $q$Être capable de mener cinq tests sans influencer les testeurs et de consigner les observations dans une grille exploitable.$q$, $q$Être capable de synthétiser les résultats, d’évaluer la gravité des problèmes et de les prioriser dans votre backlog Notion.$q$, $q$Être capable de définir un plan de marquage minimal, un entonnoir d’activation et un indicateur principal pour mesurer l’usage réel de votre MVP.$q$]::text[])
on conflict (id) do nothing;

insert into crm.academy_modules (id, course_id, position, title, summary, objectives)
values ($q$crs_mvp_ia_m08$q$, $q$crs_mvp_ia$q$, 8, $q$Lancer$q$, $q$Positionner votre offre, mettre en ligne une landing page qui convertit, écrire des messages justes, lancer vos premières expériences d’acquisition, piloter chaque semaine et poser les bases juridiques du lancement.$q$, array[$q$Être capable de formuler le positionnement de votre MVP en une phrase, appuyée par des preuves honnêtes.$q$, $q$Être capable de construire et de mettre en ligne une landing page à objectif unique, avec un formulaire de capture respectueux du RGPD.$q$, $q$Être capable de rédiger et de tester des messages orientés bénéfices, dans les mots de votre cible, avec l’aide de l’IA.$q$, $q$Être capable de concevoir, mener et trancher des expériences d’acquisition à petit budget, suivies dans un tableau de bord hebdomadaire.$q$, $q$Être capable d’identifier les obligations juridiques de base d’un lancement en France et les sources officielles à consulter.$q$]::text[])
on conflict (id) do nothing;

insert into crm.academy_modules (id, course_id, position, title, summary, objectives)
values ($q$crs_mvp_ia_m09$q$, $q$crs_mvp_ia$q$, 9, $q$Pitch, roadmap et évaluation finale$q$, $q$Présenter votre MVP de façon convaincante (deck, démo, pitch vidéo), planifier les 30 jours qui suivent la formation et valider l’ensemble de vos acquis lors de l’évaluation finale.$q$, array[$q$Être capable de construire un pitch structuré en 10 à 12 slides, appuyé sur des faits vérifiables.$q$, $q$Être capable de produire un deck avec un outil de génération comme Gamma à partir de son PRD et de sa trame, puis de le corriger et de l’harmoniser à la main.$q$, $q$Être capable d’enregistrer une démo du parcours clé intégrée à un pitch vidéo de 3 minutes.$q$, $q$Être capable d’élaborer une roadmap à 30 jours avec des priorités, des indicateurs et des rituels de suivi.$q$, $q$Être capable de mobiliser l’ensemble des acquis de la formation lors de l’évaluation finale.$q$]::text[])
on conflict (id) do nothing;

insert into crm.academy_lessons (id, course_id, module_id, position, title, summary, estimated_minutes, is_preview, blocks)
values ($q$crs_mvp_ia_m00_l01$q$, $q$crs_mvp_ia$q$, $q$crs_mvp_ia_m00$q$, 0, $q$Bienvenue dans StartupWeek Academy$q$, $q$Découvrir le fonctionnement de la formation : parcours, progression, assistance, évaluations et certificat.$q$, 15, true, $q$[{"id":"crs_mvp_ia_m00_l01_b_1","type":"texte","markdown":"À la fin de cette leçon, vous saurez comment fonctionne la formation, ce que l’on attend de vous et à qui vous adresser à chaque étape. Prenez un quart d’heure : ces repères vous feront gagner beaucoup de temps ensuite.\n\n## Une formation par projet\n\nStartupWeek Academy propose la version en ligne du bootcamp StartupWeek, qui permet de construire un MVP en 7 jours. Un MVP (*minimum viable product*, ou produit minimum viable) est la plus petite version de votre produit qui permet de vérifier, auprès de vrais utilisateurs, qu’il résout bien leur problème.\n\nIci, vous ne suivez pas des cours « pour savoir ». Vous construisez **votre** MVP, étape par étape. Chaque module se termine par des livrables qui font avancer votre projet : un problème cadré, un cahier des charges, des maquettes, une application en ligne, des retours d’utilisateurs, une page de lancement, un pitch. À la fin, vous repartez avec un produit testé et un plan pour la suite, pas seulement avec des notes.\n\n## Le fil rouge : Créno\n\nPour illustrer chaque notion, nous suivons un projet fictif, **Créno** : une application web de réservation et de paiement de séances pour coachs sportifs indépendants.\n\n- Le **coach** publie ses créneaux, gère ses clients et voit ses paiements.\n- Le **client** réserve une séance, la paie en ligne et peut l’annuler.\n- Le MVP de Créno se limite à l’essentiel : le coach publie ses créneaux, le client réserve et paie, un rappel automatique part la veille de la séance.\n\nCréno vous montre à quoi ressemble une réponse attendue. Ce n’est pas un modèle à copier : votre projet a sa propre cible et ses propres contraintes.\n\n## Le parcours en 10 modules\n\n| Module | Thème | Ce que vous produisez |\n| --- | --- | --- |\n| 0 | Bienvenue et positionnement | Votre présentation, un environnement de travail prêt |\n| 1 | Cadrer son problème et son MVP | Énoncé de problème, synthèse d’entretiens, PRD, backlog |\n| 2 | Bien prompter | Vos prompts de travail réutilisables |\n| 3 | Choisir sa stack | Le choix argumenté de vos outils |\n| 4 | Architecturer son app | Votre modèle de données et vos règles d’accès |\n| 5 | Parcours utilisateur et maquettes | Les maquettes de votre parcours clé |\n| 6 | Construire avec l’IA | Votre MVP en ligne |\n| 7 | Tester avec de vrais utilisateurs | Une synthèse de tests et des corrections |\n| 8 | Lancer | Une page de lancement et un plan d’acquisition |\n| 9 | Pitch, roadmap et évaluation finale | Deck, pitch vidéo, roadmap à 30 jours |\n\n## Comment se déroule votre progression\n\n- **Environ 50 heures d’activités**, estimées leçon par leçon : la durée affichée comprend la lecture, les vidéos, les exercices et les quiz.\n- **Une progression séquentielle** : la leçon suivante se débloque quand la leçon en cours est terminée. Cet ordre n’est pas arbitraire : chaque étape s’appuie sur la précédente.\n- **6 mois d’accès** à partir de l’ouverture de votre formation. À raison de 5 heures par semaine, vous terminez en une dizaine de semaines, ce qui laisse de la marge pour les imprévus.\n\n> [!tip] Bloquez dès aujourd’hui deux ou trois créneaux fixes par semaine dans votre agenda. La régularité compte davantage que la durée de chaque séance.\n\n## Des contenus adaptés à votre profil\n\nCertains contenus existent en plusieurs versions selon votre profil, défini lors de votre inscription :\n\n- **technique** (développeur, ingénieur, data…) : davantage de code et d’autonomie sur les outils de développement ;\n- **non technique** (entrepreneur, expert métier) : des outils sans code et des repères pour piloter l’IA sans programmer ;\n- **reconversion** : davantage de pas-à-pas, de vocabulaire expliqué et de points d’étape.\n\nLe tronc commun est identique pour tous : les variantes le complètent, elles ne le remplacent pas. Si votre profil ne vous semble pas adapté, signalez-le à votre formateur.\n\n## Assistance pédagogique et technique\n\nUn **formateur référent** vous accompagne pendant toute la formation. Vous le contactez depuis la **messagerie de Mon espace**, pour une question sur le contenu, un blocage technique ou un problème d’accès. Il vous répond **sous 48 heures ouvrées**.\n\nPour obtenir une réponse utile du premier coup, précisez la leçon concernée, ce que vous cherchiez à faire, ce que vous avez essayé et le message d’erreur exact, sans jamais y inclure de mot de passe ni de clé secrète.\n\n## Comment vous êtes évalué\n\n- **Les quiz d’auto-vérification**, dans les leçons : non notés, ils vous permettent de vérifier votre compréhension.\n- **Les quiz de fin de module** : notés, ils mesurent vos acquis. Le score attendu est indiqué dans le livret d’accueil.\n- **Les livrables corrigés** : certains exercices sont relus par votre formateur, selon des critères de réussite affichés avec chaque consigne.\n- **L’évaluation finale** (module 9) : un quiz transversal et vos livrables finaux (MVP en ligne, deck, vidéo de pitch, roadmap).\n\n## Le certificat de réalisation\n\nLe certificat de réalisation atteste que vous avez suivi la formation. Il est délivré lorsque vous atteignez la progression minimale précisée dans le livret d’accueil. Pour une formation à distance, l’organisme doit pouvoir prouver ce suivi : vos connexions et vos activités (leçons terminées, quiz, exercices remis) sont donc tracées.\n\n## Accessibilité et réclamations\n\nVous êtes en situation de handicap ou avez besoin d’un aménagement (rythme, format des contenus, outils) ? Contactez la **référente handicap** : ses coordonnées figurent dans le livret d’accueil. Plus tôt vous en parlez, plus tôt une solution peut être étudiée.\n\nUne difficulté ou une insatisfaction que votre formateur n’a pas pu résoudre ? Le livret d’accueil décrit la **procédure de réclamation** : chaque réclamation est enregistrée et reçoit une réponse."},{"id":"crs_mvp_ia_m00_l01_b_2","type":"texte","markdown":"## Votre parcours en tant que profil technique\n\nVous savez coder : c’est un atout, et un piège. Le piège, c’est de passer trop vite à la construction, ou de bâtir une architecture trop ambitieuse pour un MVP. Les modules 1 à 5 vous demandent de cadrer avant de coder : jouez le jeu, ils vous éviteront de réécrire votre application.\n\nAu module 6, vous travaillerez avec Next.js, Supabase et Vercel, assisté par des agents de code comme Claude Code, Codex ou Cursor. Votre valeur ajoutée sera de bien les piloter : découper les demandes, relire le code produit, tester, sécuriser.","personas":["tech"]},{"id":"crs_mvp_ia_m00_l01_b_3","type":"texte","markdown":"## Votre parcours en tant que profil non technique\n\nVous n’avez pas besoin de savoir programmer pour suivre cette formation. Vous apprendrez à décrire précisément ce que vous voulez, puis à faire construire votre application par un outil comme Bolt.new, relié à une base de données Supabase.\n\nVotre expertise métier est votre meilleur atout : vous connaissez vos futurs utilisateurs et leurs problèmes. Les modules de cadrage (1 à 5) sont ceux où vous ferez la différence. Au module 6, suivez les pas-à-pas et sollicitez votre formateur dès qu’un blocage dure.","personas":["non_tech"]},{"id":"crs_mvp_ia_m00_l01_b_4","type":"texte","markdown":"## Votre parcours en tant que personne en reconversion\n\nBeaucoup de mots vont vous sembler nouveaux : c’est normal. Chaque terme est défini la première fois qu’il apparaît, et plusieurs leçons vous proposent un petit glossaire. Vous n’avez pas à tout retenir d’un coup.\n\nAvancez régulièrement, même par petites séances, et notez vos questions au fil de l’eau pour les poser à votre formateur. Votre parcours antérieur compte : la connaissance d’un métier, d’un public ou d’un secteur est souvent le point de départ des meilleurs projets.","personas":["reconversion"]},{"id":"crs_mvp_ia_m00_l01_b_5","type":"video","title":"Bienvenue : comment se déroule votre formation","url":"","durationMinutes":5,"script":"- Accueil face caméra : présentation de StartupWeek et de l’objectif de la formation (repartir avec un MVP testé et un plan pour la suite).\n- Le principe de la formation par projet : chaque module fait avancer le produit de l’apprenant, pas un exercice abstrait.\n- Présentation rapide de Créno, le fil rouge : les deux rôles (coach, client) et le parcours clé du MVP.\n- Démonstration à l’écran de Mon espace : progression séquentielle, durée estimée des leçons, exercices, messagerie.\n- L’assistance : formateur référent, réponse sous 48 heures ouvrées, comment rédiger une question efficace.\n- Évaluations et certificat de réalisation en une minute, renvoi vers le livret d’accueil.\n- Conseil de rythme : deux à trois créneaux fixes par semaine ; rendez-vous à la leçon suivante."},{"id":"crs_mvp_ia_m00_l01_b_6","type":"ressource","resourceId":"res_livret","note":"Le livret d’accueil rassemble les informations pratiques : contacts, référente handicap, règles de fonctionnement, seuils d’évaluation et de certificat, procédure de réclamation. Gardez-le à portée de main."},{"id":"crs_mvp_ia_m00_l01_b_7","type":"checklist","title":"Avant de commencer","items":[{"id":"crs_mvp_ia_m00_l01_b_7_i_1","label":"J’ai lu le livret d’accueil et je sais où trouver le contact de la référente handicap."},{"id":"crs_mvp_ia_m00_l01_b_7_i_2","label":"J’ai bloqué deux ou trois créneaux fixes par semaine dans mon agenda."},{"id":"crs_mvp_ia_m00_l01_b_7_i_3","label":"J’ai repéré la messagerie de Mon espace pour contacter mon formateur référent."},{"id":"crs_mvp_ia_m00_l01_b_7_i_4","label":"Je sais que chaque leçon débloque la suivante une fois terminée."},{"id":"crs_mvp_ia_m00_l01_b_7_i_5","label":"Je connais la date de fin de mon accès (6 mois après l’ouverture)."},{"id":"crs_mvp_ia_m00_l01_b_7_i_6","label":"J’ai une idée de projet, même floue, sur laquelle travailler tout au long de la formation."}]}]$q$::jsonb)
on conflict (id) do nothing;

insert into crm.academy_lessons (id, course_id, module_id, position, title, summary, estimated_minutes, is_preview, blocks)
values ($q$crs_mvp_ia_m00_l02$q$, $q$crs_mvp_ia$q$, $q$crs_mvp_ia_m00$q$, 1, $q$Votre positionnement de départ$q$, $q$Faire le point sur vos acquis de départ avec un quiz non évalué et présenter votre projet à votre formateur.$q$, 30, false, $q$[{"id":"crs_mvp_ia_m00_l02_b_1","type":"texte","markdown":"À la fin de cette leçon, vous saurez où vous en êtes au départ sur quatre axes (numérique, intelligence artificielle, notions produit, maturité du projet), et vous aurez présenté votre projet à votre formateur.\n\n## Pourquoi un positionnement ?\n\nLes apprenants arrivent avec des profils très différents : certains codent depuis dix ans, d’autres n’ont jamais utilisé d’assistant IA ; certains ont déjà des clients, d’autres une simple intuition. Le positionnement sert à deux choses :\n\n- **pour vous** : repérer vos points forts et les notions à consolider, afin d’y consacrer plus de temps quand elles arriveront ;\n- **pour votre formateur** : adapter son accompagnement. Il lira votre présentation et vos points d’attention avant de corriger vos premiers livrables.\n\n## Un quiz non évalué\n\nLe quiz de cette leçon **ne compte pas dans votre évaluation**. Chaque question a une réponse attendue, mais ici la « bonne réponse » sert d’**auto-diagnostic** : si vous la trouvez, la notion est probablement acquise ; sinon, c’est un point à surveiller. Après chaque réponse, lisez l’explication : elle précise où la notion est travaillée dans la formation.\n\nRépondez spontanément, sans chercher sur internet ni demander à une IA. Un positionnement « gonflé » ne vous servirait à rien : c’est votre point de départ réel qui compte.\n\n| Axe | Ce que l’on vérifie | Où c’est travaillé |\n| --- | --- | --- |\n| Autonomie numérique | Partager un document, sécuriser un compte, lire une adresse web | Module 0, puis tout au long de la formation |\n| Intelligence artificielle | Savoir ce qu’est un prompt, connaître les limites et les risques d’un assistant IA | Modules 0 et 2 |\n| Notions produit | MVP, user story | Module 1 |\n| Maturité du projet | Distinguer ce qui est prouvé de ce qui reste une hypothèse | Module 1 |\n\n## Lire votre résultat\n\nComptez vos réponses attendues sur les 10 questions :\n\n- **8 à 10** : vous avez de bonnes bases. Profitez-en pour aller plus loin dans les exercices et soigner vos livrables.\n- **5 à 7** : c’est un point de départ courant. Notez les notions manquées : elles seront traitées en détail dans les modules indiqués.\n- **0 à 4** : vous découvrez beaucoup de notions, et la formation est faite pour cela. Suivez les leçons dans l’ordre, prenez le temps des variantes pas-à-pas et écrivez à votre formateur dès qu’un point reste flou.\n\nAucun résultat n’est « mauvais ». Un projet encore au stade de l’idée, par exemple, n’est pas un handicap : le module 1 vous apprend précisément à le cadrer.\n\n## Présenter votre projet\n\nAprès le quiz, vous rédigerez une courte présentation. Elle a trois objectifs : clarifier votre projet pour vous-même, donner à votre formateur le contexte dont il a besoin, et formuler vos attentes pour pouvoir mesurer, à la fin, le chemin parcouru.\n\nPas besoin d’un texte parfait. Écrivez comme vous parleriez à quelqu’un qui découvre votre projet : phrases courtes, exemples concrets, pas de superlatifs. Si votre idée est encore floue, dites-le : c’est une information utile.\n\nVoici, à titre d’exemple fictif, le début de la présentation de la porteuse de projet de Créno :\n\n> [!info] « Je suis ancienne coach sportive, sans compétence en code. Je veux aider les coachs indépendants à gérer leurs réservations et leurs paiements sans passer leurs soirées sur leur téléphone. J’ai parlé du problème avec quatre collègues, mais rien n’est encore construit. J’attends de la formation qu’elle m’aide à réduire mon idée à l’essentiel et à mettre en ligne une première version que je pourrai tester. »"},{"id":"crs_mvp_ia_m00_l02_b_2","type":"quiz","title":"Quiz de positionnement (non évalué)","graded":false,"questions":[{"id":"crs_mvp_ia_m00_l02_b_2_q_1","prompt":"Vous devez transmettre à votre formateur un document de travail, consultable en ligne et toujours à jour. Quelle est la meilleure option ?","kind":"unique","options":[{"id":"crs_mvp_ia_m00_l02_b_2_q_1_o_1","label":"Un lien de partage en lecture seule vers le document (Notion, Google Docs…)","correct":true},{"id":"crs_mvp_ia_m00_l02_b_2_q_1_o_2","label":"Une capture d’écran de chaque page","correct":false},{"id":"crs_mvp_ia_m00_l02_b_2_q_1_o_3","label":"Le fichier en pièce jointe, renvoyé à chaque modification","correct":false},{"id":"crs_mvp_ia_m00_l02_b_2_q_1_o_4","label":"Vos identifiants de connexion, pour qu’il aille le consulter lui-même","correct":false}],"explanation":"Un lien en lecture seule donne toujours accès à la dernière version, sans exposer vos identifiants. Si vous avez hésité, retenez ce réflexe : vous l’utiliserez pour la plupart des livrables de la formation."},{"id":"crs_mvp_ia_m00_l02_b_2_q_2","prompt":"Qu’est-ce que la double authentification ?","kind":"unique","options":[{"id":"crs_mvp_ia_m00_l02_b_2_q_2_o_1","label":"Une seconde preuve d’identité (code, notification, clé) demandée en plus du mot de passe","correct":true},{"id":"crs_mvp_ia_m00_l02_b_2_q_2_o_2","label":"Le fait d’avoir deux comptes sur le même service","correct":false},{"id":"crs_mvp_ia_m00_l02_b_2_q_2_o_3","label":"Un mot de passe deux fois plus long","correct":false},{"id":"crs_mvp_ia_m00_l02_b_2_q_2_o_4","label":"La connexion simultanée sur deux appareils","correct":false}],"explanation":"La double authentification protège vos comptes même si votre mot de passe est dérobé. Vous l’activerez dans la leçon suivante."},{"id":"crs_mvp_ia_m00_l02_b_2_q_3","prompt":"Dans l’adresse https://app.exemple.fr/reservations, que désigne « app.exemple.fr » ?","kind":"unique","options":[{"id":"crs_mvp_ia_m00_l02_b_2_q_3_o_1","label":"Le nom de domaine (ici un sous-domaine) du site","correct":true},{"id":"crs_mvp_ia_m00_l02_b_2_q_3_o_2","label":"Un dossier de votre ordinateur","correct":false},{"id":"crs_mvp_ia_m00_l02_b_2_q_3_o_3","label":"Le nom du navigateur utilisé","correct":false},{"id":"crs_mvp_ia_m00_l02_b_2_q_3_o_4","label":"Le nom de l’utilisateur connecté","correct":false}],"explanation":"Le nom de domaine identifie le site ; « /reservations » est le chemin d’une page. Ces notions reviennent au module 6, quand vous mettrez votre application en ligne."},{"id":"crs_mvp_ia_m00_l02_b_2_q_4","prompt":"Qu’est-ce qu’un prompt ?","kind":"unique","options":[{"id":"crs_mvp_ia_m00_l02_b_2_q_4_o_1","label":"La consigne, rédigée en langage naturel, que l’on donne à un assistant IA","correct":true},{"id":"crs_mvp_ia_m00_l02_b_2_q_4_o_2","label":"Un langage de programmation réservé aux développeurs","correct":false},{"id":"crs_mvp_ia_m00_l02_b_2_q_4_o_3","label":"Un abonnement payant à un service d’IA","correct":false},{"id":"crs_mvp_ia_m00_l02_b_2_q_4_o_4","label":"Un message d’erreur affiché par un logiciel","correct":false}],"explanation":"Le prompt est la consigne donnée à l’IA. Savoir le rédiger avec précision est l’objet du module 2."},{"id":"crs_mvp_ia_m00_l02_b_2_q_5","prompt":"Un assistant IA vous répond avec assurance, en citant un chiffre de marché et une source. Quelle attitude adopter ?","kind":"unique","options":[{"id":"crs_mvp_ia_m00_l02_b_2_q_5_o_1","label":"Vérifier le chiffre et la source, car un modèle de langage peut produire des informations fausses de façon convaincante","correct":true},{"id":"crs_mvp_ia_m00_l02_b_2_q_5_o_2","label":"L’utiliser tel quel : une IA ne cite pas de source inexistante","correct":false},{"id":"crs_mvp_ia_m00_l02_b_2_q_5_o_3","label":"Le reformuler pour qu’il ait l’air plus fiable","correct":false},{"id":"crs_mvp_ia_m00_l02_b_2_q_5_o_4","label":"Poser la même question une seconde fois : si la réponse est identique, elle est juste","correct":false}],"explanation":"Les modèles de langage peuvent « halluciner », c’est-à-dire produire des faits ou des sources inventés. Tout chiffre destiné à un livrable doit être vérifié à sa source. Vous approfondirez ce point au module 2."},{"id":"crs_mvp_ia_m00_l02_b_2_q_6","prompt":"Parmi ces informations, laquelle pouvez-vous coller sans risque dans un prompt ?","kind":"unique","options":[{"id":"crs_mvp_ia_m00_l02_b_2_q_6_o_1","label":"La description anonymisée du parcours de votre utilisateur type","correct":true},{"id":"crs_mvp_ia_m00_l02_b_2_q_6_o_2","label":"La clé secrète de votre compte de paiement","correct":false},{"id":"crs_mvp_ia_m00_l02_b_2_q_6_o_3","label":"Le fichier de vos contacts avec noms et téléphones","correct":false},{"id":"crs_mvp_ia_m00_l02_b_2_q_6_o_4","label":"Le mot de passe de votre messagerie","correct":false}],"explanation":"Secrets et données personnelles ne doivent jamais figurer dans un prompt. La leçon suivante détaille les bons réflexes."},{"id":"crs_mvp_ia_m00_l02_b_2_q_7","prompt":"Quel élément constitue la meilleure preuve qu’un problème est réel pour votre cible ?","kind":"unique","options":[{"id":"crs_mvp_ia_m00_l02_b_2_q_7_o_1","label":"Des personnes de la cible décrivent spontanément le problème et ce qu’elles font déjà pour le contourner","correct":true},{"id":"crs_mvp_ia_m00_l02_b_2_q_7_o_2","label":"Vos proches trouvent l’idée excellente","correct":false},{"id":"crs_mvp_ia_m00_l02_b_2_q_7_o_3","label":"Vous n’avez trouvé aucun concurrent","correct":false},{"id":"crs_mvp_ia_m00_l02_b_2_q_7_o_4","label":"Un assistant IA confirme que le marché est très important","correct":false}],"explanation":"Ce que les gens font vaut plus que ce qu’ils disent. Si vous avez hésité, le module 1 vous apprend à distinguer signaux forts et signaux faibles."},{"id":"crs_mvp_ia_m00_l02_b_2_q_8","prompt":"Lequel de ces projets est le plus prêt à entrer en phase de construction ?","kind":"unique","options":[{"id":"crs_mvp_ia_m00_l02_b_2_q_8_o_1","label":"Le problème, la cible et un parcours principal sont écrits, et plusieurs utilisateurs potentiels ont été interrogés","correct":true},{"id":"crs_mvp_ia_m00_l02_b_2_q_8_o_2","label":"L’idée est claire dans la tête du porteur de projet, mais rien n’est écrit","correct":false},{"id":"crs_mvp_ia_m00_l02_b_2_q_8_o_3","label":"Le nom et le logo sont trouvés","correct":false},{"id":"crs_mvp_ia_m00_l02_b_2_q_8_o_4","label":"La liste des fonctionnalités compte déjà une cinquantaine d’éléments","correct":false}],"explanation":"Un projet prêt à construire a un problème écrit, une cible précise et des premiers retours. Si ce n’est pas encore votre cas, pas d’inquiétude : c’est l’objet du module 1."},{"id":"crs_mvp_ia_m00_l02_b_2_q_9","prompt":"Que désigne un MVP (produit minimum viable) ?","kind":"unique","options":[{"id":"crs_mvp_ia_m00_l02_b_2_q_9_o_1","label":"La plus petite version du produit qui permet d’apprendre auprès de vrais utilisateurs","correct":true},{"id":"crs_mvp_ia_m00_l02_b_2_q_9_o_2","label":"Une version complète du produit, mais à prix réduit","correct":false},{"id":"crs_mvp_ia_m00_l02_b_2_q_9_o_3","label":"Une maquette non fonctionnelle destinée aux investisseurs","correct":false},{"id":"crs_mvp_ia_m00_l02_b_2_q_9_o_4","label":"Le meilleur produit du marché dans sa catégorie","correct":false}],"explanation":"Le MVP sert à apprendre vite, avec un minimum d’effort. Vous en définirez le périmètre au module 1."},{"id":"crs_mvp_ia_m00_l02_b_2_q_10","prompt":"Qu’est-ce qu’une user story ?","kind":"unique","options":[{"id":"crs_mvp_ia_m00_l02_b_2_q_10_o_1","label":"Une phrase qui décrit un besoin du point de vue d’un utilisateur : « En tant que…, je veux…, afin de… »","correct":true},{"id":"crs_mvp_ia_m00_l02_b_2_q_10_o_2","label":"Le témoignage d’un client satisfait publié sur un site","correct":false},{"id":"crs_mvp_ia_m00_l02_b_2_q_10_o_3","label":"L’historique des connexions d’un utilisateur","correct":false},{"id":"crs_mvp_ia_m00_l02_b_2_q_10_o_4","label":"Le récit de la création de l’entreprise","correct":false}],"explanation":"Les user stories structurent votre cahier des charges et votre backlog. Vous les rédigerez au module 1."}]},{"id":"crs_mvp_ia_m00_l02_b_3","type":"texte","markdown":"## Conseils pour votre présentation (profil technique)\n\nPrécisez vos langages et frameworks, votre expérience des agents de code et des outils de déploiement. Surtout, dites aussi ce que vous n’avez jamais fait : entretiens avec des clients, maquettage, rédaction d’une page de vente, acquisition. C’est souvent là que se joue la réussite d’un MVP, et c’est là que votre formateur pourra vous être le plus utile.","personas":["tech"]},{"id":"crs_mvp_ia_m00_l02_b_4","type":"texte","markdown":"## Conseils pour votre présentation (profil non technique)\n\nDécrivez votre expertise métier et votre réseau : combien de futurs utilisateurs pouvez-vous contacter facilement ? Citez les outils que vous maîtrisez déjà (tableur, Notion, outils sans code, assistants IA) et ceux qui vous inquiètent. Votre formateur saura ainsi où vous accompagner au moment de la construction.","personas":["non_tech"]},{"id":"crs_mvp_ia_m00_l02_b_5","type":"texte","markdown":"## Conseils pour votre présentation (profil reconversion)\n\nDites d’où vous venez et ce qui motive votre changement. Listez vos compétences transférables : gestion de projet, relation client, organisation, connaissance d’un secteur ou d’un public. Nommez aussi ce qui vous inquiète (la technique, le temps, la légitimité) : votre formateur ne peut vous aider que sur ce qu’il connaît.","personas":["reconversion"]},{"id":"crs_mvp_ia_m00_l02_b_6","type":"exercice","title":"Présentez votre projet, votre profil et vos attentes","instructions":"Rédigez une présentation de 250 à 400 mots, en quatre parties, directement dans le champ de réponse.\n\n1. **Votre projet** : le problème que vous voulez résoudre, pour qui, et votre idée de solution (5 lignes maximum). Indiquez son stade : simple idée, idée déjà discutée avec de futurs utilisateurs, prototype, produit déjà utilisé.\n2. **Votre profil** : votre parcours en deux ou trois phrases, les outils numériques et IA que vous utilisez déjà, et le temps que vous pouvez consacrer à la formation chaque semaine.\n3. **Votre positionnement** : votre nombre de réponses attendues au quiz et les deux ou trois notions que vous voulez consolider.\n4. **Vos attentes** : trois résultats concrets que vous attendez de la formation, et vos éventuelles contraintes (agenda, matériel, besoin d’aménagement).\n\nSi vous travaillez en binôme, chacun remet sa propre présentation et mentionne son binôme.\n\n> [!tip] Un besoin d’aménagement lié à un handicap peut aussi être adressé directement, et en toute confidentialité, à la référente handicap : ses coordonnées figurent dans le livret d’accueil.","deliverable":"texte","estimatedMinutes":15,"review":"formateur","rubric":["Le problème, la cible et l’idée de solution sont décrits concrètement.","Le stade du projet est indiqué honnêtement.","Le profil, le temps disponible et les notions à consolider sont précisés.","Au moins trois attentes concrètes sont formulées."]}]$q$::jsonb)
on conflict (id) do nothing;

insert into crm.academy_lessons (id, course_id, module_id, position, title, summary, estimated_minutes, is_preview, blocks)
values ($q$crs_mvp_ia_m00_l03$q$, $q$crs_mvp_ia$q$, $q$crs_mvp_ia_m00$q$, 2, $q$Préparer vos outils$q$, $q$Créer et sécuriser les comptes utiles à la formation, puis organiser votre espace de travail selon votre profil.$q$, 45, false, $q$[{"id":"crs_mvp_ia_m00_l03_b_1","type":"texte","markdown":"À la fin de cette leçon, vous aurez créé les comptes utiles à la formation, sécurisé vos accès et organisé votre espace de travail. Ce temps investi maintenant vous évitera d’être bloqué au moment où vous voudrez avancer sur votre projet.\n\n## Les comptes à créer, et pourquoi\n\nVous n’avez pas besoin de tout maîtriser aujourd’hui. L’objectif est d’ouvrir les comptes, pas d’apprendre les outils : chacun sera présenté dans le module où il sert.\n\n| Outil | À quoi il sert dans la formation | Quand |\n| --- | --- | --- |\n| Claude | Assistant IA pour réfléchir, rédiger, analyser et, avec Claude Code, écrire du code | Dès le module 1 |\n| ChatGPT | Second assistant IA, utile pour comparer les réponses ; Codex en est la déclinaison pour le code | Dès le module 1 |\n| Notion | Espace de travail du projet : notes, entretiens, PRD, backlog | Dès le module 1 |\n| GitHub | Hébergement du code et historique de ses versions | Module 6 |\n| Supabase | Base de données, authentification des utilisateurs, règles d’accès | Modules 4 et 6 |\n| Vercel | Mise en ligne de votre application | Module 6 |\n| Cursor ou Bolt.new | Construire l’application avec l’IA : Cursor est un éditeur de code (profil technique), Bolt.new fonctionne dans le navigateur (autres profils) | Module 6 |\n\nD’autres outils viendront plus tard, inutile de les créer maintenant : **Airtable** (une base de données qui ressemble à un tableur) et **n8n** (automatisation de tâches, comme l’envoi de rappels) au module 6, **Gamma** (création de présentations) au module 9.\n\nLa plupart de ces outils proposent une formule gratuite ou d’essai suffisante pour démarrer. Les conditions changent souvent : consultez la page tarifs de chaque outil au moment de créer votre compte, et ne souscrivez un abonnement que lorsque vous en avez réellement besoin.\n\n## Comptes professionnels ou personnels ?\n\nCréez vos comptes avec une **adresse e-mail dédiée au projet** : une adresse professionnelle si vous en avez une, sinon une nouvelle adresse. Vos outils seront ainsi regroupés, faciles à transmettre à un futur associé, et séparés de votre vie privée.\n\nSi vous utilisez l’ordinateur ou les comptes de votre employeur, vérifiez d’abord ses règles : certaines entreprises interdisent les outils d’IA externes ou l’installation de logiciels.\n\n## Sécuriser vos accès\n\n### Un gestionnaire de mots de passe\n\nUn gestionnaire de mots de passe est un logiciel qui génère et mémorise un mot de passe long et différent pour chaque service. Vous ne retenez plus qu’un seul mot de passe, le « mot de passe maître ». Votre navigateur en intègre un ; des applications dédiées existent aussi. L’essentiel : ne jamais réutiliser le même mot de passe sur deux services.\n\n### La double authentification\n\nLa double authentification (on dit aussi 2FA, ou authentification à deux facteurs) ajoute une seconde preuve d’identité au mot de passe : un code affiché par une application d’authentification, une notification sur votre téléphone ou une clé physique. Activez-la en priorité sur votre adresse e-mail, qui permet de réinitialiser tout le reste, puis sur GitHub, Supabase et Vercel, qui hébergeront votre code et vos données. Conservez les codes de secours dans votre gestionnaire de mots de passe.\n\n### Ce que vous ne collez jamais dans un prompt\n\nTout ce que vous collez dans un prompt quitte votre ordinateur et est traité par un service externe. N’y mettez donc jamais :\n\n- **des secrets** : mots de passe, clés d’API (codes qui donnent accès à un service ou à vos données), jetons de connexion, fichiers de configuration qui en contiennent ;\n- **des données personnelles de tiers** : noms, e-mails, téléphones ou notes d’entretien nominatives de vos clients, testeurs ou contacts ;\n- **des informations confidentielles** : contrats, chiffres d’un partenaire, données de votre employeur.\n\nRemplacez-les par des marqueurs neutres : [CLIENT_1], [CLÉ_MASQUÉE], « une coach de 35 ans ». Vérifiez aussi, dans les paramètres de confidentialité de chaque assistant, si vos conversations peuvent servir à améliorer les modèles, et réglez cette option selon vos besoins.\n\n> [!warning] Si une clé secrète a été collée dans un prompt, un message ou un dépôt de code public, considérez-la comme compromise : révoquez-la et générez-en une nouvelle depuis le tableau de bord du service concerné.\n\n## Organiser votre espace de travail\n\nUn projet de MVP produit vite beaucoup de fichiers : notes d’entretien, captures, exports, maquettes, textes. Mettez en place dès maintenant une organisation simple.\n\n**Sur votre ordinateur**, créez un dossier projet avec un sous-dossier par grande étape :\n\n```text\nmon-projet/\n  01-cadrage/\n  02-maquettes/\n  03-produit/\n  04-tests/\n  05-lancement/\n  06-pitch/\n```\n\nNommez vos fichiers avec la date en tête, au format AAAA-MM-JJ (par exemple « AAAA-MM-JJ_synthese-entretiens_v1 ») : ils se trieront d’eux-mêmes dans l’ordre chronologique.\n\n**Dans Notion**, créez une page « Mon MVP » avec cinq sous-pages : Journal de bord, Entretiens, PRD, Backlog et Ressources. Vous les remplirez au fil des modules ; le backlog sera construit au module 1.\n\n**Un journal de bord** : à la fin de chaque séance de travail, notez en trois lignes ce que vous avez fait, ce qui vous bloque et la prochaine action. C’est le meilleur moyen de reprendre vite après une pause, et une matière précieuse pour vos échanges avec votre formateur."},{"id":"crs_mvp_ia_m00_l03_b_2","type":"video","title":"Votre boîte à outils : à quoi sert chaque compte","url":"","durationMinutes":6,"script":"- Pourquoi préparer ses outils avant de commencer : éviter de perdre une séance de travail en création de comptes au module 6.\n- Démonstration à l’écran : création d’un compte avec l’adresse du projet, puis activation de la double authentification.\n- Le gestionnaire de mots de passe en pratique : générer, enregistrer et retrouver un mot de passe.\n- Tour rapide des outils et de leur rôle dans Créno : Claude et ChatGPT, Notion, GitHub, Supabase, Vercel.\n- Les deux chemins de construction : Cursor et Claude Code (profil technique), Bolt.new dans le navigateur (autres profils).\n- Ce que l’on ne colle jamais dans un prompt : démonstration du masquage d’une clé et d’un nom avant envoi.\n- Mise en place du dossier projet et de la page Notion « Mon MVP »."},{"id":"crs_mvp_ia_m00_l03_b_3","type":"texte","markdown":"## Profil technique : votre environnement de développement\n\nInstallez ou mettez à jour les outils suivants, en suivant la documentation officielle de chacun :\n\n1. **Git**, le logiciel de gestion de versions ([git-scm.com](https://git-scm.com)).\n2. **Node.js**, dans sa version LTS (version à support long, la plus stable), qui fournit aussi npm.\n3. **Cursor**, éditeur de code intégrant l’IA ([cursor.com](https://cursor.com)). Vous pouvez rester sur votre éditeur habituel : les principes restent les mêmes.\n4. **Claude Code**, l’agent de code d’Anthropic qui s’utilise en ligne de commande : suivez la procédure d’installation de sa documentation officielle, puis connectez-vous avec votre compte. Codex, chez OpenAI, joue un rôle comparable ; la formation montre surtout Claude Code, mais les méthodes sont transposables.\n\nVérifiez ensuite que tout répond dans un terminal :\n\n```bash\ngit --version\nnode --version\nnpm --version\nclaude --version\n```\n\nConfigurez enfin votre identité Git, qui apparaîtra dans l’historique de vos commits :\n\n```bash\ngit config --global user.name \"Prénom Nom\"\ngit config --global user.email \"adresse-du-projet@exemple.fr\"\n```\n\nReliez votre poste à GitHub (clé SSH ou authentification HTTPS, selon la documentation de GitHub) et testez en clonant un dépôt. Aucun secret ne doit jamais être commité : prenez dès maintenant l’habitude d’un fichier `.env` listé dans le `.gitignore`.","personas":["tech"]},{"id":"crs_mvp_ia_m00_l03_b_4","type":"texte","markdown":"## Profil non technique : rien à installer\n\nVous construirez votre application avec **Bolt.new**, directement dans votre navigateur : aucune installation n’est nécessaire. Vous décrivez ce que vous voulez en langage naturel, l’outil génère l’application et vous en montre un aperçu.\n\nPour aujourd’hui :\n\n1. Utilisez un navigateur récent et à jour, sur un ordinateur plutôt que sur une tablette.\n2. Créez votre compte sur [bolt.new](https://bolt.new) avec l’adresse e-mail du projet.\n3. Faites un premier essai sans enjeu : demandez une page d’accueil simple pour votre projet, observez le résultat, puis supprimez ce projet d’essai si vous le souhaitez.\n4. Créez vos comptes Supabase et GitHub, même si vous ne les utiliserez qu’au module 6 : Bolt.new propose de s’y connecter pour stocker vos données et sauvegarder votre code, ce que vous mettrez en place à ce moment-là.\n\nComme pour tout assistant IA, ne décrivez jamais de vraies personnes dans vos demandes à Bolt.new : utilisez des exemples fictifs.","personas":["non_tech"]},{"id":"crs_mvp_ia_m00_l03_b_5","type":"texte","markdown":"## Profil reconversion : pas à pas et glossaire\n\nProcédez dans cet ordre, un outil à la fois, en comptant quelques minutes par compte.\n\n1. Choisissez ou créez l’adresse e-mail du projet, et activez-y la double authentification.\n2. Installez ou activez un gestionnaire de mots de passe, puis enregistrez-y le mot de passe de cette adresse.\n3. Créez vos comptes Claude et ChatGPT. Posez une première question simple à chacun, par exemple : « Explique-moi ce qu’est un MVP en cinq lignes. »\n4. Créez votre compte Notion et la page « Mon MVP ».\n5. Créez vos comptes GitHub, Supabase et Vercel. Vous n’avez rien à y faire pour l’instant.\n6. Créez votre compte Bolt.new.\n7. Notez dans votre journal de bord ce qui a fonctionné et ce qui vous a posé problème.\n\n| Mot | Signification |\n| --- | --- |\n| Compte | Votre accès personnel à un service en ligne, protégé par un identifiant et un mot de passe |\n| Navigateur | Le logiciel qui affiche les sites web (Chrome, Edge, Firefox, Safari…) |\n| Prompt | La consigne écrite que vous donnez à un assistant IA |\n| Base de données | L’endroit où une application range ses informations (utilisateurs, réservations…) |\n| Dépôt | Le dossier d’un projet de code hébergé sur GitHub, avec tout son historique (on dit aussi *repository*) |\n| Déploiement | L’action de mettre une application en ligne, accessible par une adresse web |\n| Clé d’API | Un code secret qui permet à un logiciel d’utiliser un service : à protéger comme un mot de passe |\n\nUn compte vous résiste ? Notez l’étape exacte et le message affiché, puis écrivez à votre formateur.","personas":["reconversion"]},{"id":"crs_mvp_ia_m00_l03_b_6","type":"checklist","title":"Mon environnement est prêt","items":[{"id":"crs_mvp_ia_m00_l03_b_6_i_1","label":"Mon gestionnaire de mots de passe est en place et je connais mon mot de passe maître."},{"id":"crs_mvp_ia_m00_l03_b_6_i_2","label":"La double authentification est activée sur l’adresse e-mail du projet."},{"id":"crs_mvp_ia_m00_l03_b_6_i_3","label":"Mes comptes Claude et ChatGPT sont créés et j’ai vérifié leurs paramètres de confidentialité."},{"id":"crs_mvp_ia_m00_l03_b_6_i_4","label":"Mes comptes GitHub, Notion, Supabase et Vercel sont créés, avec la double authentification quand elle est proposée."},{"id":"crs_mvp_ia_m00_l03_b_6_i_5","label":"Mon outil de construction est prêt : Cursor et Claude Code (profil technique) ou Bolt.new (autres profils)."},{"id":"crs_mvp_ia_m00_l03_b_6_i_6","label":"Mon dossier projet et ma page Notion « Mon MVP » existent."},{"id":"crs_mvp_ia_m00_l03_b_6_i_7","label":"Mon journal de bord est commencé."}]},{"id":"crs_mvp_ia_m00_l03_b_7","type":"exercice","title":"Confirmez que votre environnement est prêt","instructions":"Vérifiez que votre environnement est prêt, puis confirmez-le en quelques lignes.\n\n1. Cochez chaque point de la checklist ci-dessus.\n2. Dans le champ de réponse, indiquez : les comptes créés, l’outil de construction retenu (Cursor et Claude Code, ou Bolt.new), l’emplacement de votre dossier projet et le nom de votre page Notion.\n3. Signalez tout blocage : compte refusé, installation impossible, matériel inadapté. Si un blocage persiste, écrivez aussi à votre formateur via la messagerie de Mon espace : n’attendez pas le module 6 pour le résoudre.\n\nNe communiquez ici aucun mot de passe, code de secours ou clé.","deliverable":"texte","estimatedMinutes":20,"review":"auto","rubric":["Les comptes nécessaires à la formation sont créés.","La double authentification est activée sur les comptes critiques (e-mail, GitHub, Supabase, Vercel).","Le dossier projet et l’espace Notion existent.","Les éventuels blocages sont signalés, sans aucun secret dans la réponse."]},{"id":"crs_mvp_ia_m00_l03_b_8","type":"quiz","title":"Quiz : le fonctionnement de la formation","graded":true,"questions":[{"id":"crs_mvp_ia_m00_l03_b_8_q_1","prompt":"Vous venez de terminer une leçon. Comment la leçon suivante devient-elle accessible ?","kind":"unique","options":[{"id":"crs_mvp_ia_m00_l03_b_8_q_1_o_1","label":"Elle se débloque quand la leçon en cours est terminée","correct":true},{"id":"crs_mvp_ia_m00_l03_b_8_q_1_o_2","label":"Toutes les leçons sont ouvertes dès le premier jour","correct":false},{"id":"crs_mvp_ia_m00_l03_b_8_q_1_o_3","label":"Votre formateur l’ouvre manuellement chaque semaine","correct":false},{"id":"crs_mvp_ia_m00_l03_b_8_q_1_o_4","label":"Elle s’ouvre automatiquement après sept jours","correct":false}],"explanation":"La progression est séquentielle : chaque étape s’appuie sur la précédente, la leçon suivante se débloque donc quand la leçon en cours est terminée."},{"id":"crs_mvp_ia_m00_l03_b_8_q_2","prompt":"Vous êtes bloqué depuis une heure sur une erreur. Quelle est la meilleure démarche ?","kind":"unique","options":[{"id":"crs_mvp_ia_m00_l03_b_8_q_2_o_1","label":"Écrire à votre formateur référent via la messagerie de Mon espace, en précisant la leçon, ce que vous avez essayé et le message d’erreur, sans aucun secret","correct":true},{"id":"crs_mvp_ia_m00_l03_b_8_q_2_o_2","label":"Attendre la fin du module pour en parler","correct":false},{"id":"crs_mvp_ia_m00_l03_b_8_q_2_o_3","label":"Envoyer votre mot de passe à votre formateur pour qu’il se connecte à votre place","correct":false},{"id":"crs_mvp_ia_m00_l03_b_8_q_2_o_4","label":"Sauter l’exercice et passer au module suivant","correct":false}],"explanation":"La messagerie de Mon espace est le canal d’assistance. Une question précise (contexte, essais, message d’erreur) obtient une réponse utile du premier coup. Ne transmettez jamais vos identifiants."},{"id":"crs_mvp_ia_m00_l03_b_8_q_3","prompt":"Dans quel délai votre formateur référent s’engage-t-il à vous répondre ?","kind":"unique","options":[{"id":"crs_mvp_ia_m00_l03_b_8_q_3_o_1","label":"Sous 48 heures ouvrées","correct":true},{"id":"crs_mvp_ia_m00_l03_b_8_q_3_o_2","label":"Dans l’heure, sept jours sur sept","correct":false},{"id":"crs_mvp_ia_m00_l03_b_8_q_3_o_3","label":"Uniquement lors d’une séance collective mensuelle","correct":false},{"id":"crs_mvp_ia_m00_l03_b_8_q_3_o_4","label":"À la fin de la formation","correct":false}],"explanation":"Le formateur référent répond sous 48 heures ouvrées. Anticipez : posez votre question dès qu’un blocage dure, sans attendre la veille d’une échéance."},{"id":"crs_mvp_ia_m00_l03_b_8_q_4","prompt":"Qu’est-ce qui conditionne la délivrance du certificat de réalisation ?","kind":"unique","options":[{"id":"crs_mvp_ia_m00_l03_b_8_q_4_o_1","label":"Atteindre la progression minimale indiquée dans le livret d’accueil, vos connexions et activités étant tracées","correct":true},{"id":"crs_mvp_ia_m00_l03_b_8_q_4_o_2","label":"Obtenir la note maximale à tous les quiz","correct":false},{"id":"crs_mvp_ia_m00_l03_b_8_q_4_o_3","label":"Avoir levé des fonds pour son projet","correct":false},{"id":"crs_mvp_ia_m00_l03_b_8_q_4_o_4","label":"Être inscrit, même sans jamais se connecter","correct":false}],"explanation":"Le certificat de réalisation atteste le suivi de la formation. Il repose sur une progression minimale, prouvée par les connexions et activités tracées."},{"id":"crs_mvp_ia_m00_l03_b_8_q_5","prompt":"Lequel de ces prompts respecte les règles de sécurité vues dans cette leçon ?","kind":"unique","options":[{"id":"crs_mvp_ia_m00_l03_b_8_q_5_o_1","label":"« Voici l’erreur affichée : Invalid API key [CLÉ_MASQUÉE]. Que dois-je vérifier ? »","correct":true},{"id":"crs_mvp_ia_m00_l03_b_8_q_5_o_2","label":"« Voici ma clé secrète de paiement complète, dis-moi si elle est valide. »","correct":false},{"id":"crs_mvp_ia_m00_l03_b_8_q_5_o_3","label":"« Résume ces notes : Mme Martin, avec son téléphone et son e-mail, m’a dit que… »","correct":false},{"id":"crs_mvp_ia_m00_l03_b_8_q_5_o_4","label":"« Voici le mot de passe de mon compte Supabase, connecte-toi pour moi. »","correct":false}],"explanation":"Seul le premier prompt masque le secret. Les autres exposent une clé, des données personnelles ou un mot de passe à un service externe."},{"id":"crs_mvp_ia_m00_l03_b_8_q_6","prompt":"Vous avez collé par erreur une clé secrète dans une conversation avec un assistant IA. Que faites-vous ?","kind":"unique","options":[{"id":"crs_mvp_ia_m00_l03_b_8_q_6_o_1","label":"Vous révoquez la clé et en générez une nouvelle depuis le service concerné","correct":true},{"id":"crs_mvp_ia_m00_l03_b_8_q_6_o_2","label":"Vous supprimez la conversation : cela suffit","correct":false},{"id":"crs_mvp_ia_m00_l03_b_8_q_6_o_3","label":"Rien : les assistants IA sont sécurisés","correct":false},{"id":"crs_mvp_ia_m00_l03_b_8_q_6_o_4","label":"Vous changez le mot de passe de votre messagerie","correct":false}],"explanation":"Une clé exposée doit être considérée comme compromise. Supprimer la conversation ne garantit pas qu’elle n’a pas été conservée ailleurs : seule la révocation la rend inutilisable."}]}]$q$::jsonb)
on conflict (id) do nothing;

insert into crm.academy_lessons (id, course_id, module_id, position, title, summary, estimated_minutes, is_preview, blocks)
values ($q$crs_mvp_ia_m01_l01$q$, $q$crs_mvp_ia$q$, $q$crs_mvp_ia_m01$q$, 0, $q$Du problème à l’opportunité$q$, $q$Transformer une idée en énoncé de problème étayé et repérer les hypothèses qui peuvent faire échouer le projet.$q$, 35, false, $q$[{"id":"crs_mvp_ia_m01_l01_b_1","type":"texte","markdown":"À la fin de cette leçon, vous saurez écrire un énoncé de problème précis, le relier à ce que votre cible cherche vraiment à accomplir, et repérer les hypothèses qui peuvent faire échouer votre projet.\n\n## Partir du problème, pas de la solution\n\nLa plupart des projets naissent d’une idée de solution : « une application qui… ». C’est naturel, mais risqué. Une solution n’a de valeur que si elle résout un problème **réel**, **fréquent** ou **coûteux** pour un groupe de personnes identifiable. Construire d’abord, puis chercher des utilisateurs, c’est prendre le risque de passer des semaines sur un produit dont personne n’a besoin.\n\nUn problème, au sens où nous l’entendons, a quatre composantes : **une personne** précise, **une situation** dans laquelle il se produit, **une cause**, et **une conséquence** qui coûte quelque chose (du temps, de l’argent, du stress, une opportunité perdue).\n\n## Écrire un énoncé de problème\n\nUtilisez cette trame :\n\n> [!info] [Cible] a du mal à [objectif] quand [situation], parce que [cause]. Aujourd’hui, elle [solution de contournement], ce qui lui coûte [conséquence].\n\nExemple pour Créno : « Les coachs sportifs indépendants ont du mal à remplir et à organiser leur planning de séances, parce que chaque réservation passe par des échanges de messages. Aujourd’hui, ils confirment les créneaux un par un, relancent les paiements et subissent des annulations de dernière minute, ce qui leur coûte des soirées de travail non facturé et des séances perdues. »\n\n| Énoncé flou | Ce qui manque |\n| --- | --- |\n| « Les gens ont du mal à faire du sport. » | Qui exactement ? Dans quelle situation ? Avec quelle conséquence ? |\n| « Les coachs ont besoin d’une application de réservation. » | C’est une solution, pas un problème : que vit le coach aujourd’hui ? |\n| « Le marché du fitness est énorme. » | C’est un contexte, pas un problème, et un chiffre à sourcer. |\n\n## Les « jobs to be done »\n\nL’approche des *jobs to be done* (littéralement « tâches à accomplir ») part d’une idée simple : une personne n’achète pas un produit pour lui-même, elle l’« embauche » pour progresser dans une situation donnée. Un job se formule ainsi :\n\n> [!info] Quand [situation], je veux [motivation], pour [résultat attendu].\n\nUn job a souvent trois dimensions : **fonctionnelle** (ce qu’il faut faire), **émotionnelle** (ce que la personne veut ressentir ou éviter) et **sociale** (l’image qu’elle veut donner).\n\nPour Créno :\n\n- **Le coach** : « Quand un client veut réserver une séance, je veux qu’il le fasse seul et paie d’avance, pour ne plus gérer mon agenda le soir ni courir après les paiements. » Dimension émotionnelle : ne plus se sentir débordé. Dimension sociale : paraître professionnel.\n- **Le client** : « Quand je décide de m’entraîner, je veux réserver en quelques secondes un créneau qui me convient, pour ne pas attendre une réponse par message. »\n\nLes jobs vous montrent contre quoi vous êtes réellement en concurrence. Pour le coach, ce n’est pas seulement un autre logiciel : c’est aussi le carnet et les messages, qui « font le job » aujourd’hui, même mal.\n\n## Des preuves, pas des opinions\n\nUn problème n’est pas prouvé parce qu’il vous semble évident, ni parce que votre entourage trouve l’idée « géniale ». Classez vos indices selon leur force :\n\n| Signal | Force |\n| --- | --- |\n| Des personnes de la cible décrivent spontanément le problème, avec un exemple récent | Forte |\n| Elles ont déjà bricolé une solution (tableur, messages, outil détourné) | Forte |\n| Elles dépensent déjà du temps ou de l’argent pour le résoudre | Très forte |\n| Elles s’engagent : rendez-vous, inscription sur une liste d’attente, précommande | Très forte |\n| « Bonne idée, je l’utiliserais sûrement » | Faible |\n| L’enthousiasme de vos proches | Faible |\n| Un article qui affirme que le marché est « énorme » | Faible, et à vérifier |\n\nLa règle : ce que les gens **font** vaut plus que ce qu’ils **disent** qu’ils feront.\n\n## Identifier vos hypothèses risquées\n\nUne hypothèse est une affirmation que vous tenez pour vraie sans l’avoir encore prouvée. Votre projet en contient des dizaines. On les classe en trois familles :\n\n- **Désirabilité** : la cible veut-elle vraiment cette solution ?\n- **Viabilité** : le modèle économique tient-il ? Quelqu’un paiera-t-il, et assez ?\n- **Faisabilité** : pouvez-vous la construire, avec vos moyens et dans vos délais ?\n\nPour chaque hypothèse, posez deux questions : **si elle est fausse, le projet s’effondre-t-il ?** et **quelle preuve ai-je déjà ?** Les hypothèses à tester en premier sont à la fois **critiques** et **peu prouvées**.\n\nLes hypothèses de Créno, de la plus risquée à la moins risquée :\n\n1. Les coachs acceptent de publier leurs créneaux dans un outil plutôt que de tout gérer par messages (désirabilité, critique, peu prouvée).\n2. Les clients acceptent de payer en ligne au moment de réserver (désirabilité, critique).\n3. Les coachs paieront pour l’outil, par abonnement ou par commission (viabilité, critique).\n4. Un rappel la veille réduit les oublis de séance (désirabilité, importante mais secondaire).\n5. Réservation, paiement et rappels peuvent être construits en quelques semaines avec les outils de la formation (faisabilité, moins risquée : des produits comparables existent).\n\n> [!tip] L’IA peut vous aider à lister vos hypothèses et à repérer vos angles morts. Elle ne peut pas les valider : seuls vos futurs utilisateurs le peuvent. Vous les rencontrerez dès la leçon suivante."},{"id":"crs_mvp_ia_m01_l01_b_2","type":"video","title":"Du problème aux hypothèses : l’exemple de Créno","url":"","durationMinutes":6,"script":"- Accroche : une idée de solution (« une app de réservation ») face à un problème réellement vécu par les coachs.\n- Les quatre composantes d’un problème (personne, situation, cause, conséquence), appliquées aux coachs indépendants.\n- Réécriture en direct d’un énoncé flou en énoncé exploitable.\n- Le job du coach et le job du client : dimensions fonctionnelle, émotionnelle et sociale.\n- Signaux forts et signaux faibles : exemples de phrases entendues et de ce qu’elles prouvent vraiment.\n- Les hypothèses de Créno classées en désirabilité, viabilité et faisabilité ; choix des trois plus risquées.\n- Transition vers la leçon suivante : aller vérifier ces hypothèses auprès de vrais coachs."},{"id":"crs_mvp_ia_m01_l01_b_3","type":"prompt","title":"Faire challenger votre énoncé de problème","tool":"Tout assistant IA","prompt":"Tu es un coach en entrepreneuriat exigeant. Voici l’énoncé de problème de mon projet :\n\n[COLLEZ VOTRE ÉNONCÉ, SANS AUCUNE DONNÉE PERSONNELLE]\n\n1. Dis-moi si la cible, la situation, la cause et la conséquence sont précises. Pour chaque élément flou, propose une question à poser à de vrais utilisateurs pour le préciser.\n2. Liste 8 hypothèses implicites contenues dans cet énoncé, classées en désirabilité, viabilité et faisabilité.\n3. Pour chacune, indique ce qui la rendrait fausse et quel comportement observable la confirmerait.\n4. Désigne les 3 hypothèses qui te semblent à la fois critiques et les moins prouvées, en expliquant pourquoi.\n\nNe me donne aucun chiffre de marché : je vérifierai moi-même les données dont j’ai besoin.","tips":"Soumettez ensuite votre énoncé corrigé une seconde fois. Gardez les questions proposées : elles alimenteront votre script d’entretien à la leçon suivante."},{"id":"crs_mvp_ia_m01_l01_b_4","type":"exercice","title":"Votre énoncé de problème et vos hypothèses","instructions":"Appliquez la leçon à votre projet. Répondez dans le champ de texte.\n\n1. **Énoncé de problème** : rédigez-le avec la trame de la leçon (5 lignes maximum).\n2. **Job to be done** : formulez le job principal de votre cible (« Quand…, je veux…, pour… ») et précisez ses dimensions émotionnelle et sociale.\n3. **Preuves actuelles** : listez ce que vous savez déjà, en indiquant pour chaque élément s’il s’agit d’un signal fort ou faible.\n4. **Hypothèses** : listez au moins 6 hypothèses (désirabilité, viabilité, faisabilité), puis désignez les 3 plus risquées (critiques et peu prouvées) en justifiant votre choix.\n\nVous pouvez utiliser le prompt ci-dessus pour challenger votre premier jet, mais le texte remis doit être le vôtre, relu et assumé.","deliverable":"texte","estimatedMinutes":20,"review":"auto","rubric":["L’énoncé précise la cible, la situation, la cause et la conséquence.","Le job est formulé du point de vue de la cible, sans décrire de solution.","Les preuves distinguent les faits observés des opinions.","Au moins 6 hypothèses sont classées, dont 3 prioritaires justifiées."]}]$q$::jsonb)
on conflict (id) do nothing;

insert into crm.academy_lessons (id, course_id, module_id, position, title, summary, estimated_minutes, is_preview, blocks)
values ($q$crs_mvp_ia_m01_l02$q$, $q$crs_mvp_ia$q$, $q$crs_mvp_ia_m01$q$, 1, $q$Définir sa cible et ses early adopters$q$, $q$Délimiter votre cible, repérer vos early adopters et mener des entretiens de découverte en limitant les biais.$q$, 45, false, $q$[{"id":"crs_mvp_ia_m01_l02_b_1","type":"texte","markdown":"À la fin de cette leçon, vous saurez délimiter votre cible, repérer vos early adopters et mener des entretiens de découverte qui produisent des faits plutôt que des politesses.\n\n## Segmenter : de « tout le monde » à un segment\n\n« Mon produit s’adresse à tout le monde » est l’une des phrases les plus dangereuses pour un projet naissant. Un **segment** est un groupe de personnes qui partagent le même problème, dans la même situation, et que l’on peut atteindre par les mêmes canaux.\n\nPour segmenter, l’âge ou le revenu comptent souvent moins que :\n\n- **la situation** : dans quel contexte le problème apparaît-il ?\n- **le comportement** : que font ces personnes aujourd’hui ?\n- **l’intensité du besoin** : à quel point le problème est-il douloureux ou fréquent ?\n- **l’accessibilité** : où les trouver, comment leur parler ?\n\nCréno affine sa cible ainsi : « les gens qui font du sport » → « les coachs sportifs » → « les coachs indépendants qui donnent des séances individuelles ou en petit groupe, gèrent seuls leur planning et se font payer à la séance ».\n\n## Vos early adopters\n\nLes **early adopters** (premiers utilisateurs) sont les personnes du segment qui adopteront votre MVP en premier, malgré ses imperfections. On les reconnaît à cinq traits :\n\n1. elles ont le problème ;\n2. elles savent qu’elles l’ont ;\n3. elles cherchent déjà une solution, ou en ont bricolé une ;\n4. elles ont les moyens (budget, temps) de changer d’habitude ;\n5. vous pouvez les joindre facilement.\n\nPour Créno : des coachs installés depuis peu, déjà débordés par les messages, qui ont essayé un agenda partagé sans en être satisfaits et qui sont actifs sur des réseaux où vous pouvez les contacter.\n\n## Persona utile ou persona cliché\n\nUn **persona** est la description d’un utilisateur type. Il est utile s’il aide à prendre des décisions, inutile s’il décrit une caricature.\n\n| Persona cliché | Persona utile |\n| --- | --- |\n| Julie, 32 ans, aime le yoga et les voyages | Coach indépendante, une vingtaine de clients réguliers, gère tout depuis son téléphone |\n| « Active sur les réseaux sociaux » | Reçoit ses demandes de réservation par messages, souvent le soir |\n| « Veut une application simple » | A essayé un agenda partagé, abandonné car ses clients ne l’utilisaient pas |\n| Photo et citation inventées | Critères de choix : rapidité, paiement garanti, image professionnelle |\n\nUn persona se construit à partir des entretiens, pas de l’imagination. Avant vos entretiens, écrivez-le comme une hypothèse ; après, corrigez-le avec ce que vous avez appris.\n\n## Les entretiens de découverte\n\nL’entretien de découverte sert à **comprendre le problème**, pas à présenter votre solution. Visez au moins **5 entretiens** de 20 à 30 minutes avec des personnes de votre segment : c’est assez pour voir des tendances se dessiner, pas pour tirer des conclusions définitives.\n\n### Un script type\n\n1. **Introduction (2 min)** : remerciez, expliquez que vous cherchez à comprendre leur quotidien et non à vendre ; demandez l’autorisation de prendre des notes ou d’enregistrer.\n2. **Contexte (5 min)** : « Parlez-moi de votre activité. À quoi ressemble une semaine type ? »\n3. **Le problème (10 min)** : « Racontez-moi la dernière fois que [situation] s’est produite. Qu’avez-vous fait ? Qu’est-ce qui a été le plus pénible ? Qu’est-ce que cela vous a coûté ? »\n4. **Les solutions actuelles (5 min)** : « Qu’utilisez-vous aujourd’hui ? Qu’avez-vous déjà essayé ? Pourquoi avez-vous arrêté ? »\n5. **Clôture (3 min)** : « Qui d’autre devrais-je rencontrer ? Puis-je revenir vers vous quand j’aurai quelque chose à vous montrer ? »\n\n### Les biais à éviter\n\n- **Les questions orientées** : « Ne trouvez-vous pas que les messages font perdre du temps ? » suggère la réponse. Préférez : « Comment gérez-vous vos réservations ? »\n- **Les questions hypothétiques** : « Utiliseriez-vous une application qui… ? » produit des « oui » polis. Interrogez le passé : ce que la personne a réellement fait.\n- **Le biais de complaisance** : dès que vous présentez votre idée, votre interlocuteur veut vous faire plaisir. Gardez la solution pour la fin, ou pour un autre rendez-vous.\n- **Le biais de confirmation** : vous retenez ce qui confirme votre idée. Notez aussi, et surtout, ce qui la contredit.\n- **L’échantillon de proches** : amis et famille sont rarement votre cible, et toujours bienveillants.\n- **La généralisation** : un entretien est une anecdote ; une tendance, c’est ce qui revient chez plusieurs personnes.\n\n### Synthétiser\n\nJuste après chaque entretien, prenez 10 minutes pour remplir une fiche : contexte de la personne, faits marquants, phrases citées mot pour mot, solutions actuelles, intensité du problème (de 1 à 5), signaux d’engagement. Après vos cinq entretiens, comparez les fiches : ce qui revient chez au moins trois personnes, ce qui vous a surpris, les hypothèses confirmées ou fragilisées.\n\n> [!warning] Vos notes d’entretien contiennent des données personnelles. Demandez le consentement avant d’enregistrer, ne collectez que ce qui est utile, anonymisez vos fiches (« Coach A », « Coach B ») et ne collez jamais de notes nominatives dans un assistant IA. Des repères généraux sont disponibles sur [cnil.fr](https://www.cnil.fr) ; ceci n’est pas un conseil juridique."},{"id":"crs_mvp_ia_m01_l02_b_2","type":"texte","markdown":"## Profil technique : parler avant de coder\n\nVotre réflexe sera peut-être de lancer un prototype pour « voir si ça plaît ». Résistez : un prototype présenté trop tôt transforme l’entretien en démonstration, et vous n’apprenez plus rien sur le problème.\n\nTraitez vos entretiens comme une collecte de données : même script pour tous, fiche de synthèse identique, tableau comparatif (par exemple une base Notion avec une ligne par entretien et une colonne par question). Si vous utilisez un outil de transcription, informez la personne et obtenez son accord, puis anonymisez la transcription avant toute analyse par une IA.","personas":["tech"]},{"id":"crs_mvp_ia_m01_l02_b_3","type":"texte","markdown":"## Profil non technique : votre réseau, un atout à manier avec précaution\n\nVotre expérience métier vous donne un accès direct à votre cible : collègues, clients, fournisseurs, groupes professionnels. Utilisez-le, mais diversifiez : une bonne partie de vos entretiens devrait se faire avec des personnes qui ne vous connaissent pas, pour limiter la complaisance.\n\nAutre piège : votre expertise vous pousse à « savoir » ce dont les gens ont besoin. Pendant l’entretien, mettez-la de côté et posez vos questions comme si vous découvriez le métier.","personas":["non_tech"]},{"id":"crs_mvp_ia_m01_l02_b_4","type":"texte","markdown":"## Profil reconversion : un message pour décrocher vos premiers entretiens\n\nDemander un entretien à un inconnu intimide. Voici un message court à adapter :\n\n> [!tip] « Bonjour [prénom], je travaille sur un projet autour de [thème] et je cherche à comprendre comment les [cible] gèrent [situation]. Je ne vends rien : j’aimerais simplement vous poser quelques questions pendant 20 minutes, par téléphone ou en visio, au moment qui vous arrange. Seriez-vous d’accord ? Merci d’avance ! »\n\nContactez nettement plus de personnes que le nombre d’entretiens visé : beaucoup ne répondront pas, et ce n’est pas un jugement sur votre projet. Pour votre tout premier entretien, entraînez-vous avec une personne bienveillante, puis passez à votre vraie cible.","personas":["reconversion"]},{"id":"crs_mvp_ia_m01_l02_b_5","type":"prompt","title":"Synthétiser vos fiches d’entretien anonymisées","tool":"Claude","prompt":"Tu es chercheur en expérience utilisateur. Voici les fiches anonymisées de mes entretiens de découverte (aucun nom, e-mail ni téléphone) :\n\n[COLLEZ VOS FICHES ANONYMISÉES]\n\nMon hypothèse principale était : [VOTRE HYPOTHÈSE]\n\n1. Liste les problèmes cités, en indiquant pour chacun combien de personnes l’ont mentionné et une phrase citée à l’appui.\n2. Liste les solutions de contournement actuelles.\n3. Indique ce qui confirme mon hypothèse, ce qui la contredit et ce qui reste incertain.\n4. Propose une version corrigée de mon persona, uniquement à partir de ces fiches.\n\nN’invente aucune information absente des fiches. Si un point n’est pas couvert, écris « non couvert ».","tips":"Fonctionne aussi dans ChatGPT. Relisez la synthèse en la confrontant à vos fiches : une IA peut surpondérer une phrase marquante ou lisser une contradiction."},{"id":"crs_mvp_ia_m01_l02_b_6","type":"exercice","title":"Mener et synthétiser vos entretiens de découverte","instructions":"1. **Votre segment et vos early adopters** : décrivez-les en 5 lignes maximum, en reprenant les cinq traits vus dans la leçon.\n2. **Votre persona hypothèse** : situation, objectifs, frustrations, solutions actuelles, critères de choix, où le trouver.\n3. **Votre script** : adaptez le script type à votre projet (8 à 12 questions, tournées vers le passé).\n4. **Vos entretiens** : menez au moins 5 entretiens avec des personnes de votre segment, dont une majorité hors de votre cercle proche.\n5. **Votre synthèse** : les 3 enseignements principaux, les phrases citées les plus parlantes (anonymisées), les hypothèses confirmées ou fragilisées, et votre persona corrigé.\n\nLes 30 minutes estimées couvrent la préparation et la synthèse. Les entretiens eux-mêmes se planifient en parallèle des leçons suivantes. S’ils ne sont pas tous réalisés au moment du dépôt, remettez votre script et les synthèses disponibles, en indiquant les dates prévues pour les suivants.","deliverable":"texte","estimatedMinutes":30,"review":"formateur","rubric":["Le segment et les early adopters sont précis et atteignables.","Le script ne contient ni question orientée ni question hypothétique.","La synthèse s’appuie sur des faits et des citations anonymisées, pas sur des opinions.","Les hypothèses sont explicitement confirmées, fragilisées ou laissées ouvertes.","Le persona a été corrigé à la lumière des entretiens."]}]$q$::jsonb)
on conflict (id) do nothing;

insert into crm.academy_lessons (id, course_id, module_id, position, title, summary, estimated_minutes, is_preview, blocks)
values ($q$crs_mvp_ia_m01_l03$q$, $q$crs_mvp_ia$q$, $q$crs_mvp_ia_m01$q$, 2, $q$Formuler sa proposition de valeur$q$, $q$Formuler une proposition de valeur, un one-liner et une différenciation crédibles.$q$, 35, false, $q$[{"id":"crs_mvp_ia_m01_l03_b_1","type":"texte","markdown":"À la fin de cette leçon, vous saurez formuler votre proposition de valeur, la résumer en une phrase et expliquer ce qui vous distingue des alternatives existantes.\n\n## Qu’est-ce qu’une proposition de valeur ?\n\nLa proposition de valeur est la promesse que vous faites à votre cible : **le bénéfice concret** qu’elle obtiendra avec votre produit, **par rapport à ce qu’elle fait aujourd’hui**. Ce n’est pas une liste de fonctionnalités. « Réservation en ligne » est une fonctionnalité ; « ne plus passer ses soirées à caler des rendez-vous par message » est un bénéfice.\n\n## Le canevas de proposition de valeur\n\nLe canevas de proposition de valeur, popularisé par Alexander Osterwalder et Strategyzer, aide à vérifier l’adéquation entre ce que vit votre cible et ce que vous proposez. Il a deux côtés.\n\n**Le profil client**, à remplir à partir de vos entretiens :\n\n- **les tâches** : ce que la personne cherche à accomplir (ses jobs) ;\n- **les problèmes** : ce qui la gêne, la bloque, lui coûte ou l’inquiète ;\n- **les gains** : ce qu’elle espère obtenir, y compris au-delà de la tâche elle-même.\n\n**L’offre**, ce que vous proposez :\n\n- **les produits et services** : ce que vous proposez concrètement ;\n- **les solutions aux problèmes** : comment votre offre supprime ou réduit chaque problème ;\n- **les créateurs de gains** : comment elle produit les gains attendus.\n\nL’adéquation existe quand vos solutions répondent aux problèmes **les plus importants** de votre cible, pas à des problèmes secondaires.\n\n| Profil du coach | Offre de Créno |\n| --- | --- |\n| Tâche : remplir son planning et être payé | Une page de réservation avec paiement en ligne |\n| Problème : des soirées à répondre aux messages | Le client réserve seul, sans échange de messages |\n| Problème : les impayés et les relances | Le paiement a lieu au moment de la réservation |\n| Problème : les oublis de séance | Un rappel automatique part la veille |\n| Gain : paraître professionnel | Une page de réservation soignée, au nom du coach |\n\n## Le one-liner\n\nLe one-liner résume votre proposition de valeur en une phrase. Une trame simple :\n\n> [!info] [Produit] aide [cible] à [résultat] grâce à [mécanisme], sans [irritant actuel].\n\nPour Créno : « Créno aide les coachs sportifs indépendants à remplir leur planning et à être payés d’avance, grâce à une page de réservation en ligne, sans passer leurs soirées à échanger des messages. »\n\nUn bon one-liner :\n\n- se comprend en dix secondes par quelqu’un qui ne connaît pas votre secteur ;\n- nomme une cible précise ;\n- promet un résultat, pas une technologie (« grâce à l’IA » n’est pas un bénéfice) ;\n- évite les superlatifs : « révolutionnaire », « unique », « le meilleur ».\n\n## Se différencier\n\nVos concurrents ne sont pas seulement les produits similaires au vôtre. Pensez à **toutes les alternatives** : ne rien faire, les messages et le carnet, un tableur, un outil généraliste de prise de rendez-vous, une plateforme qui met en relation coachs et clients.\n\n« Nous n’avons pas de concurrent » est presque toujours faux, et c’est un signal inquiétant pour un investisseur ou un jury : soit le problème n’existe pas, soit l’analyse n’a pas été faite.\n\n| Alternative | Force | Limite pour notre cible |\n| --- | --- | --- |\n| Messages et carnet | Gratuit, déjà en place | Chronophage, pas de paiement garanti |\n| Tableur ou agenda partagé | Simple, flexible | Le client ne peut ni réserver ni payer seul |\n| Outil généraliste de prise de rendez-vous | Complet, éprouvé | Pensé pour de nombreux métiers, à paramétrer soi-même |\n| Plateforme de mise en relation | Apporte des clients | Le coach dépend de la plateforme et de ses conditions |\n\nPour un MVP, la différenciation vient rarement d’une fonctionnalité que personne d’autre n’a. Elle vient plus souvent d’une **cible plus précise**, d’un **parcours plus simple** pour cette cible, ou d’une **combinaison** mieux pensée. La différenciation de Créno (la simplicité pour le coach qui travaille seul) est elle-même une hypothèse, que vous vérifierez avec vos testeurs au module 7."},{"id":"crs_mvp_ia_m01_l03_b_2","type":"prompt","title":"Challenger votre proposition de valeur","tool":"Claude","prompt":"Joue successivement deux rôles critiques.\n\nRôle 1 : [DÉCRIVEZ VOTRE EARLY ADOPTER, par exemple « un coach sportif indépendant, débordé, méfiant envers les nouveaux outils »].\nRôle 2 : un membre exigeant du jury d’un incubateur.\n\nVoici ma proposition de valeur :\n- Cible : [...]\n- Problèmes principaux, issus de mes entretiens : [...]\n- Offre et bénéfices : [...]\n- One-liner : [...]\n- Alternatives utilisées aujourd’hui par ma cible : [...]\n\nPour chaque rôle :\n1. Donne les 5 objections les plus sérieuses, formulées comme cette personne les dirait.\n2. Indique quelles objections pourraient être levées par un fait vérifiable, et comment le vérifier.\n3. Propose 3 reformulations de mon one-liner, plus claires et plus concrètes, sans superlatif.\n\nNe cite aucun chiffre de marché et n’invente aucun concurrent précis.","tips":"Soumettez le même prompt à ChatGPT et comparez les objections. Gardez celles que vous pouvez vérifier auprès de vrais utilisateurs ; les autres ne sont que des opinions."},{"id":"crs_mvp_ia_m01_l03_b_3","type":"quiz","title":"Auto-vérification : proposition de valeur","graded":false,"questions":[{"id":"crs_mvp_ia_m01_l03_b_3_q_1","prompt":"Lequel de ces éléments est un bénéfice, et non une fonctionnalité ?","kind":"unique","options":[{"id":"crs_mvp_ia_m01_l03_b_3_q_1_o_1","label":"Ne plus passer ses soirées à caler des rendez-vous par message","correct":true},{"id":"crs_mvp_ia_m01_l03_b_3_q_1_o_2","label":"La réservation en ligne","correct":false},{"id":"crs_mvp_ia_m01_l03_b_3_q_1_o_3","label":"Le paiement par carte","correct":false},{"id":"crs_mvp_ia_m01_l03_b_3_q_1_o_4","label":"Un tableau de bord","correct":false}],"explanation":"Un bénéfice décrit ce qui change pour la personne. Les trois autres réponses décrivent des moyens (des fonctionnalités) qui produisent ce bénéfice."},{"id":"crs_mvp_ia_m01_l03_b_3_q_2","prompt":"Quand y a-t-il adéquation entre le profil client et l’offre ?","kind":"unique","options":[{"id":"crs_mvp_ia_m01_l03_b_3_q_2_o_1","label":"Quand l’offre répond aux problèmes les plus importants de la cible","correct":true},{"id":"crs_mvp_ia_m01_l03_b_3_q_2_o_2","label":"Quand l’offre contient plus de fonctionnalités que la concurrence","correct":false},{"id":"crs_mvp_ia_m01_l03_b_3_q_2_o_3","label":"Quand le canevas est entièrement rempli","correct":false},{"id":"crs_mvp_ia_m01_l03_b_3_q_2_o_4","label":"Quand l’équipe est convaincue par son idée","correct":false}],"explanation":"Le canevas n’a de valeur que s’il relie vos solutions aux problèmes réellement prioritaires pour la cible, tels qu’ils ressortent de vos entretiens."},{"id":"crs_mvp_ia_m01_l03_b_3_q_3","prompt":"Que révèle généralement la phrase « nous n’avons pas de concurrent » ?","kind":"unique","options":[{"id":"crs_mvp_ia_m01_l03_b_3_q_3_o_1","label":"Une analyse insuffisante des alternatives utilisées par la cible","correct":true},{"id":"crs_mvp_ia_m01_l03_b_3_q_3_o_2","label":"Un avantage décisif qu’il faut mettre en avant","correct":false},{"id":"crs_mvp_ia_m01_l03_b_3_q_3_o_3","label":"Un marché forcément très rentable","correct":false},{"id":"crs_mvp_ia_m01_l03_b_3_q_3_o_4","label":"Un projet prêt à lever des fonds","correct":false}],"explanation":"Votre cible fait déjà quelque chose pour régler son problème, même mal. Ces alternatives sont vos vrais concurrents."}]},{"id":"crs_mvp_ia_m01_l03_b_4","type":"exercice","title":"Votre canevas de proposition de valeur et votre one-liner","instructions":"1. Remplissez le canevas de proposition de valeur de votre projet sous forme de tableau à deux colonnes, comme l’exemple de Créno, à partir de vos entretiens et non de votre intuition.\n2. Rédigez trois versions de votre one-liner, puis choisissez-en une et expliquez votre choix en une phrase.\n3. Listez au moins quatre alternatives utilisées aujourd’hui par votre cible, avec leur force et leur limite.\n4. Formulez votre différenciation en une phrase, ainsi que l’hypothèse qu’elle suppose.","deliverable":"texte","estimatedMinutes":20,"review":"auto","rubric":["Le profil client s’appuie sur des éléments issus des entretiens.","Chaque problème important a une réponse dans l’offre.","Le one-liner nomme une cible, un résultat et un mécanisme, sans superlatif.","Au moins quatre alternatives sont analysées honnêtement."]}]$q$::jsonb)
on conflict (id) do nothing;

insert into crm.academy_lessons (id, course_id, module_id, position, title, summary, estimated_minutes, is_preview, blocks)
values ($q$crs_mvp_ia_m01_l04$q$, $q$crs_mvp_ia$q$, $q$crs_mvp_ia_m01$q$, 3, $q$Scoper son MVP$q$, $q$Choisir le bon type de MVP et réduire votre produit à un parcours clé priorisé.$q$, 55, false, $q$[{"id":"crs_mvp_ia_m01_l04_b_1","type":"texte","markdown":"À la fin de cette leçon, vous saurez choisir le type de MVP adapté à votre hypothèse principale, réduire votre produit à un seul parcours clé et écrire noir sur blanc ce que votre MVP ne fera pas.\n\n## Un MVP sert à apprendre\n\nLe « minimum » du MVP porte sur l’effort : ce qui est nécessaire, et rien de plus, pour tester votre hypothèse la plus risquée. Le « viable » porte sur la valeur : sur son parcours principal, le produit doit réellement rendre le service promis. Un MVP n’est donc ni une maquette qui ne fonctionne pas, ni une version complète « en plus petit ».\n\nLa question à se poser n’est pas « qu’est-ce que je peux construire ? » mais « **quelle est la façon la plus économique de vérifier mon hypothèse la plus risquée ?** »\n\n## Quatre types de MVP\n\n| Type | Principe | Ce qu’il teste | Exemple Créno |\n| --- | --- | --- | --- |\n| Landing page | Une page qui présente l’offre et propose une action (liste d’attente, précommande) | L’intérêt pour la promesse | Une page « Créno arrive bientôt » avec inscription des coachs |\n| Concierge | Vous rendez le service à la main, et le client sait qu’une personne s’en occupe | La valeur du service et son déroulé réel | Vous gérez les réservations de trois coachs avec Airtable, n8n et une page de réservation simple |\n| Magicien d’Oz | L’utilisateur voit un produit qui semble automatique, mais une personne agit en coulisses | L’expérience utilisateur, avant d’automatiser | Le client réserve via un formulaire, vous confirmez et envoyez vous-même le lien de paiement |\n| Fonction unique | Une seule fonctionnalité, réellement construite | L’usage réel du cœur du produit | Réserver et payer un créneau, rien d’autre |\n\nCes types se combinent : une landing page peut précéder un concierge, qui précède une fonction unique. Dans cette formation, vous construirez une **fonction unique** qui couvre votre parcours clé, parce que c’est ce qui permet de tester l’usage réel. Rien ne vous empêche de lancer en parallèle une landing page ou un concierge pour apprendre plus vite.\n\n> [!warning] Le magicien d’Oz ne doit pas tromper vos utilisateurs sur ce qui compte pour eux : sécurité, paiement, données personnelles. Si une étape est faite à la main, le service rendu doit être réel, et vous devez pouvoir l’expliquer honnêtement si on vous le demande.\n\n## Un seul parcours clé\n\nLe **parcours clé** est la suite d’étapes par laquelle un utilisateur obtient la valeur principale de votre produit, du début à la fin. Pour Créno :\n\n1. Le coach crée son compte et publie un créneau.\n2. Le client ouvre la page de réservation du coach.\n3. Il choisit un créneau disponible.\n4. Il paie en ligne.\n5. Il reçoit une confirmation ; le coach voit la réservation.\n6. La veille, le client reçoit un rappel automatique.\n\nTout ce qui n’est pas indispensable à ce parcours attend. Pour chaque idée de fonctionnalité, posez la question : **si je la retire, le parcours clé fonctionne-t-il encore ?** Si oui, elle n’est pas prioritaire.\n\n## Prioriser avec MoSCoW\n\nLa méthode MoSCoW classe chaque fonctionnalité en quatre catégories :\n\n- **Must have** (indispensable) : sans elle, le parcours clé ne fonctionne pas ;\n- **Should have** (important) : forte valeur, mais un contournement existe ;\n- **Could have** (souhaitable) : agréable, si le temps le permet ;\n- **Won’t have this time** (pas cette fois) : exclu du MVP, consciemment.\n\n| Catégorie | Créno |\n| --- | --- |\n| Must | Compte coach, publication de créneaux, page de réservation, paiement en ligne, confirmation, rappel la veille |\n| Should | Annulation par le client selon une règle simple, liste des réservations côté coach |\n| Could | Packs de séances, séances collectives, statistiques |\n| Won’t | Application mobile à installer, messagerie intégrée, synchronisation avec d’autres agendas, facturation avancée |\n\nGardez la catégorie Must courte : elle doit pouvoir être construite pendant le module 6. Si elle déborde, c’est que certains Must sont en réalité des Should.\n\n## La liste « ce que le MVP ne fera pas »\n\nÉcrire explicitement ce que votre MVP ne fera pas vous protège de la **dérive du périmètre** (en anglais *scope creep*) : cette tendance à ajouter « juste une petite fonctionnalité » à chaque étape, jusqu’à ne jamais terminer. Cette liste vous sert aussi face aux testeurs : quand l’un d’eux réclame une fonctionnalité exclue, vous la notez pour plus tard, sans renégocier votre périmètre.\n\nDans son MVP, Créno ne proposera pas d’application mobile à installer, de messagerie entre coach et client, de gestion d’abonnements ou de packs, de séances collectives, de synchronisation avec d’autres agendas ni de programmes d’entraînement.\n\n## Valider votre périmètre\n\nVotre périmètre est bon si :\n\n- il se teste en un seul parcours, de bout en bout ;\n- chaque Must est relié à une hypothèse que vous voulez vérifier ;\n- il est réaliste au regard du temps dont vous disposez ;\n- vous savez à l’avance quel signal vous dira que le test est réussi (par exemple, un nombre de réservations payées fixé avant le lancement)."},{"id":"crs_mvp_ia_m01_l04_b_2","type":"video","title":"Quatre façons de tester une idée","url":"","durationMinutes":5,"script":"- Rappel : un MVP sert à apprendre, pas à construire « petit ».\n- Landing page, concierge, magicien d’Oz, fonction unique : principe et exemple Créno pour chacun.\n- Comment choisir le type de MVP selon l’hypothèse à tester.\n- Le parcours clé de Créno dessiné en six étapes au tableau.\n- Tri MoSCoW en direct d’une douzaine d’idées de fonctionnalités.\n- La liste « ce que Créno ne fera pas » et son usage face aux testeurs."},{"id":"crs_mvp_ia_m01_l04_b_3","type":"ressource","resourceId":"res_scope_mvp","note":"Le canevas de scope MVP reprend les étapes de cette leçon : hypothèse testée, type de MVP, parcours clé, tableau MoSCoW, liste « ne fera pas » et signal de réussite. Utilisez-le pour l’exercice."},{"id":"crs_mvp_ia_m01_l04_b_4","type":"texte","markdown":"## Profil technique : le risque de trop construire\n\nVotre risque principal n’est pas de ne pas y arriver : c’est de construire trop. Quelques règles pour un MVP :\n\n- n’écrivez pas votre propre système d’authentification : utilisez celui de Supabase ;\n- pour le paiement, préférez une page de paiement hébergée par votre prestataire (par exemple Stripe Checkout) à un formulaire de carte bancaire intégré à votre application ;\n- une seule application, une seule base de données : pas de microservices ni d’architecture « prête pour un million d’utilisateurs » ;\n- chaque ligne de code doit servir le parcours clé.\n\nEstimez chaque Must en demi-journées. Si le total dépasse le temps dont vous disposerez au module 6, recoupez.","personas":["tech"]},{"id":"crs_mvp_ia_m01_l04_b_5","type":"texte","markdown":"## Profil non technique : construire ou commencer en concierge\n\nDeux chemins s’offrent à vous. Le premier : construire votre parcours clé avec Bolt.new et Supabase au module 6. Le second : démarrer par un MVP concierge (Airtable pour les données, n8n pour les automatisations, une page de réservation simple), plus rapide à mettre en place et très riche en apprentissages. Dans les deux cas, votre parcours clé devra être accessible en ligne à l’issue du module 6.\n\nGardez un périmètre encore plus étroit que vous ne le pensez : chaque fonctionnalité générée par l’IA est une fonctionnalité que vous devrez comprendre, tester et maintenir. Mieux vaut trois écrans qui fonctionnent parfaitement que dix écrans fragiles.","personas":["non_tech"]},{"id":"crs_mvp_ia_m01_l04_b_6","type":"texte","markdown":"## Profil reconversion : réduire n’est pas renoncer\n\nUn peu de vocabulaire : le **scope** (ou périmètre) est l’ensemble de ce que votre produit fera ; **scoper**, c’est décider de ce périmètre. Une **fonctionnalité** est une chose que le produit permet de faire : réserver, payer, annuler.\n\nCouper des fonctionnalités peut donner l’impression d’abandonner une partie de votre projet. Ce n’est pas le cas : vous les rangez dans la catégorie « pas cette fois ». Elles reviendront si vos utilisateurs les réclament. Un MVP réduit, terminé et testé vaut mieux qu’un projet ambitieux qui n’est jamais mis en ligne.","personas":["reconversion"]},{"id":"crs_mvp_ia_m01_l04_b_7","type":"exercice","title":"Scoper votre MVP","instructions":"À l’aide du canevas de scope MVP, rédigez le périmètre de votre MVP :\n\n1. **Hypothèse principale** : l’hypothèse la plus risquée que votre MVP doit tester (issue de la leçon 1, corrigée après vos entretiens).\n2. **Type de MVP** : landing page, concierge, magicien d’Oz ou fonction unique (éventuellement une combinaison), et pourquoi.\n3. **Parcours clé** : 5 à 8 étapes numérotées, du point de vue de l’utilisateur.\n4. **Tableau MoSCoW** : au moins 10 fonctionnalités réparties dans les quatre catégories.\n5. **Ce que le MVP ne fera pas** : au moins 5 exclusions explicites.\n6. **Signal de réussite** : ce que vous devrez observer pour considérer le test comme réussi, fixé avant de lancer.\n\nCopiez le contenu de votre canevas complété dans le champ de réponse.","deliverable":"texte","estimatedMinutes":30,"review":"formateur","rubric":["L’hypothèse testée est bien la plus risquée, et le type de MVP est cohérent avec elle.","Le parcours clé est complet, de bout en bout, en 5 à 8 étapes.","La catégorie Must ne contient que l’indispensable au parcours clé.","Au moins 5 exclusions explicites sont listées.","Le signal de réussite est observable et fixé à l’avance."]}]$q$::jsonb)
on conflict (id) do nothing;

insert into crm.academy_lessons (id, course_id, module_id, position, title, summary, estimated_minutes, is_preview, blocks)
values ($q$crs_mvp_ia_m01_l05$q$, $q$crs_mvp_ia$q$, $q$crs_mvp_ia_m01$q$, 4, $q$Rédiger un cahier des charges léger (PRD)$q$, $q$Rédiger un PRD d’une à deux pages avec l’aide de l’IA, puis le relire de façon critique.$q$, 50, false, $q$[{"id":"crs_mvp_ia_m01_l05_b_1","type":"texte","markdown":"À la fin de cette leçon, vous saurez rédiger un cahier des charges léger d’une à deux pages, le faire produire en premier jet par une IA et le relire d’un œil critique. Ce document servira de contexte à tous vos outils IA pendant la construction.\n\n## Pourquoi un PRD, même quand on est seul\n\nUn PRD (*Product Requirements Document*, ou document d’exigences produit) décrit **ce que** le produit doit faire et **pourquoi**, sans détailler **comment** le construire. Dans une grande entreprise, il coordonne des équipes. Pour vous, il a trois usages :\n\n- **clarifier votre pensée** : ce qui n’est pas écrit clairement n’est pas encore décidé ;\n- **servir de référence** : quand un doute surgit pendant la construction (« est-ce qu’on gère l’annulation ? »), la réponse est dans le PRD ;\n- **nourrir vos outils IA** : un agent de code, un générateur d’application ou un assistant produit un bien meilleur résultat quand il reçoit un contexte précis. Votre PRD sera ce contexte.\n\nUn PRD léger tient en une à deux pages. Au-delà, personne ne le relit, vous compris.\n\n## La structure\n\n1. **Problème et contexte** : votre énoncé de problème, en 3 à 5 lignes.\n2. **Cible et early adopters** : qui, dans quelle situation.\n3. **Proposition de valeur** : votre one-liner.\n4. **Parcours clé** : les étapes numérotées.\n5. **User stories** : 5 à 10 besoins, chacun formulé du point de vue d’un utilisateur.\n6. **Critères d’acceptation** : pour chaque user story, les conditions vérifiables qui disent qu’elle est terminée.\n7. **Hors périmètre** : votre liste « ce que le MVP ne fera pas ».\n8. **Métriques de succès** : les indicateurs que vous suivrez et votre signal de réussite.\n9. **Contraintes et questions ouvertes** : données personnelles, paiement, délais, points non tranchés.\n\n### User stories et critères d’acceptation\n\nUne **user story** décrit un besoin avec la formule « En tant que [rôle], je veux [action], afin de [bénéfice] ». Elle reste courte et parle de l’utilisateur, pas de la technique.\n\nUn **critère d’acceptation** est une condition que l’on peut vérifier par un test, avec une réponse par oui ou par non. La formule « Étant donné… quand… alors… » aide à les écrire sans ambiguïté.\n\nExtrait du PRD de Créno :\n\n- **US1** : en tant que coach, je veux publier un créneau (date, heure, durée, lieu, prix, nombre de places) afin que mes clients le réservent sans m’écrire.\n- **US2** : en tant que client, je veux voir les créneaux disponibles d’un coach afin de choisir celui qui me convient.\n- **US3** : en tant que client, je veux réserver et payer en ligne afin de garantir ma place.\n- **US4** : en tant que client, je veux recevoir un rappel la veille afin de ne pas oublier ma séance.\n- **US5** : en tant que coach, je veux voir mes réservations et leur statut de paiement afin de préparer mes séances.\n\nCritères d’acceptation de l’US3 :\n\n- Étant donné un créneau avec une place libre, quand le client paie avec succès, alors la réservation est confirmée et le nombre de places restantes diminue d’une unité.\n- Étant donné un créneau complet, quand un client ouvre la page, alors il ne peut pas le réserver.\n- Étant donné un paiement échoué ou abandonné, alors aucune réservation n’est confirmée et la place reste disponible.\n\nMétriques de Créno : nombre de réservations payées par coach et par semaine ; part des créneaux publiés qui sont réservés ; nombre de coachs qui publient des créneaux deux semaines de suite.\n\n## Générer avec l’IA, puis relire en critique\n\nUn assistant IA produit en une minute un PRD bien présenté. C’est un gain de temps réel, à une condition : le **relire comme s’il avait été écrit par un stagiaire brillant qui n’a jamais rencontré vos utilisateurs**.\n\nLa méthode :\n\n1. Rassemblez vos matériaux : énoncé de problème, synthèse anonymisée des entretiens, canevas de proposition de valeur, périmètre MoSCoW.\n2. Demandez un PRD dans la structure ci-dessus, en précisant de ne rien inventer (voir le prompt ci-dessous).\n3. Relisez ligne par ligne : chaque affirmation est-elle vraie, vérifiable, issue de vos matériaux ?\n4. Coupez : visez une à deux pages.\n5. Datez et numérotez : « PRD v1 », avec la date. Le document évoluera ; gardez les versions successives.\n\nLes défauts les plus fréquents d’un PRD généré sont des **fonctionnalités ajoutées** que vous n’aviez pas prévues (l’IA a tendance à compléter), des **chiffres inventés** (« augmenter la rétention de 30 % »), des **critères non testables** (« l’interface est intuitive »), du **jargon** et une longueur excessive."},{"id":"crs_mvp_ia_m01_l05_b_2","type":"prompt","title":"Générer le premier jet de votre PRD","tool":"Claude","prompt":"Tu es un product manager expérimenté, habitué aux MVP. À partir de mes notes ci-dessous, rédige un PRD d’une à deux pages maximum, en français, au format Markdown.\n\nStructure imposée :\n1. Problème et contexte\n2. Cible et early adopters\n3. Proposition de valeur (one-liner)\n4. Parcours clé (étapes numérotées)\n5. User stories (formule « En tant que…, je veux…, afin de… », 5 à 10, numérotées US1, US2…)\n6. Critères d’acceptation (formule « Étant donné… quand… alors… », 2 à 3 par user story)\n7. Hors périmètre\n8. Métriques de succès\n9. Contraintes et questions ouvertes\n\nRègles :\n- N’ajoute aucune fonctionnalité absente de mon périmètre ; si tu en suggères, place-les dans une section séparée « Suggestions non retenues ».\n- N’invente aucun chiffre ; si une valeur manque, écris [À DÉFINIR].\n- Chaque critère d’acceptation doit pouvoir être vérifié par un test (oui ou non).\n- Pas de jargon technique : ce document décrit le quoi et le pourquoi, pas le comment.\n\nMes notes :\n- Énoncé de problème : [...]\n- Synthèse anonymisée des entretiens : [...]\n- Proposition de valeur et one-liner : [...]\n- Périmètre MoSCoW et liste « ne fera pas » : [...]\n- Signal de réussite : [...]","tips":"Fonctionne aussi dans ChatGPT. Après la réponse, demandez : « Liste tout ce que tu as ajouté qui ne figurait pas dans mes notes. » Supprimez ou validez chaque ajout. Ne collez aucune donnée personnelle."},{"id":"crs_mvp_ia_m01_l05_b_3","type":"checklist","title":"Relecture critique de votre PRD","items":[{"id":"crs_mvp_ia_m01_l05_b_3_i_1","label":"Le PRD tient en une à deux pages."},{"id":"crs_mvp_ia_m01_l05_b_3_i_2","label":"Chaque affirmation provient de mes notes ou de mes entretiens."},{"id":"crs_mvp_ia_m01_l05_b_3_i_3","label":"Aucune fonctionnalité hors de mon périmètre MoSCoW n’a été ajoutée."},{"id":"crs_mvp_ia_m01_l05_b_3_i_4","label":"Aucun chiffre n’est inventé : les valeurs inconnues sont marquées [À DÉFINIR]."},{"id":"crs_mvp_ia_m01_l05_b_3_i_5","label":"Chaque user story suit la formule « En tant que…, je veux…, afin de… »."},{"id":"crs_mvp_ia_m01_l05_b_3_i_6","label":"Chaque critère d’acceptation se vérifie par oui ou par non."},{"id":"crs_mvp_ia_m01_l05_b_3_i_7","label":"La section hors périmètre reprend ma liste « ne fera pas »."},{"id":"crs_mvp_ia_m01_l05_b_3_i_8","label":"Le document est daté et numéroté (v1)."}]},{"id":"crs_mvp_ia_m01_l05_b_4","type":"texte","markdown":"## Profil technique : votre PRD dans le dépôt\n\nAu module 6, votre PRD deviendra un fichier Markdown de votre dépôt, par exemple `docs/PRD.md`. Vous le référencerez dans les instructions de votre agent de code : le fichier `CLAUDE.md` pour Claude Code, les règles de projet dans Cursor, le fichier `AGENTS.md` pour Codex. L’agent disposera ainsi du contexte à chaque session, sans que vous ayez à réexpliquer le projet.\n\nSoignez vos critères d’acceptation : ils se transforment presque directement en tests automatisés. Résistez en revanche à l’envie d’ajouter une section technique détaillée : l’architecture fera l’objet du module 4, dans un document séparé.","personas":["tech"]},{"id":"crs_mvp_ia_m01_l05_b_5","type":"texte","markdown":"## Profil non technique : votre PRD comme brief pour Bolt.new\n\nAu module 6, votre PRD sera la base de vos demandes à Bolt.new. Vous ne le collerez pas d’un bloc : vous donnerez d’abord le contexte (problème, cible, parcours clé), puis vous ferez construire l’application **une user story à la fois**, en vérifiant les critères d’acceptation avant de passer à la suivante.\n\nC’est pourquoi la qualité de vos user stories compte autant : une user story claire donne une demande claire, et une demande claire donne un résultat que vous pouvez vérifier.","personas":["non_tech"]},{"id":"crs_mvp_ia_m01_l05_b_6","type":"texte","markdown":"## Profil reconversion : le vocabulaire du PRD\n\n| Mot | Signification |\n| --- | --- |\n| PRD | Document qui décrit ce que le produit doit faire, et pourquoi |\n| User story | Un besoin d’utilisateur, en une phrase : « En tant que…, je veux…, afin de… » |\n| Critère d’acceptation | Une condition vérifiable qui dit si une user story est terminée |\n| Hors périmètre | Ce que le produit ne fera pas dans cette version |\n| Métrique | Un chiffre que l’on suit pour savoir si le produit atteint son but |\n\nVotre premier PRD n’a pas besoin d’être parfait : c’est une version 1, que vous améliorerez après les maquettes et les tests. Ce qui compte, c’est qu’il soit clair et honnête.","personas":["reconversion"]},{"id":"crs_mvp_ia_m01_l05_b_7","type":"exercice","title":"Votre PRD v1","instructions":"Rédigez le PRD v1 de votre MVP.\n\n1. Générez un premier jet avec le prompt ci-dessus, à partir de vos livrables des leçons précédentes.\n2. Relisez-le avec la checklist de relecture critique et corrigez-le à la main.\n3. Publiez-le dans votre page Notion « Mon MVP » (sous-page PRD), sous le titre « PRD v1 » suivi de la date.\n4. En fin de document, ajoutez une courte note : ce que vous avez modifié par rapport au premier jet de l’IA, et pourquoi.\n5. Rendez la page accessible en lecture seule par lien (option de partage ou de publication de Notion), vérifiez que le lien s’ouvre dans une fenêtre de navigation privée, puis collez-le dans le champ de réponse.","deliverable":"lien","estimatedMinutes":30,"review":"formateur","rubric":["Les neuf sections sont présentes et le document tient en une à deux pages.","Les user stories suivent la formule et couvrent tout le parcours clé.","Chaque user story a des critères d’acceptation testables.","Le hors périmètre et les métriques sont cohérents avec le scope du MVP.","La note de relecture montre un regard critique sur le premier jet de l’IA."]}]$q$::jsonb)
on conflict (id) do nothing;

insert into crm.academy_lessons (id, course_id, module_id, position, title, summary, estimated_minutes, is_preview, blocks)
values ($q$crs_mvp_ia_m01_l06$q$, $q$crs_mvp_ia$q$, $q$crs_mvp_ia_m01$q$, 5, $q$Piloter son projet en mode agile$q$, $q$Organiser votre projet en sprints d’une semaine avec un backlog Notion et une définition de « fini ».$q$, 60, false, $q$[{"id":"crs_mvp_ia_m01_l06_b_1","type":"texte","markdown":"À la fin de cette leçon, vous saurez organiser votre projet en sprints d’une semaine, tenir un backlog dans Notion et planifier votre construction jusqu’à la fin de la formation.\n\n## La gestion de projet digital en bref\n\nUn projet se définit par un **objectif**, un **périmètre** (ce qui sera fait), un **délai**, des **ressources** (votre temps, votre budget, vos outils) et un niveau de **qualité**. Ces éléments sont liés : si le périmètre grossit, le délai s’allonge ou la qualité baisse.\n\nPour un MVP, la règle est simple : **on fixe le délai et le niveau de qualité, et on ajuste le périmètre**. Votre parcours clé doit être fiable et en ligne à une date donnée ; ce qui ne tient pas dans ce délai passe dans la catégorie « pas cette fois ».\n\n## Les rôles, même quand on est seul\n\n| Rôle | Responsabilité | Seul | En binôme |\n| --- | --- | --- | --- |\n| Responsable produit | Définit et ordonne les priorités, tranche les arbitrages | Vous | L’un des deux, désigné à l’avance |\n| Facilitateur | Protège le rythme, anime les rituels, lève les obstacles | Vous | À tour de rôle |\n| Réalisation | Construit, teste, met en ligne, avec l’aide d’agents IA | Vous | Les deux |\n| Parties prenantes | Donnent leur avis, testent, conseillent | Testeurs, formateur, mentors | Idem |\n\nSeul, vous portez toutes les casquettes : séparez les moments. En début de semaine, vous êtes responsable produit et vous décidez ; le reste de la semaine, vous réalisez sans remettre en cause les priorités à chaque heure. En binôme, décidez dès maintenant qui tranche en cas de désaccord sur une priorité.\n\n## Scrum, adapté à votre projet\n\nScrum est un cadre de travail agile : on avance par cycles courts, on livre quelque chose d’utilisable à chaque cycle, et on améliore sa façon de travailler en continu. Sa définition de référence est le Scrum Guide, disponible sur [scrum.org](https://www.scrum.org). Nous en utilisons ici une version allégée, adaptée à une ou deux personnes : ce n’est pas du Scrum au sens strict, mais ses principes sont conservés.\n\n### Les éléments\n\n- **Le sprint** : un cycle d’une semaine, avec un **objectif de sprint** en une phrase (« Le client peut réserver et payer un créneau »).\n- **Le backlog produit** : la liste ordonnée de tout ce qui reste à faire (user stories, tâches, corrections). Le plus important est en haut.\n- **Le backlog de sprint** : les éléments choisis pour la semaine, et seulement ceux-là.\n- **L’estimation** : une taille simple par élément : S (moins d’une demi-journée), M (environ une journée), L (davantage, donc à découper).\n- **La définition de « fini »** : une liste de conditions communes à tous les éléments. Un élément n’est « fait » que s’il les remplit toutes.\n\nLa définition de « fini » de Créno :\n\n- les critères d’acceptation de la user story sont vérifiés ;\n- le parcours fonctionne sur mobile et sur ordinateur ;\n- le code est enregistré sur GitHub (ou le projet Bolt.new est sauvegardé) ;\n- la fonctionnalité est déployée sur une adresse de test ;\n- aucun secret n’apparaît dans le code ni dans les prompts.\n\n### Les rituels\n\n| Rituel | Quand | Durée | Question clé |\n| --- | --- | --- | --- |\n| Planification | Début de sprint | 30 min | Quel objectif cette semaine, et quels éléments pour l’atteindre ? |\n| Point quotidien | Chaque séance de travail | 5 min | Qu’ai-je fait, que vais-je faire, qu’est-ce qui me bloque ? |\n| Revue | Fin de sprint | 30 min | Qu’est-ce qui fonctionne réellement ? Montrez-le à quelqu’un. |\n| Rétrospective | Après la revue | 15 min | Qu’est-ce qui a bien marché, mal marché, et que change-t-on ? |\n\nLe point quotidien peut se faire dans votre journal de bord. La revue gagne à se faire devant une autre personne : un testeur, un proche, votre binôme. La rétrospective produit **une** action concrète pour le sprint suivant, pas dix.\n\n## Votre tableau dans Notion\n\nNotion permet de créer une base de données et de l’afficher sous forme de tableau Kanban (une colonne par statut) ou de liste. Créez une base « Backlog » avec ces propriétés :\n\n| Propriété | Type | Valeurs |\n| --- | --- | --- |\n| Titre | Titre | La user story ou la tâche |\n| Statut | Statut ou sélection | À faire, En cours, Fait |\n| Priorité | Sélection | Must, Should, Could, Won’t |\n| Taille | Sélection | S, M, L |\n| Sprint | Sélection | Sprint 1, Sprint 2… |\n| Critères d’acceptation | Texte | Copiés depuis le PRD |\n\nCréez deux vues : un **tableau Kanban** filtré sur le sprint en cours (votre outil de la semaine) et une **liste** complète triée par priorité (votre backlog produit). D’autres outils font la même chose, comme GitHub Projects, Trello ou un simple tableur : l’important est d’en avoir **un seul**, et à jour.\n\n## Planifier vos sprints sur la formation\n\nVotre planning dépend du temps dont vous disposez chaque semaine. À titre d’exemple, avec 5 à 6 heures par semaine :\n\n| Sprint | Objectif | Modules |\n| --- | --- | --- |\n| 1 | Problème et cible étayés, PRD v1 | 1 |\n| 2 | Prompts de travail et stack choisie | 2 et 3 |\n| 3 | Modèle de données et maquettes du parcours clé | 4 et 5 |\n| 4 à 6 | Parcours clé construit et en ligne | 6 |\n| 7 | Tests utilisateurs et corrections | 7 |\n| 8 | Page de lancement et premières actions d’acquisition | 8 |\n| 9 | Deck, pitch vidéo et roadmap | 9 |\n\nAdaptez ce tableau à votre rythme et gardez de la marge : ne planifiez pas plus des deux tiers de votre temps disponible, les imprévus se chargeront du reste.\n\n## Les pièges à éviter\n\n- **Le sprint surchargé** : mieux vaut terminer trois éléments que d’en commencer huit.\n- **Le backlog infini** : une liste de souhaits n’est pas un plan ; archivez ce qui ne sera jamais fait.\n- **La priorité qui change tous les jours** : sauf urgence, les changements attendent la planification suivante.\n- **La rétrospective sautée** : c’est pourtant elle qui rend le sprint suivant plus efficace."},{"id":"crs_mvp_ia_m01_l06_b_2","type":"texte","markdown":"## Profil technique : relier votre backlog et GitHub\n\nVous pouvez gérer vos tâches dans les issues de GitHub et GitHub Projects plutôt que dans Notion : c’est pertinent si vous travaillez surtout dans votre éditeur. Choisissez un seul outil de référence et tenez-vous-y.\n\nComplétez votre définition de « fini » : le code généré par l’agent a été relu, les tests automatisés passent, et chaque user story correspond à une branche et à des commits aux messages explicites (par exemple « US3 : paiement de la réservation »). Vous mettrez cela en pratique au module 6.","personas":["tech"]},{"id":"crs_mvp_ia_m01_l06_b_3","type":"texte","markdown":"## Profil non technique : une user story, une demande\n\nDans Bolt.new, découpez votre travail comme votre backlog : une user story par demande, vérifiée avant de passer à la suivante. Si une user story est de taille L, découpez-la avant de la confier à l’outil.\n\nVotre revue de fin de sprint est particulièrement précieuse : montrez votre parcours à une personne de votre cible, même s’il est incomplet. Vous verrez très tôt ce qui n’est pas clair.","personas":["non_tech"]},{"id":"crs_mvp_ia_m01_l06_b_4","type":"texte","markdown":"## Profil reconversion : commencer simple\n\nLe vocabulaire de l’agilité est souvent anglais et abondant. Retenez l’essentiel : un **sprint** est une semaine de travail avec un objectif ; le **backlog** est votre liste de choses à faire, classée par importance ; la **revue** consiste à montrer ce qui fonctionne ; la **rétrospective**, à se demander comment mieux travailler.\n\nSi Notion vous semble intimidant, commencez par un tableau à trois colonnes (À faire, En cours, Fait) et ajoutez les propriétés une par une. Un outil simple et à jour vaut mieux qu’un outil complet et abandonné.","personas":["reconversion"]},{"id":"crs_mvp_ia_m01_l06_b_5","type":"prompt","title":"Transformer votre PRD en backlog","tool":"Tout assistant IA","prompt":"Voici les user stories, les critères d’acceptation et le périmètre MoSCoW de mon PRD :\n\n[COLLEZ LES SECTIONS CONCERNÉES DE VOTRE PRD]\n\nJe dispose d’environ [NOMBRE] heures par semaine, en sprints d’une semaine.\n\n1. Transforme chaque user story en éléments de backlog de taille S ou M (découpe les plus gros), avec leur priorité MoSCoW.\n2. Présente le résultat sous forme de tableau : Titre, Priorité, Taille, Dépendances.\n3. Propose une répartition des éléments Must et Should en sprints, sans dépasser les deux tiers de mon temps disponible par sprint.\n4. Signale les éléments dont l’estimation te paraît incertaine.\n\nN’ajoute aucun élément qui ne découle pas de mes user stories.","tips":"Recopiez ensuite le tableau dans votre base Notion (ou importez-le au format CSV). Vérifiez les tailles proposées : l’IA ne connaît ni votre niveau ni vos outils."},{"id":"crs_mvp_ia_m01_l06_b_6","type":"exercice","title":"Votre backlog Notion et votre planning de sprints","instructions":"1. Créez la base « Backlog » dans votre page Notion « Mon MVP », avec les propriétés de la leçon.\n2. Ajoutez au moins 10 éléments issus de votre PRD, avec leur priorité et leur taille ; découpez tout élément de taille L.\n3. Créez les deux vues : tableau Kanban du sprint en cours et liste complète triée par priorité.\n4. Rédigez votre définition de « fini » (4 à 6 conditions) en haut de la page.\n5. Ajoutez votre planning de sprints jusqu’à la fin de la formation, adapté à votre temps disponible.\n6. Préparez le sprint 1 : un objectif en une phrase et les éléments sélectionnés.\n\nPartagez la page en lecture seule et collez le lien dans le champ de réponse. En binôme, précisez qui tient le rôle de responsable produit.","deliverable":"lien","estimatedMinutes":35,"review":"formateur","rubric":["Le backlog contient au moins 10 éléments priorisés et dimensionnés, sans élément de taille L.","Les deux vues (Kanban du sprint, liste complète) sont en place.","La définition de « fini » est concrète et vérifiable.","Le planning de sprints est réaliste au regard du temps disponible.","Le sprint 1 a un objectif clair et un contenu cohérent avec cet objectif."]}]$q$::jsonb)
on conflict (id) do nothing;

insert into crm.academy_lessons (id, course_id, module_id, position, title, summary, estimated_minutes, is_preview, blocks)
values ($q$crs_mvp_ia_m01_l07$q$, $q$crs_mvp_ia$q$, $q$crs_mvp_ia_m01$q$, 6, $q$Évaluation du module$q$, $q$Valider vos acquis du module 1 avec un quiz évalué.$q$, 20, false, $q$[{"id":"crs_mvp_ia_m01_l07_b_1","type":"texte","markdown":"Ce quiz évalue vos acquis sur l’ensemble du module 1 : problème et hypothèses, cible et entretiens, proposition de valeur, périmètre du MVP, PRD et organisation agile. Il compte dans votre évaluation.\n\n## Avant de commencer\n\n- Prévoyez une quinzaine de minutes au calme.\n- Chaque question a une seule bonne réponse.\n- Chaque question est accompagnée d’une explication : lisez-la, même quand vous avez répondu juste.\n- Le score attendu est indiqué dans le livret d’accueil. Si une notion vous a échappé, relisez la leçon correspondante et n’hésitez pas à interroger votre formateur via la messagerie de Mon espace."},{"id":"crs_mvp_ia_m01_l07_b_2","type":"quiz","title":"Évaluation du module 1 : cadrer son problème et son MVP","graded":true,"questions":[{"id":"crs_mvp_ia_m01_l07_b_2_q_1","prompt":"Lequel de ces énoncés de problème est le plus exploitable ?","kind":"unique","options":[{"id":"crs_mvp_ia_m01_l07_b_2_q_1_o_1","label":"« Les coachs ont besoin d’une application de réservation. »","correct":false},{"id":"crs_mvp_ia_m01_l07_b_2_q_1_o_2","label":"« Le marché du sport est en pleine croissance. »","correct":false},{"id":"crs_mvp_ia_m01_l07_b_2_q_1_o_3","label":"« Les coachs indépendants passent leurs soirées à caler leurs séances par messages et à relancer les impayés, ce qui leur coûte du temps non facturé. »","correct":true},{"id":"crs_mvp_ia_m01_l07_b_2_q_1_o_4","label":"« Les gens veulent faire plus de sport. »","correct":false}],"explanation":"Un énoncé exploitable précise la cible, la situation, la cause et la conséquence. Les autres décrivent une solution, un contexte de marché ou une généralité."},{"id":"crs_mvp_ia_m01_l07_b_2_q_2","prompt":"Quelle hypothèse faut-il tester en priorité ?","kind":"unique","options":[{"id":"crs_mvp_ia_m01_l07_b_2_q_2_o_1","label":"Celle qui est critique pour le projet et pour laquelle vous avez le moins de preuves","correct":true},{"id":"crs_mvp_ia_m01_l07_b_2_q_2_o_2","label":"Celle qui est la plus facile à tester","correct":false},{"id":"crs_mvp_ia_m01_l07_b_2_q_2_o_3","label":"Celle que votre entourage trouve la plus convaincante","correct":false},{"id":"crs_mvp_ia_m01_l07_b_2_q_2_o_4","label":"Toujours celle qui concerne la faisabilité technique","correct":false}],"explanation":"On teste d’abord ce qui ferait s’effondrer le projet si c’était faux et que l’on n’a pas encore prouvé. Une hypothèse facile à tester mais secondaire peut attendre."},{"id":"crs_mvp_ia_m01_l07_b_2_q_3","prompt":"Parmi ces personnes, laquelle correspond le mieux à un early adopter pour Créno ?","kind":"unique","options":[{"id":"crs_mvp_ia_m01_l07_b_2_q_3_o_1","label":"Une coach indépendante débordée par les messages, qui a déjà essayé un agenda partagé sans succès et que vous pouvez joindre facilement","correct":true},{"id":"crs_mvp_ia_m01_l07_b_2_q_3_o_2","label":"Un coach salarié d’une grande salle de sport, dont le planning est géré par son employeur","correct":false},{"id":"crs_mvp_ia_m01_l07_b_2_q_3_o_3","label":"Un ami sportif qui trouve l’idée excellente","correct":false},{"id":"crs_mvp_ia_m01_l07_b_2_q_3_o_4","label":"Une coach satisfaite de son outil actuel, qui ne cherche rien d’autre","correct":false}],"explanation":"Un early adopter a le problème, en a conscience, cherche ou bricole déjà une solution, a les moyens de changer et est accessible."},{"id":"crs_mvp_ia_m01_l07_b_2_q_4","prompt":"Quelle question respecte les bonnes pratiques d’un entretien de découverte ?","kind":"unique","options":[{"id":"crs_mvp_ia_m01_l07_b_2_q_4_o_1","label":"« Utiliseriez-vous une application qui gère vos réservations ? »","correct":false},{"id":"crs_mvp_ia_m01_l07_b_2_q_4_o_2","label":"« Ne trouvez-vous pas que les messages font perdre beaucoup de temps ? »","correct":false},{"id":"crs_mvp_ia_m01_l07_b_2_q_4_o_3","label":"« Racontez-moi comment s’est passée la dernière réservation que vous avez gérée. »","correct":true},{"id":"crs_mvp_ia_m01_l07_b_2_q_4_o_4","label":"« Combien paieriez-vous pour mon application ? »","correct":false}],"explanation":"Les questions sur le passé concret produisent des faits. Les autres sont hypothétiques, orientées ou centrées sur votre solution, et suscitent des réponses de complaisance."},{"id":"crs_mvp_ia_m01_l07_b_2_q_5","prompt":"Quel one-liner est le mieux formulé ?","kind":"unique","options":[{"id":"crs_mvp_ia_m01_l07_b_2_q_5_o_1","label":"« Créno, la plateforme révolutionnaire du coaching propulsée par l’IA. »","correct":false},{"id":"crs_mvp_ia_m01_l07_b_2_q_5_o_2","label":"« Créno aide les coachs sportifs indépendants à remplir leur planning et à être payés d’avance, sans échanger de messages. »","correct":true},{"id":"crs_mvp_ia_m01_l07_b_2_q_5_o_3","label":"« Créno est une application web construite avec Next.js, Supabase et Stripe. »","correct":false},{"id":"crs_mvp_ia_m01_l07_b_2_q_5_o_4","label":"« Créno, pour tous ceux qui aiment le sport. »","correct":false}],"explanation":"Un bon one-liner nomme une cible précise et un résultat concret, sans superlatif ni jargon technique."},{"id":"crs_mvp_ia_m01_l07_b_2_q_6","prompt":"Quelle est la différence entre un MVP concierge et un MVP magicien d’Oz ?","kind":"unique","options":[{"id":"crs_mvp_ia_m01_l07_b_2_q_6_o_1","label":"Dans le concierge, le client sait qu’une personne rend le service ; dans le magicien d’Oz, le service semble automatique alors qu’une personne agit en coulisses","correct":true},{"id":"crs_mvp_ia_m01_l07_b_2_q_6_o_2","label":"Le concierge est entièrement automatisé, le magicien d’Oz est manuel","correct":false},{"id":"crs_mvp_ia_m01_l07_b_2_q_6_o_3","label":"Le magicien d’Oz est une landing page, le concierge une application","correct":false},{"id":"crs_mvp_ia_m01_l07_b_2_q_6_o_4","label":"Il n’y a aucune différence : ce sont deux noms pour le même type de MVP","correct":false}],"explanation":"Les deux sont réalisés à la main, mais le concierge l’assume auprès du client, alors que le magicien d’Oz présente une interface qui semble automatisée."},{"id":"crs_mvp_ia_m01_l07_b_2_q_7","prompt":"Dans la méthode MoSCoW, où classez-vous une application mobile à installer pour Créno, alors que le parcours clé fonctionne déjà dans le navigateur ?","kind":"unique","options":[{"id":"crs_mvp_ia_m01_l07_b_2_q_7_o_1","label":"Must have","correct":false},{"id":"crs_mvp_ia_m01_l07_b_2_q_7_o_2","label":"Should have","correct":false},{"id":"crs_mvp_ia_m01_l07_b_2_q_7_o_3","label":"Could have","correct":false},{"id":"crs_mvp_ia_m01_l07_b_2_q_7_o_4","label":"Won’t have this time","correct":true}],"explanation":"Le parcours clé fonctionne sans elle et elle demanderait un effort important : elle est consciemment exclue du MVP, quitte à revenir plus tard si les utilisateurs la réclament."},{"id":"crs_mvp_ia_m01_l07_b_2_q_8","prompt":"Lequel de ces critères d’acceptation est correctement rédigé ?","kind":"unique","options":[{"id":"crs_mvp_ia_m01_l07_b_2_q_8_o_1","label":"« L’interface de paiement est simple et intuitive. »","correct":false},{"id":"crs_mvp_ia_m01_l07_b_2_q_8_o_2","label":"« Étant donné un créneau complet, quand un client ouvre la page, alors il ne peut pas le réserver. »","correct":true},{"id":"crs_mvp_ia_m01_l07_b_2_q_8_o_3","label":"« Le paiement doit être rapide. »","correct":false},{"id":"crs_mvp_ia_m01_l07_b_2_q_8_o_4","label":"« Les utilisateurs aiment la page de réservation. »","correct":false}],"explanation":"Un critère d’acceptation se vérifie par oui ou par non. « Simple », « rapide » ou « aiment » ne sont pas vérifiables en l’état."},{"id":"crs_mvp_ia_m01_l07_b_2_q_9","prompt":"Pour un MVP, quelle variable ajuste-t-on en priorité lorsque le temps manque ?","kind":"unique","options":[{"id":"crs_mvp_ia_m01_l07_b_2_q_9_o_1","label":"Le délai : on repousse la mise en ligne","correct":false},{"id":"crs_mvp_ia_m01_l07_b_2_q_9_o_2","label":"La qualité : on accepte un parcours clé qui fonctionne mal","correct":false},{"id":"crs_mvp_ia_m01_l07_b_2_q_9_o_3","label":"Le périmètre : on retire ce qui n’est pas indispensable au parcours clé","correct":true},{"id":"crs_mvp_ia_m01_l07_b_2_q_9_o_4","label":"Les ressources : on ajoute des outils payants","correct":false}],"explanation":"On fixe le délai et le niveau de qualité, et on ajuste le périmètre. C’est tout l’intérêt de la priorisation MoSCoW."},{"id":"crs_mvp_ia_m01_l07_b_2_q_10","prompt":"À quoi sert la rétrospective en fin de sprint ?","kind":"unique","options":[{"id":"crs_mvp_ia_m01_l07_b_2_q_10_o_1","label":"À montrer le produit à des utilisateurs","correct":false},{"id":"crs_mvp_ia_m01_l07_b_2_q_10_o_2","label":"À choisir les éléments du prochain sprint","correct":false},{"id":"crs_mvp_ia_m01_l07_b_2_q_10_o_3","label":"À identifier une amélioration concrète de votre façon de travailler pour le sprint suivant","correct":true},{"id":"crs_mvp_ia_m01_l07_b_2_q_10_o_4","label":"À réécrire entièrement le PRD","correct":false}],"explanation":"La revue sert à montrer ce qui fonctionne, la planification à choisir les éléments du sprint ; la rétrospective porte sur la façon de travailler et produit une action concrète."}]}]$q$::jsonb)
on conflict (id) do nothing;

insert into crm.academy_lessons (id, course_id, module_id, position, title, summary, estimated_minutes, is_preview, blocks)
values ($q$crs_mvp_ia_m02_l01$q$, $q$crs_mvp_ia$q$, $q$crs_mvp_ia_m02$q$, 0, $q$Comment fonctionne un assistant IA (et ce qu'il ne sait pas faire)$q$, $q$Modèle de langage, contexte, hallucinations, date de connaissance et confidentialité : les bases pour utiliser Claude ou ChatGPT en connaissance de cause.$q$, 40, false, $q$[{"id":"crs_mvp_ia_m02_l01_b_1","type":"texte","markdown":"À la fin de cette leçon, vous saurez expliquer simplement comment un assistant IA produit ses réponses, où il se trompe, et quelles précautions prendre avant de lui confier vos données. On guide mieux un outil dont on comprend le fonctionnement.\n\n## Un modèle de langage, c'est quoi ?\n\nClaude (édité par Anthropic) et ChatGPT (édité par OpenAI) reposent sur des **modèles de langage** (en anglais *large language models*, ou LLM). Un modèle de langage est un programme entraîné sur une très grande quantité de textes pour une tâche précise : prédire la suite la plus plausible d'un texte.\n\nQuand vous posez une question, le modèle ne « cherche » pas la réponse dans une base de données. Il la génère morceau par morceau. Ces morceaux s'appellent des **tokens** : un token correspond à un mot, un bout de mot ou un signe de ponctuation. À chaque étape, le modèle calcule quels tokens sont les plus probables compte tenu de tout ce qui précède, en choisit un, puis recommence.\n\nDeux conséquences pratiques :\n\n- **La génération est probabiliste.** La même question posée deux fois peut donner deux réponses différentes. C'est normal : relancez, comparez, gardez la meilleure.\n- **Le modèle produit du texte plausible, pas du texte vérifié.** Une réponse bien rédigée n'est pas forcément exacte.\n\n## Le contexte : tout ce que le modèle « voit »\n\nLe **contexte** est l'ensemble du texte que le modèle prend en compte pour répondre : vos consignes, l'historique de la conversation, les fichiers joints, les résultats d'une recherche web. En dehors des fonctions de mémoire ou de consignes persistantes (leçon 3), le modèle ne sait de vous que ce qui figure dans ce contexte.\n\nCe contexte a une taille maximale, la **fenêtre de contexte**, mesurée en tokens. Elle est large sur les assistants actuels, mais pas infinie. Dans une conversation très longue, les éléments anciens peuvent être moins bien pris en compte, résumés ou sortir de la fenêtre. D'où une règle simple : **ce qui compte doit être dit clairement, et redit si la conversation s'allonge.**\n\n## Les « hallucinations »\n\nOn appelle **hallucination** une réponse fausse présentée avec assurance : une référence qui n'existe pas, une fonction de code inventée, un chiffre sorti de nulle part, un article de loi mal cité. Ce n'est pas un bug ponctuel, c'est une conséquence directe de la génération probabiliste : le modèle comble les trous avec du plausible.\n\nLe risque augmente quand :\n\n- la question porte sur un sujet pointu, récent ou peu documenté ;\n- vous demandez des chiffres, des dates, des noms propres ou des sources précises ;\n- le prompt est flou et laisse le modèle deviner ce que vous voulez ;\n- vous insistez pour obtenir une réponse coûte que coûte.\n\nParades : fournir vous-même les documents de référence, autoriser explicitement la réponse « je ne sais pas », demander de distinguer ce qui est sûr de ce qui est supposé, et vérifier toute information factuelle qui compte.\n\n## La date de connaissance\n\nUn modèle est entraîné sur des données collectées jusqu'à une certaine date : sa **date de coupure des connaissances**. Il ignore ce qui s'est passé ensuite : nouvelles versions d'outils, changements de tarifs, nouvelles règles. Pour un projet qui s'appuie sur des outils qui évoluent vite (Supabase, Next.js, Bolt.new…), c'est une vigilance permanente : le code ou les conseils générés peuvent correspondre à une version dépassée.\n\n## Recherche web et fichiers joints\n\nLes assistants proposent en général deux moyens d'élargir le contexte :\n\n- **la recherche web** : l'assistant lance des recherches, lit des pages et cite ses sources. Utile pour l'actualité et la documentation récente. Vérifiez que les sources citées existent et disent bien ce qui est annoncé ;\n- **les fichiers joints** : PDF, tableur, capture d'écran, document de spécification. Le modèle travaille alors sur *vos* informations plutôt que sur sa mémoire générale. C'est le moyen le plus simple de réduire les hallucinations.\n\n> [!tip] Réflexe à prendre : quand la réponse dépend d'une information précise (documentation d'un outil, conditions tarifaires, texte de loi), donnez la source à l'assistant ou demandez-lui de la chercher et de la citer, plutôt que de le croire sur parole."},{"id":"crs_mvp_ia_m02_l01_b_2","type":"video","title":"Ce qui se passe quand vous envoyez un prompt","url":"","durationMinutes":6,"script":"- Accroche : la même question sur Créno posée deux fois, deux réponses différentes à l'écran. Pourquoi ?\n- Schéma animé : prompt → découpage en tokens → prédiction du token suivant → réponse. Insister sur « plausible » plutôt que « vrai ».\n- La fenêtre de contexte : illustration d'une longue conversation dont le début « s'efface » progressivement.\n- Démonstration d'une hallucination : demander une référence précise qui n'existe pas, puis montrer comment la débusquer (demander la source, vérifier).\n- Même question avec la documentation jointe ou la recherche web activée : réponse sourcée, plus fiable.\n- Confidentialité : où se trouvent les réglages de confidentialité d'un assistant (sans montrer d'offre ni de prix) ; remplacer des données réelles par des données fictives.\n- Conclusion : trois réflexes — donner le contexte, vérifier, ne rien coller de sensible."},{"id":"crs_mvp_ia_m02_l01_b_3","type":"texte","markdown":"## Le vocabulaire essentiel\n\n| Terme | En clair |\n| --- | --- |\n| IA générative | Une IA qui produit un contenu nouveau : texte, code, image |\n| Modèle de langage (LLM) | Le « moteur » de l'assistant, entraîné à prédire la suite d'un texte |\n| Prompt | La consigne que vous écrivez à l'IA |\n| Token | Un petit morceau de texte (mot ou bout de mot), l'unité de mesure des modèles |\n| Contexte | Tout ce que l'IA a sous les yeux pour vous répondre |\n| Hallucination | Une information fausse présentée avec assurance |\n| Agent | Une IA qui agit (ouvre des fichiers, navigue, exécute des commandes) pour atteindre un objectif |\n\nVous n'avez pas besoin de comprendre les mathématiques des modèles pour bien les utiliser, pas plus qu'il ne faut être mécanicien pour bien conduire. Ce qui compte : savoir ce que l'outil fait bien, où il se trompe, et comment le guider. C'est exactement l'objet de ce module.","personas":["non_tech","reconversion"]},{"id":"crs_mvp_ia_m02_l01_b_4","type":"texte","markdown":"## Pour les profils techniques\n\n- **Tokens et coûts** : via une API (l'accès programmatique au modèle), la facturation et les limites se comptent en tokens d'entrée et de sortie. Un prompt verbeux ou un historique complet renvoyé à chaque appel a un coût direct.\n- **API sans état** : un appel d'API ne se souvient de rien. C'est votre code qui renvoie l'historique utile à chaque requête ; les interfaces de chat le font pour vous.\n- **Message système** : les API distinguent en général les consignes de cadrage (message système) des messages de l'utilisateur. C'est l'équivalent programmatique des consignes persistantes.\n- **Paramètres d'échantillonnage** : la *température* et les paramètres voisins règlent la part d'aléatoire de la génération. Utile pour stabiliser une extraction de données, mais aucun réglage ne supprime les hallucinations.\n- **Sorties structurées** : demandez du JSON conforme à un schéma, et validez-le toujours côté code.\n\nVous intégrerez un modèle de langage dans un produit au module 6.","personas":["tech"]},{"id":"crs_mvp_ia_m02_l01_b_5","type":"texte","markdown":"## Confidentialité : ce que vous tapez n'est pas anodin\n\nTout ce que vous saisissez dans un assistant est envoyé aux serveurs de l'éditeur. Selon l'outil, le type de compte et vos réglages, ces échanges peuvent être conservés un certain temps, et parfois utilisés pour améliorer les modèles. Ces règles évoluent : lisez les paramètres de confidentialité et les conditions d'utilisation de l'outil au moment où vous l'utilisez.\n\nRepères durables :\n\n- **Réglages** : la plupart des assistants proposent des options sur l'historique et sur l'utilisation de vos conversations pour l'entraînement. Vérifiez-les dès la création du compte.\n- **Comptes professionnels** : les offres destinées aux entreprises prévoient généralement des engagements contractuels plus stricts sur l'usage des données et l'administration des accès. Si vous devez traiter des données de clients, c'est ce type de compte qu'il faut examiner.\n- **Données à ne jamais coller** : mots de passe, clés d'API (les codes secrets qui donnent accès à un service ou à votre base de données), données bancaires, données de santé, fichiers clients nominatifs. Remplacez-les par des données fictives ou anonymisées (« Client A, 34 ans, Lyon »).\n\n## Et le RGPD ?\n\nLe **RGPD** (Règlement général sur la protection des données) encadre le traitement des données personnelles des personnes situées dans l'Union européenne. Coller une liste de clients dans un assistant IA est un traitement de données personnelles : il faut une raison légitime (une « base légale »), informer les personnes, limiter les données au strict nécessaire et savoir où elles partent, y compris hors de l'Union européenne. La CNIL publie des recommandations sur l'IA et les données personnelles : consultez [cnil.fr](https://www.cnil.fr). Ces informations sont générales et ne constituent pas un conseil juridique ; pour un cas précis, faites-vous accompagner.\n\nPour Créno, concrètement : on fait travailler l'IA sur des profils de coachs et de clients **fictifs**, jamais sur l'export réel des réservations.\n\n## Claude ou ChatGPT ?\n\nLes deux assistants ont beaucoup en commun : conversation en langage naturel, analyse de fichiers, recherche web, génération de code, consignes persistantes, déclinaisons dédiées au code (Claude Code d'un côté, Codex de l'autre) et modes agents. Leurs forces relatives évoluent à chaque nouvelle version, et les comparatifs publiés vieillissent vite.\n\nLa méthode fiable : **tester sur vos propres tâches**. Choisissez trois tâches réelles de votre projet, soumettez le même prompt aux deux outils, et comparez selon des critères fixés à l'avance : exactitude, respect des consignes, clarté, temps de correction nécessaire. Rien n'empêche ensuite d'utiliser les deux, selon la tâche."},{"id":"crs_mvp_ia_m02_l01_b_6","type":"checklist","title":"Avant de coller un contenu dans un assistant IA","items":[{"id":"crs_mvp_ia_m02_l01_b_6_i_1","label":"Le contenu ne contient ni mot de passe, ni clé d'API, ni donnée bancaire."},{"id":"crs_mvp_ia_m02_l01_b_6_i_2","label":"Les noms, e-mails et téléphones de personnes réelles ont été remplacés par des données fictives."},{"id":"crs_mvp_ia_m02_l01_b_6_i_3","label":"J'ai vérifié les réglages de confidentialité de mon compte (historique, utilisation pour l'entraînement)."},{"id":"crs_mvp_ia_m02_l01_b_6_i_4","label":"Pour des données clients réelles, j'utilise un compte professionnel dont j'ai lu les engagements."},{"id":"crs_mvp_ia_m02_l01_b_6_i_5","label":"Je sais quelles informations de la réponse je devrai vérifier (chiffres, dates, sources)."},{"id":"crs_mvp_ia_m02_l01_b_6_i_6","label":"Si la réponse dépend d'une information récente, j'active la recherche web ou je joins la source."}]},{"id":"crs_mvp_ia_m02_l01_b_7","type":"quiz","title":"Auto-évaluation : les bases","graded":false,"questions":[{"id":"crs_mvp_ia_m02_l01_b_7_q_1","prompt":"Pourquoi la même question posée deux fois peut-elle donner deux réponses différentes ?","kind":"unique","options":[{"id":"crs_mvp_ia_m02_l01_b_7_q_1_o_1","label":"Parce que l'assistant a appris de votre première question entre-temps","correct":false},{"id":"crs_mvp_ia_m02_l01_b_7_q_1_o_2","label":"Parce que la génération est probabiliste : le modèle choisit parmi des suites plausibles","correct":true},{"id":"crs_mvp_ia_m02_l01_b_7_q_1_o_3","label":"Parce que la première réponse était forcément fausse","correct":false},{"id":"crs_mvp_ia_m02_l01_b_7_q_1_o_4","label":"Parce que l'assistant consulte une base de données différente à chaque fois","correct":false}],"explanation":"Le modèle génère sa réponse token par token en choisissant parmi les suites les plus probables. Deux essais peuvent donc différer : c'est une occasion de comparer."},{"id":"crs_mvp_ia_m02_l01_b_7_q_2","prompt":"Qu'appelle-t-on une « hallucination » ?","kind":"unique","options":[{"id":"crs_mvp_ia_m02_l01_b_7_q_2_o_1","label":"Une réponse fausse présentée avec assurance","correct":true},{"id":"crs_mvp_ia_m02_l01_b_7_q_2_o_2","label":"Une réponse trop longue","correct":false},{"id":"crs_mvp_ia_m02_l01_b_7_q_2_o_3","label":"Un refus de répondre","correct":false},{"id":"crs_mvp_ia_m02_l01_b_7_q_2_o_4","label":"Une erreur d'affichage de l'interface","correct":false}],"explanation":"Une hallucination est un contenu plausible mais faux (source inventée, chiffre erroné, fonction inexistante). Elle se repère par la vérification sur des sources fiables."},{"id":"crs_mvp_ia_m02_l01_b_7_q_3","prompt":"Vous voulez que l'assistant respecte la documentation actuelle de Supabase. Quelle est la meilleure approche ?","kind":"unique","options":[{"id":"crs_mvp_ia_m02_l01_b_7_q_3_o_1","label":"Lui faire confiance : il connaît forcément la dernière version","correct":false},{"id":"crs_mvp_ia_m02_l01_b_7_q_3_o_2","label":"Lui demander de répondre plus vite","correct":false},{"id":"crs_mvp_ia_m02_l01_b_7_q_3_o_3","label":"Joindre la page de documentation ou activer la recherche web, et demander de citer la source","correct":true},{"id":"crs_mvp_ia_m02_l01_b_7_q_3_o_4","label":"Reposer la question jusqu'à obtenir la réponse attendue","correct":false}],"explanation":"Le modèle a une date de coupure des connaissances. Lui fournir la documentation récente (ou le laisser la chercher en citant ses sources) réduit le risque d'information dépassée."},{"id":"crs_mvp_ia_m02_l01_b_7_q_4","prompt":"Quel contenu pouvez-vous coller dans un assistant sans risque particulier ?","kind":"unique","options":[{"id":"crs_mvp_ia_m02_l01_b_7_q_4_o_1","label":"L'export de vos réservations avec les téléphones des clients","correct":false},{"id":"crs_mvp_ia_m02_l01_b_7_q_4_o_2","label":"La clé secrète de votre compte de paiement, pour qu'il configure l'intégration","correct":false},{"id":"crs_mvp_ia_m02_l01_b_7_q_4_o_3","label":"Le mot de passe de votre base de données","correct":false},{"id":"crs_mvp_ia_m02_l01_b_7_q_4_o_4","label":"Un profil client fictif (« Client A, 34 ans, Lyon ») pour tester un message","correct":true}],"explanation":"Les secrets et les données personnelles réelles ne doivent jamais être collés dans un prompt. Des données fictives ou anonymisées suffisent pour travailler."}]},{"id":"crs_mvp_ia_m02_l01_b_8","type":"exercice","title":"Tester deux assistants sur vos propres tâches","instructions":"Objectif : choisir vos outils sur la base de vos propres observations, pas sur des comparatifs.\n\n1. Choisissez **trois tâches réelles** de votre projet, de nature différente. Exemple Créno : rédiger le texte d'accueil de la page coach ; résumer cinq verbatims d'entretiens fictifs ; proposer la liste des informations à enregistrer pour une réservation.\n2. Avant de tester, écrivez vos **critères de comparaison** (trois au maximum) : exactitude, respect des consignes, ton, temps de correction nécessaire…\n3. Soumettez **exactement le même prompt** à Claude et à ChatGPT. Une version gratuite suffit généralement pour cet exercice. N'utilisez que des données fictives.\n4. Notez chaque réponse de 1 à 5 par critère, et relevez les erreurs ou approximations éventuelles.\n5. Ouvrez les paramètres de confidentialité de chaque outil et notez les réglages que vous avez choisis.\n\nLivrable (texte) : un tableau tâche × outil × notes, vos réglages de confidentialité, et deux phrases de conclusion : quel outil pour quelle tâche, à ce stade.","deliverable":"texte","estimatedMinutes":20,"review":"auto","rubric":["Trois tâches réelles et variées du projet","Critères de comparaison définis avant le test","Même prompt soumis aux deux outils, sans donnée personnelle réelle","Réglages de confidentialité vérifiés et notés","Conclusion appuyée sur les observations"]}]$q$::jsonb)
on conflict (id) do nothing;

insert into crm.academy_lessons (id, course_id, module_id, position, title, summary, estimated_minutes, is_preview, blocks)
values ($q$crs_mvp_ia_m02_l02$q$, $q$crs_mvp_ia$q$, $q$crs_mvp_ia_m02$q$, 1, $q$Anatomie d'un bon prompt$q$, $q$Les sept composantes d'un prompt efficace, un avant / après sur Créno et des gabarits prêts à copier pour votre projet.$q$, 60, false, $q$[{"id":"crs_mvp_ia_m02_l02_b_1","type":"texte","markdown":"À la fin de cette leçon, vous saurez construire un prompt complet en sept composantes et transformer une demande vague en consigne précise, testée sur votre projet.\n\n## Le principe : briefer l'IA comme un prestataire compétent\n\nImaginez que vous confiez une mission à un freelance brillant qui ne connaît ni vous, ni votre projet, ni vos clients. Il fera ce que vous demandez, avec ce que vous lui donnez. Un **prompt** (la consigne que vous écrivez à l'IA) fonctionne de la même façon. La plupart des réponses décevantes viennent d'un brief incomplet, pas d'un outil défaillant.\n\n## Les sept composantes\n\n| Composante | Question à se poser | Exemple (Créno) |\n| --- | --- | --- |\n| Rôle | Quel expert doit répondre ? | « Tu es rédacteur web spécialisé dans les applications pour indépendants. » |\n| Contexte | Que doit-il savoir de la situation ? | « Créno est une application de réservation pour coachs sportifs indépendants… » |\n| Tâche | Qu'attend-on exactement ? | « Rédige le texte de la page d'accueil destinée aux coachs. » |\n| Contraintes | Quelles limites respecter ? | « 150 mots maximum, vouvoiement, aucun superlatif. » |\n| Format de sortie | Sous quelle forme ? | « Un titre, un sous-titre, trois bénéfices en liste, un bouton d'action. » |\n| Exemples | À quoi ressemble un bon résultat ? | Une phrase dont vous aimez le ton. |\n| Critères de qualité | Comment juger le résultat ? | « Un coach doit comprendre en cinq secondes ce qu'il y gagne. » |\n\nToutes les composantes ne sont pas utiles à chaque fois : « traduis cette phrase en anglais » n'en demande que deux. Mais dès que le résultat compte, passez la liste en revue.\n\n- **Rôle.** Il oriente le vocabulaire, le niveau de détail et les réflexes de l'IA. « Tu es product manager » ne produit pas la même liste de fonctionnalités que « tu es développeur ». Un rôle ne donne pas de compétences magiques : il fixe un point de vue.\n- **Contexte.** C'est la composante la plus sous-estimée. Qui sont vos utilisateurs ? Où en est le projet ? Qu'avez-vous déjà essayé ? Qu'est-ce qui est hors sujet ? Plus le contexte est précis, moins l'IA comble les trous avec des généralités.\n- **Tâche.** Un verbe d'action et un livrable : rédige, liste, compare, corrige, propose trois options. Une seule tâche principale par prompt ; si vous en avez quatre, découpez (leçon suivante).\n- **Contraintes.** Longueur, ton, public, vocabulaire interdit, technologies imposées. Préférez les contraintes mesurables (« phrases de moins de 20 mots ») aux formules vagues (« pas trop long »).\n- **Format de sortie.** Tableau, liste, e-mail, plan en sections, JSON (un format de données structuré, lisible par un programme)… Le format rend la réponse directement utilisable et facilite la comparaison entre deux versions.\n- **Exemples.** Un exemple vaut mieux qu'une longue description du ton attendu. Précisez s'il faut s'en inspirer ou le reproduire.\n- **Critères de qualité.** Dites à l'IA comment vous jugerez sa réponse. Elle peut alors la vérifier avant de vous la rendre.\n\n> [!info] Tutoyer ou vouvoyer l'IA n'a pas d'importance majeure. Dans cette formation, les prompts tutoient l'assistant ; choisissez votre convention et restez cohérent."},{"id":"crs_mvp_ia_m02_l02_b_2","type":"texte","markdown":"## Avant / après : le cas Créno\n\nVoici un prompt typique de début de projet :\n\n```text\nÉcris-moi la page d'accueil de mon app de réservation pour coachs.\n```\n\nRésultat probable : un texte générique (« Révolutionnez votre activité ! »), trop long, sans lien avec les vrais utilisateurs. Vous passerez plus de temps à corriger qu'à écrire.\n\nLa version structurée :\n\n```text\nRôle : tu es rédacteur web spécialisé dans les applications pour indépendants.\n\nContexte : Créno est une application web qui permet aux coachs sportifs\nindépendants de publier leurs créneaux et d'être payés en ligne dès la\nréservation. Nos premiers utilisateurs sont des coachs de fitness et de yoga\nqui gèrent aujourd'hui leurs réservations par SMS et encaissent en espèces\nou par virement. Leurs irritants : les annulations de dernière minute et les\nrelances de paiement.\n\nTâche : rédige le texte de la page d'accueil destinée aux coachs.\n\nContraintes : 150 mots maximum, vouvoiement, ton direct et chaleureux,\naucun superlatif, aucune promesse chiffrée.\n\nFormat : un titre (8 mots max), un sous-titre (20 mots max), trois bénéfices\nen liste (une ligne chacun), le libellé d'un bouton d'action.\n\nExemple de ton : « Vos créneaux en ligne, vos paiements à l'heure. »\n\nCritères de qualité : un coach comprend en cinq secondes ce qu'il y gagne ;\nchaque bénéfice répond à un irritant cité dans le contexte.\nPropose deux versions différentes.\n```\n\nCe prompt est plus long, mais il se relit en une minute et produit un résultat exploitable dès le premier essai. Il est aussi **réutilisable** : changez le contexte, et il sert pour la page destinée aux clients.\n\n> [!tip] Demander deux ou trois versions est une astuce simple : vous comparez au lieu de subir, et vous pouvez combiner le meilleur de chacune.\n\n## Les erreurs les plus fréquentes\n\n- **Le prompt télégraphique** : trois mots, et l'IA devine le reste.\n- **Le prompt fourre-tout** : cinq tâches dans un seul message, dont aucune n'est bien traitée.\n- **Le contexte implicite** : « comme on a dit » alors que l'information ne figure pas dans la conversation.\n- **Le format oublié** : un pavé de texte là où il fallait un tableau.\n- **L'absence de relecture** : copier-coller la réponse sans la vérifier."},{"id":"crs_mvp_ia_m02_l02_b_3","type":"prompt","title":"Gabarit de prompt en sept composantes","tool":"Tout assistant IA","prompt":"Rôle : tu es [EXPERTISE] qui s'adresse à [PUBLIC].\n\nContexte : [VOTRE PROJET EN 3 À 5 PHRASES : produit, utilisateurs, situation actuelle, ce qui a déjà été fait].\n\nTâche : [VERBE D'ACTION + LIVRABLE].\n\nContraintes :\n- [LONGUEUR]\n- [TON / REGISTRE]\n- [CE QU'IL NE FAUT PAS FAIRE]\n\nFormat de sortie : [TABLEAU / LISTE / SECTIONS / JSON…].\n\nExemple de résultat attendu : [EXEMPLE, OU « aucun »].\n\nCritères de qualité : [COMMENT JE JUGERAI LA RÉPONSE].\n\nSi une information te manque pour bien répondre, pose-moi tes questions avant de commencer.","tips":"Remplacez chaque élément entre crochets. Supprimez les rubriques inutiles pour les demandes simples. Conservez ce gabarit dans votre bibliothèque de prompts (leçon 6)."},{"id":"crs_mvp_ia_m02_l02_b_4","type":"prompt","title":"Faire diagnostiquer un prompt existant","tool":"Tout assistant IA","prompt":"Voici un prompt que j'utilise pour mon projet :\n---\n[COLLEZ VOTRE PROMPT]\n---\nContexte du projet : [2 À 3 PHRASES].\n\nAnalyse ce prompt selon sept composantes : rôle, contexte, tâche, contraintes, format de sortie, exemples, critères de qualité. Pour chacune, indique si elle est présente, absente ou floue, et pourquoi c'est un problème.\nPropose ensuite une version réécrite, en signalant entre crochets les informations que je dois compléter moi-même. N'invente aucune information sur mon projet."},{"id":"crs_mvp_ia_m02_l02_b_5","type":"texte","markdown":"## Votre expertise métier est votre meilleur atout\n\nVous connaissez vos clients, leurs mots, leurs irritants : c'est exactement ce qui manque à l'IA. Avant de rédiger un prompt, notez trois éléments que vous seul connaissez : une phrase typique d'un client, une objection fréquente, une règle métier (pour Créno : « un coach refuse les annulations moins de 24 h avant la séance »). Glissez-les dans le contexte : la réponse passe de générique à pertinente. Pour bien prompter, vous n'avez pas besoin de vocabulaire technique, vous avez besoin de précision.","personas":["non_tech"]},{"id":"crs_mvp_ia_m02_l02_b_6","type":"texte","markdown":"## Un prompt est une spécification\n\nVous rédigez déjà des tickets, des contrats d'interface et des tests : appliquez les mêmes réflexes. Entrées explicites, sortie typée (un JSON conforme à un schéma que vous fournissez), cas limites énumérés, critères d'acceptation vérifiables. Un prompt à sortie structurée se teste : comparez deux versions d'un même prompt sur les mêmes entrées, comme un test de non-régression. Et méfiez-vous du biais « l'IA a compris » : ce qui n'est pas écrit n'existe pas pour elle.","personas":["tech"]},{"id":"crs_mvp_ia_m02_l02_b_7","type":"texte","markdown":"## Pas à pas : la méthode des trois questions\n\nSi sept composantes vous semblent beaucoup, commencez par trois questions, toujours dans cet ordre : **pour qui ?** (qui lira le résultat), **quoi ?** (le livrable attendu), **sous quelle forme ?** (longueur, format). Exemple : « Pour des coachs sportifs indépendants, écris une présentation de mon service de réservation, en cinq phrases simples. » Quand ce réflexe est acquis, ajoutez le contexte, puis les exemples. Chaque prompt raté vous apprend quelle information manquait : c'est ainsi que l'on progresse.","personas":["reconversion"]},{"id":"crs_mvp_ia_m02_l02_b_8","type":"checklist","title":"Relire son prompt avant de l'envoyer","items":[{"id":"crs_mvp_ia_m02_l02_b_8_i_1","label":"Le rôle attendu est précisé si le résultat dépend d'une expertise."},{"id":"crs_mvp_ia_m02_l02_b_8_i_2","label":"Le contexte décrit le projet, les utilisateurs et la situation actuelle."},{"id":"crs_mvp_ia_m02_l02_b_8_i_3","label":"La tâche tient en une phrase avec un verbe d'action."},{"id":"crs_mvp_ia_m02_l02_b_8_i_4","label":"Les contraintes (longueur, ton, interdits) sont explicites et mesurables."},{"id":"crs_mvp_ia_m02_l02_b_8_i_5","label":"Le format de sortie est indiqué."},{"id":"crs_mvp_ia_m02_l02_b_8_i_6","label":"Un exemple est fourni quand le ton ou la structure comptent."},{"id":"crs_mvp_ia_m02_l02_b_8_i_7","label":"Les critères de qualité sont écrits."},{"id":"crs_mvp_ia_m02_l02_b_8_i_8","label":"Le prompt ne contient aucune donnée personnelle réelle ni aucun secret."}]},{"id":"crs_mvp_ia_m02_l02_b_9","type":"exercice","title":"Réécrire trois prompts de votre projet","instructions":"Objectif : transformer trois demandes réelles en prompts complets, et mesurer la différence.\n\n1. Retrouvez (ou écrivez) **trois prompts courts** que vous avez utilisés ou utiliseriez pour votre projet, sur trois usages différents : un texte destiné à vos utilisateurs, une tâche d'analyse (résumer, comparer, prioriser), une tâche liée au produit (fonctionnalités, parcours, données).\n2. Soumettez chaque prompt tel quel à un assistant et conservez la réponse.\n3. Réécrivez chaque prompt avec le gabarit en sept composantes. Vous pouvez retirer une composante, à condition d'expliquer pourquoi.\n4. Soumettez chaque version réécrite dans une **nouvelle conversation**, pour que l'historique n'influence pas le résultat.\n5. Comparez les deux réponses : qu'est-ce qui s'est amélioré ? Qu'est-ce qui manque encore ?\n\nExemple Créno pour l'usage « produit » : le prompt initial « Quelles fonctionnalités pour mon app ? » devient un prompt qui précise les deux rôles (coach, client), le périmètre du MVP (publier des créneaux, réserver, payer, rappel la veille), la contrainte « huit fonctionnalités maximum, classées par priorité » et le format « tableau fonctionnalité / rôle / priorité / justification ».\n\nLivrable (texte) : pour chacun des trois prompts, la version initiale, la version réécrite et trois lignes d'analyse.","deliverable":"texte","estimatedMinutes":40,"review":"formateur","rubric":["Trois usages différents, tous liés au projet réel","Les prompts réécrits contiennent au minimum rôle, contexte, tâche, contraintes et format","Aucune donnée personnelle réelle ni secret dans les prompts","L'analyse compare concrètement les réponses avant / après","Les limites restantes sont identifiées"]}]$q$::jsonb)
on conflict (id) do nothing;

insert into crm.academy_lessons (id, course_id, module_id, position, title, summary, estimated_minutes, is_preview, blocks)
values ($q$crs_mvp_ia_m02_l03$q$, $q$crs_mvp_ia$q$, $q$crs_mvp_ia_m02$q$, 2, $q$Techniques avancées$q$, $q$Exemples, décomposition, questions préalables, itération, critique, balises, consignes persistantes et reprise des longues conversations.$q$, 60, false, $q$[{"id":"crs_mvp_ia_m02_l03_b_1","type":"texte","markdown":"À la fin de cette leçon, vous saurez utiliser huit techniques qui transforment un assistant IA en véritable partenaire de travail, et les combiner sur une tâche réelle de votre projet.\n\n## 1. Donner des exemples (few-shot)\n\nLe *few-shot* (« quelques exemples ») consiste à montrer à l'IA deux à cinq exemples du résultat attendu avant de lui en demander un nouveau. C'est souvent la technique la plus efficace quand le format ou le ton sont difficiles à décrire.\n\nExemple Créno : pour les messages de rappel envoyés la veille d'une séance, plutôt que de décrire le ton, donnez deux messages que vous jugez réussis, puis demandez-en trois nouveaux pour des cas différents (première séance, séance à domicile, séance en extérieur). Variez vos exemples, sinon l'IA les recopie presque à l'identique.\n\n## 2. Décomposer une tâche\n\nUne tâche complexe demandée en un seul prompt donne un résultat moyen partout. Découpez-la en étapes et validez chacune avant de passer à la suivante. Pour construire la liste des fonctionnalités de Créno, au lieu de « fais-moi le backlog », enchaînez :\n\n1. lister les tâches que réalise un coach dans sa semaine ;\n2. identifier celles que l'application doit prendre en charge au lancement ;\n3. les transformer en user stories (module 1) ;\n4. les prioriser selon la valeur et l'effort.\n\nÀ chaque étape, vous corrigez le tir : les erreurs ne se propagent pas.\n\n## 3. Faire poser des questions avant de répondre\n\nQuand vous n'êtes pas sûr d'avoir tout dit, terminez votre prompt par : « Avant de répondre, pose-moi les questions nécessaires pour bien faire ce travail. » L'IA identifie les informations manquantes (public, contraintes, priorités…). C'est aussi un excellent moyen de découvrir ce que vous n'aviez pas pensé à préciser.\n\n## 4. Itérer et affiner\n\nLe premier résultat est un brouillon. Au lieu de tout reformuler, donnez un retour ciblé, comme à un collaborateur : « Garde la structure, raccourcis le deuxième paragraphe de moitié, remplace le jargon par des mots du quotidien. » Un retour précis (quoi garder, quoi changer, pourquoi) converge vite ; un retour vague (« refais, c'est pas terrible ») tourne en rond. Si le résultat ne progresse plus après trois ou quatre échanges, le problème vient souvent du prompt initial : repartez d'une nouvelle conversation avec un prompt corrigé.\n\n## 5. Faire critiquer et vérifier\n\nCritiquer un texte est souvent plus facile, pour l'IA comme pour nous, que le réussir du premier coup. Exploitez-le en deux temps : générer, puis demander une relecture critique selon des critères explicites (clarté, exactitude, cohérence avec le contexte, risques). Demandez aussi de lister les affirmations factuelles avec, pour chacune, un niveau de certitude et un moyen de la vérifier.\n\n> [!warning] Une IA qui relit sa propre réponse peut confirmer ses propres erreurs. Pour une information importante (juridique, chiffrée, technique), la vérification finale se fait par vous, sur une source officielle."},{"id":"crs_mvp_ia_m02_l03_b_2","type":"texte","markdown":"## 6. Structurer un long prompt avec des balises\n\nQuand un prompt mélange consignes, documents et exemples, l'IA peut confondre ce qui est une instruction et ce qui est une donnée. Des **balises** (des étiquettes qui encadrent chaque partie) lèvent l'ambiguïté. La documentation d'Anthropic recommande cette pratique pour Claude, et elle fonctionne aussi avec les autres assistants.\n\n```text\n<contexte>\nCréno : application de réservation et de paiement pour coachs sportifs\nindépendants. MVP : publication de créneaux, réservation, paiement en ligne,\nrappel automatique la veille.\n</contexte>\n\n<document>\n[Notes d'entretiens anonymisées]\n</document>\n\n<consignes>\n1. Identifie les cinq problèmes les plus cités par les coachs.\n2. Pour chacun, cite une phrase du document qui l'illustre.\n3. N'invente aucun problème absent du document.\n</consignes>\n\n<format>\nTableau : problème | citation | fréquence (souvent / parfois / rarement)\n</format>\n```\n\nLes noms des balises sont libres : choisissez des mots clairs, réutilisez-les d'un prompt à l'autre, et faites-y référence dans les consignes (« en t'appuyant uniquement sur le document »).\n\n## 7. Les consignes persistantes\n\nRépéter à chaque conversation « je travaille sur Créno, application pour coachs… » est fastidieux. La plupart des assistants permettent d'enregistrer des **consignes persistantes** : des instructions, et parfois des documents, pris en compte automatiquement dans toutes les conversations d'un espace de travail ou de votre compte. Selon l'outil, cela prend la forme d'un espace de projet avec ses fichiers de référence, d'instructions personnalisées ou d'une mémoire. Les noms et l'emplacement de ces réglages évoluent : consultez l'aide de votre assistant.\n\nQue mettre dans ces consignes :\n\n- le projet en cinq lignes (problème, cible, proposition de valeur) ;\n- le périmètre du MVP, et ce qui est explicitement hors périmètre ;\n- votre profil (« je ne code pas, explique les termes techniques » ou « je suis développeur, va droit au but ») ;\n- vos préférences de ton et de format ;\n- les documents de référence : PRD, glossaire, charte éditoriale.\n\nTenez-les à jour : une consigne obsolète est pire que pas de consigne.\n\n## 8. Gérer une longue conversation\n\nAu fil d'une longue conversation, les consignes du début se diluent et les versions successives se mélangent. Signes d'alerte : l'IA réintroduit une idée écartée, oublie une contrainte ou mélange deux versions d'un document.\n\nLa parade : **repartir d'un résumé**. Demandez un résumé de passation (décisions prises, état du livrable, points ouverts, contraintes), relisez-le, corrigez-le, puis collez-le dans une nouvelle conversation. Vous repartez avec un contexte propre et court. Faites-le à chaque changement de sujet, ou dès que la conversation devient difficile à suivre."},{"id":"crs_mvp_ia_m02_l03_b_3","type":"prompt","title":"Faire poser les questions avant de répondre","tool":"Tout assistant IA","prompt":"Je veux [OBJECTIF] pour mon projet : [DESCRIPTION EN 2 PHRASES].\n\nAvant de produire quoi que ce soit, pose-moi les questions dont tu as besoin pour faire un travail de qualité : 10 au maximum, classées de la plus importante à la moins importante. Pour chaque question, explique en une ligne pourquoi elle compte.\nAttends mes réponses avant de commencer.","tips":"Répondez à chaque question, même brièvement ; si une question ne vous concerne pas, dites-le. Les questions qui reviennent souvent indiquent ce qu'il faut ajouter à vos consignes persistantes."},{"id":"crs_mvp_ia_m02_l03_b_4","type":"prompt","title":"Relecture critique en deux temps","tool":"Tout assistant IA","prompt":"Relis ta réponse précédente comme un relecteur exigeant.\n\n1. Évalue-la selon ces critères : [CRITÈRE 1], [CRITÈRE 2], [CRITÈRE 3]. Donne une note sur 5 et une justification pour chacun.\n2. Liste les affirmations factuelles (chiffres, noms, fonctionnalités d'outils, règles juridiques) et indique pour chacune : certaine, probable ou à vérifier, avec la source officielle à consulter.\n3. Propose une version corrigée qui règle les trois problèmes les plus importants.\n\nNe te contente pas de valider : cherche activement les faiblesses."},{"id":"crs_mvp_ia_m02_l03_b_5","type":"prompt","title":"Résumé de passation pour repartir d'une conversation propre","tool":"Tout assistant IA","prompt":"Nous allons poursuivre ce travail dans une nouvelle conversation. Rédige un résumé de passation autonome, compréhensible sans l'historique :\n- Objectif du travail\n- Contexte du projet (5 lignes maximum)\n- Décisions prises, et pourquoi\n- Pistes écartées (pour ne pas y revenir)\n- État actuel du livrable (colle la dernière version complète)\n- Contraintes à respecter\n- Prochaines étapes et questions ouvertes\n\nSois factuel et n'ajoute rien qui n'a pas été décidé.","tips":"Relisez et corrigez ce résumé avant de le coller dans la nouvelle conversation : il devient votre nouvelle source de vérité."},{"id":"crs_mvp_ia_m02_l03_b_6","type":"prompt","title":"Prompt long structuré par balises","tool":"Claude","prompt":"<contexte>\n[VOTRE PROJET EN 3 À 5 PHRASES]\n</contexte>\n\n<document>\n[DOCUMENT À ANALYSER, ANONYMISÉ]\n</document>\n\n<consignes>\n1. [PREMIÈRE ÉTAPE]\n2. [DEUXIÈME ÉTAPE]\n3. Appuie-toi uniquement sur le contenu de la balise document. Si une information manque, écris « non précisé ».\n</consignes>\n\n<format>\n[FORMAT DE SORTIE ATTENDU]\n</format>","tips":"Fonctionne aussi dans ChatGPT et dans les autres assistants. Gardez les mêmes noms de balises d'un prompt à l'autre."},{"id":"crs_mvp_ia_m02_l03_b_7","type":"texte","markdown":"## Profil technique : sorties structurées et chaînage\n\nLe few-shot est particulièrement efficace pour l'extraction de données : donnez deux paires entrée / sortie en JSON, puis la nouvelle entrée. Exigez une sortie conforme à un schéma et validez-la dans votre code : ne supposez jamais que le JSON reçu est valide. La décomposition devient du **chaînage** : la sortie d'un prompt alimente le suivant, ce que vous automatiserez au module 6 avec n8n ou dans votre code. Versionnez ces prompts comme du code et testez-les sur un petit jeu d'entrées de référence.","personas":["tech"]},{"id":"crs_mvp_ia_m02_l03_b_8","type":"texte","markdown":"## Par où commencer ?\n\nHuit techniques d'un coup, c'est beaucoup. Commencez par deux : **faire poser des questions** (technique 3) et **donner un retour précis** (technique 4). Elles améliorent déjà la plupart de vos échanges, sans rien à installer ni à apprendre. Ajoutez les balises le jour où vous collez un long document, et les consignes persistantes dès que vous travaillez plusieurs jours sur le même sujet.","personas":["non_tech","reconversion"]},{"id":"crs_mvp_ia_m02_l03_b_9","type":"exercice","title":"Combiner les techniques sur une vraie tâche","instructions":"Choisissez une tâche consistante de votre projet, que vous devez de toute façon réaliser : rédiger la description de votre offre, synthétiser des retours d'utilisateurs potentiels, lister les écrans de votre application…\n\n1. **Consignes persistantes** : rédigez les consignes de votre projet (description, périmètre, profil, préférences) et enregistrez-les dans votre assistant si la fonction existe ; sinon, gardez-les dans un document à coller en début de conversation.\n2. **Questions préalables** : lancez la tâche en demandant à l'IA de vous poser ses questions d'abord, puis répondez-y.\n3. **Structure** : si vous fournissez un document (anonymisé), encadrez-le avec des balises.\n4. **Itération** : faites au moins deux retours ciblés (quoi garder, quoi changer, pourquoi).\n5. **Critique** : utilisez le prompt de relecture critique, puis vérifiez vous-même au moins une affirmation factuelle sur une source officielle.\n6. **Passation** : terminez par un résumé de passation.\n\nLivrable (texte) : vos consignes persistantes, les questions posées par l'IA (et ce qu'elles vous ont appris), vos deux retours d'itération, le résumé de passation, et trois lignes de bilan : quelle technique a le plus changé le résultat ?","deliverable":"texte","estimatedMinutes":40,"review":"formateur","rubric":["Les consignes persistantes décrivent le projet, le périmètre et le profil de l'utilisateur","Au moins quatre techniques de la leçon sont appliquées et identifiables","Les retours d'itération sont précis (quoi garder, quoi changer, pourquoi)","Au moins une affirmation factuelle est vérifiée sur une source externe","Le bilan est personnel et argumenté"]}]$q$::jsonb)
on conflict (id) do nothing;

insert into crm.academy_lessons (id, course_id, module_id, position, title, summary, estimated_minutes, is_preview, blocks)
values ($q$crs_mvp_ia_m02_l04$q$, $q$crs_mvp_ia$q$, $q$crs_mvp_ia_m02$q$, 3, $q$Prompter pour produire du code$q$, $q$De la user story au code relu : spécification, fichiers de contexte, plan, petites étapes, tests et relecture des diffs, selon le type d'outil.$q$, 65, false, $q$[{"id":"crs_mvp_ia_m02_l04_b_1","type":"texte","markdown":"À la fin de cette leçon, vous saurez rédiger des prompts qui produisent du code utile et maîtrisé : à partir d'une spécification, avec un plan validé, par petites étapes testées, en relisant chaque modification avant de l'enregistrer.\n\n## Le piège du « fais-moi l'appli »\n\nLes outils de code assisté par IA peuvent générer en quelques minutes une application qui semble fonctionner. Le risque n'est pas qu'ils échouent, c'est qu'ils réussissent *en apparence*. Une page qui s'affiche peut cacher une faille de sécurité, une règle métier oubliée ou une base de données mal structurée. Plus le prompt est vague, plus l'outil prend de décisions à votre place, sans vous le dire.\n\nLa règle de cette leçon : **vous restez le chef de projet.** L'IA écrit le code ; vous décidez de ce qu'il doit faire et vous vérifiez qu'il le fait.\n\n## Partir d'une spécification\n\nAu module 1, vous avez rédigé un PRD (le document qui décrit le produit à construire) et des user stories. C'est le meilleur point de départ d'un prompt de code. Une **user story** décrit un besoin du point de vue de l'utilisateur ; les **critères d'acceptation** listent les conditions vérifiables pour considérer la fonctionnalité terminée.\n\n```text\nUser story : en tant que client, je veux annuler une réservation depuis\nmon espace, afin de libérer le créneau si je ne peux pas venir.\n\nCritères d'acceptation :\n- Le bouton « Annuler » n'apparaît que sur mes réservations à venir.\n- L'annulation est possible jusqu'à 24 h avant la séance ; au-delà, le\n  bouton est désactivé et un message explique pourquoi.\n- Après annulation, le créneau redevient disponible pour les autres clients.\n- Le coach voit la réservation au statut « annulée ».\n- Un client ne peut jamais annuler la réservation d'un autre client.\n```\n\nChaque critère est testable, automatiquement ou à la main. Donnez ce bloc tel quel à l'outil : il sait *quoi* construire et *comment* vérifier que c'est fait. Le dernier critère est une règle de sécurité : vous verrez au module 4 comment la garantir dans la base de données avec la sécurité par lignes (RLS) de Supabase."},{"id":"crs_mvp_ia_m02_l04_b_2","type":"video","title":"De la user story au code relu","url":"","durationMinutes":7,"script":"- Ouverture : le même besoin Créno (annuler une réservation) demandé de deux façons : « ajoute l'annulation » contre user story + critères d'acceptation.\n- Présentation du fichier de contexte du projet (CLAUDE.md / AGENTS.md) : ce qu'il contient, pourquoi il est court.\n- Demande d'un plan à un agent de code ; correction d'un point du plan à l'écran (la règle des 24 h avait été oubliée).\n- Lancement de la première étape : tests générés à partir des critères, exécution des tests.\n- Lecture commentée du diff : fichiers modifiés, repérage d'une modification non demandée, demande d'annulation.\n- Demande d'explication du diff en langage courant (réflexe utile aux profils non techniques).\n- Commit avec un message clair ; rappel : jamais de commit sans comprendre ce qu'il contient.\n- Conclusion : les trois postures (générer, coécrire, déléguer) et renvoi au module 6."},{"id":"crs_mvp_ia_m02_l04_b_3","type":"texte","markdown":"## Les fichiers de contexte du projet\n\nUn outil de code ne se souvient pas de la séance de la veille. Pour lui transmettre durablement les règles du projet, on place des **fichiers de contexte** dans le dépôt de code (le dossier du projet, versionné avec Git, que vous créerez au module 6) :\n\n- `CLAUDE.md` : lu automatiquement par Claude Code au démarrage d'une session ;\n- `AGENTS.md` : une convention ouverte, lue notamment par Codex et par d'autres outils ;\n- **les règles de projet de Cursor** : des consignes enregistrées dans la configuration du projet et appliquées par l'assistant de l'éditeur (voir la documentation de Cursor pour leur format actuel).\n\nLe principe est le même partout : un fichier texte, en Markdown, qui dit ce qu'un nouveau développeur devrait savoir avant de toucher au code. Exemple pour Créno :\n\n```markdown\n## Projet\nCréno : réservation et paiement de séances pour coachs sportifs indépendants.\nRôles : coach, client. Entités : profiles, slots, bookings, payments.\n\n## Stack\nNext.js, React, TypeScript, Supabase (Postgres, Auth, RLS), Stripe, Vercel.\n\n## Règles\n- Toute table a la sécurité par lignes (RLS) activée, avec des politiques explicites.\n- Les clés secrètes (Stripe, clé de service Supabase) restent côté serveur.\n- Toute nouvelle fonctionnalité est livrée avec ses tests.\n- Aucune nouvelle dépendance sans validation.\n\n## Commandes\n- Lancer en local : pnpm dev\n- Vérifier : pnpm typecheck && pnpm lint && pnpm test\n```\n\nRédigez-le court et factuel, et mettez-le à jour à chaque décision importante. Vous approfondirez l'art de documenter pour l'IA au module 4.\n\n## La boucle de travail\n\n1. **Demander un plan avant le code.** « Ne modifie rien. Propose un plan : fichiers concernés, étapes, tests, risques, questions. » Vous validez ou corrigez le plan avant qu'une seule ligne soit écrite : c'est le moment le moins coûteux pour rattraper un malentendu. Certains outils proposent un mode dédié à la planification ; la consigne « ne modifie rien » fonctionne partout.\n2. **Avancer par petites étapes.** Une étape est une modification que vous pouvez comprendre et tester en quelques minutes : une table, un écran, une règle. Une grosse modification générée d'un coup est impossible à relire.\n3. **Exiger des tests.** Demandez des tests automatiques (de petits programmes qui vérifient le comportement attendu) qui traduisent les critères d'acceptation, et leur exécution. Un test qui passe ne prouve pas tout, mais un critère sans test finit par casser sans que personne ne le remarque.\n4. **Relire le diff.** Un **diff** affiche les différences entre l'ancienne et la nouvelle version du code. Quels fichiers ont été touchés ? Y a-t-il des changements non demandés ? Une clé écrite en dur ? Un test supprimé pour « faire passer » la vérification ?\n5. **Ne jamais committer sans comprendre.** Un **commit** enregistre une version du code dans l'historique Git. Avant de committer, vous devez pouvoir dire en une phrase ce que fait la modification. Sinon, demandez : « Explique-moi ce diff fichier par fichier, comme à un débutant. »\n\n## Trois approches, trois façons de prompter\n\n| | Générateur d'application (Bolt.new) | Éditeur assisté (Cursor) | Agent de code (Claude Code, Codex) |\n| --- | --- | --- | --- |\n| Principe | Vous décrivez l'application dans le navigateur ; l'outil génère et exécute le projet | Un éditeur de code avec un assistant qui propose, modifie et explique | Un agent qui lit le dépôt, modifie les fichiers et lance des commandes, depuis un terminal ou une interface dédiée |\n| Point fort | Aller très vite de l'idée au prototype visible | Travailler au plus près du code en gardant la main | Mener une tâche de bout en bout, en plusieurs étapes |\n| Façon de prompter | Décrire produit, écrans et données ; corriger par retours visuels | Prompts ciblés sur un fichier ou une sélection de code | Prompts de mission : objectif, spécification, contraintes, critères de fin |\n| Vigilance | Structure du code et sécurité à vérifier | Garder la vision d'ensemble | Permissions accordées, relecture des diffs et des commandes |\n\nCes frontières bougent : les éditeurs intègrent des agents, les agents existent aussi en extension d'éditeur ou dans le navigateur. Retenez trois postures : **générer** un prototype, **coécrire** du code, **déléguer** une mission. Vous les mettrez en pratique au module 6."},{"id":"crs_mvp_ia_m02_l04_b_4","type":"prompt","title":"Demander un plan avant le code","tool":"Claude Code","prompt":"Lis le fichier CLAUDE.md et la structure du projet.\n\nVoici la user story à implémenter :\n[COLLEZ LA USER STORY ET SES CRITÈRES D'ACCEPTATION]\n\nNe modifie aucun fichier pour l'instant. Propose un plan :\n1. les fichiers à créer ou à modifier, avec le rôle de chacun ;\n2. les étapes, dans l'ordre, chacune testable séparément ;\n3. les tests à écrire pour chaque critère d'acceptation ;\n4. les risques (sécurité, données, cas limites) ;\n5. tes questions si quelque chose est ambigu.\n\nAttends ma validation avant de coder.","tips":"Le même prompt fonctionne avec Codex (remplacez CLAUDE.md par AGENTS.md) et avec l'agent de Cursor. Validez ou corrigez le plan point par point avant de lancer l'étape 1."},{"id":"crs_mvp_ia_m02_l04_b_5","type":"prompt","title":"Implémenter une étape, avec ses tests","tool":"Cursor","prompt":"Implémente uniquement l'étape [NUMÉRO] du plan validé : [RAPPEL DE L'ÉTAPE].\n\nContraintes :\n- Ne modifie que les fichiers nécessaires à cette étape.\n- Écris les tests correspondant aux critères [LISTE DES CRITÈRES] et exécute-les.\n- N'ajoute aucune dépendance sans me le demander.\n- Aucune clé secrète dans le code : utilise les variables d'environnement.\n\nÀ la fin, résume : fichiers modifiés, rôle de chaque modification, résultat des tests, points que je dois vérifier moi-même dans l'application.","tips":"Relisez le diff avant d'accepter. Si l'étape a touché des fichiers inattendus, demandez pourquoi avant de valider."},{"id":"crs_mvp_ia_m02_l04_b_6","type":"prompt","title":"Premier prototype dans Bolt.new","tool":"Bolt.new","prompt":"Crée une application web de réservation de séances pour coachs sportifs indépendants.\n\nDeux rôles :\n- Coach : se connecte, publie des créneaux (date, heure, durée, lieu, prix), voit la liste de ses réservations.\n- Client : consulte les créneaux disponibles d'un coach, réserve un créneau, voit et annule ses réservations (jusqu'à 24 h avant la séance).\n\nÉcrans : accueil, connexion / inscription, tableau de bord du coach, page publique d'un coach, espace client.\nDonnées : profils (coach ou client), créneaux, réservations.\n\nPour cette première version : pas de paiement réel, uniquement des données de démonstration fictives, un design sobre et lisible sur mobile.\nAvant de générer, résume ce que tu vas construire et pose-moi tes questions.","tips":"Remplacez Créno par votre projet. Avancez ensuite écran par écran, par petits prompts de correction. Le paiement et les rappels viendront plus tard (module 6).","personas":["non_tech","reconversion"]},{"id":"crs_mvp_ia_m02_l04_b_7","type":"texte","markdown":"## Vous ne lisez pas le code ? Vous pouvez quand même le piloter\n\nVous n'avez pas à comprendre chaque ligne, mais vous devez contrôler le comportement. Trois réflexes :\n\n- demandez systématiquement à l'outil d'expliquer ce qu'il a changé, en langage courant ;\n- testez vous-même chaque critère d'acceptation dans l'application, comme un utilisateur, y compris les cas interdits (essayer d'annuler la réservation d'un autre compte) ;\n- gardez une trace des versions qui fonctionnent, pour pouvoir revenir en arrière.\n\nPour tout ce qui touche à la sécurité et aux paiements, faites relire par une personne technique avant d'ouvrir l'application à de vrais utilisateurs.","personas":["non_tech"]},{"id":"crs_mvp_ia_m02_l04_b_8","type":"texte","markdown":"## Profil technique : un développeur junior très rapide\n\nTraitez les agents de code comme un collègue productif, mais sans mémoire ni responsabilité. Une branche par fonctionnalité, une pull request relue (même par vous seul), typage, linter et tests en intégration continue. Réglez les permissions de l'agent au plus juste : lecture et exécution des tests autorisées, confirmation exigée pour les commandes qui modifient l'environnement (installation, migration, suppression, push). Méfiez-vous des API inventées ou obsolètes sur les bibliothèques qui évoluent vite : exigez que l'agent s'appuie sur la documentation officielle ou sur le code existant du dépôt. Et gardez les fichiers de contexte courts : un fichier trop long dilue les règles importantes.","personas":["tech"]},{"id":"crs_mvp_ia_m02_l04_b_9","type":"texte","markdown":"## Le vocabulaire du code, en une minute\n\n| Terme | En clair |\n| --- | --- |\n| Code source | Le texte, écrit dans un langage de programmation, qui fait fonctionner l'application |\n| Dépôt | Le dossier du projet, avec tout l'historique de ses versions |\n| Git / GitHub | Git enregistre les versions ; GitHub héberge le dépôt en ligne |\n| Commit | Une version enregistrée, avec un message qui explique le changement |\n| Diff | L'affichage de ce qui a changé entre deux versions |\n| Test automatique | Un petit programme qui vérifie qu'une fonctionnalité se comporte comme prévu |\n| Terminal | La fenêtre où l'on tape des commandes sous forme de texte |\n\nPas d'inquiétude : vous manipulerez tout cela pas à pas au module 6. Pour l'instant, retenez l'idée : on avance par petites versions enregistrées et vérifiées, que l'on peut toujours annuler.","personas":["reconversion"]},{"id":"crs_mvp_ia_m02_l04_b_10","type":"checklist","title":"Avant d'accepter du code généré par l'IA","items":[{"id":"crs_mvp_ia_m02_l04_b_10_i_1","label":"Je peux expliquer en une phrase ce que fait la modification."},{"id":"crs_mvp_ia_m02_l04_b_10_i_2","label":"Le diff ne touche que les fichiers attendus."},{"id":"crs_mvp_ia_m02_l04_b_10_i_3","label":"Aucune clé secrète ni aucun mot de passe n'apparaît dans le code."},{"id":"crs_mvp_ia_m02_l04_b_10_i_4","label":"Les tests correspondant aux critères d'acceptation existent et passent."},{"id":"crs_mvp_ia_m02_l04_b_10_i_5","label":"Aucun test n'a été supprimé ou affaibli pour « faire passer » la vérification."},{"id":"crs_mvp_ia_m02_l04_b_10_i_6","label":"Aucune dépendance n'a été ajoutée sans mon accord."},{"id":"crs_mvp_ia_m02_l04_b_10_i_7","label":"J'ai testé le comportement dans l'application, y compris un cas interdit."}]},{"id":"crs_mvp_ia_m02_l04_b_11","type":"exercice","title":"Préparer le prompt de votre première fonctionnalité","instructions":"Objectif : préparer tout ce qu'il faut pour confier votre première fonctionnalité à un outil de code. Vous ne l'exécutez pas encore : ce sera l'objet du module 6.\n\n1. Choisissez **une user story** prioritaire de votre backlog (module 1). Complétez-la avec 4 à 6 **critères d'acceptation** testables, dont au moins un critère de sécurité (qui a le droit de faire quoi).\n2. Rédigez un **fichier de contexte** (`CLAUDE.md` ou `AGENTS.md`) de 15 à 30 lignes : projet, stack envisagée (vous la choisirez au module 3 : indiquez votre hypothèse actuelle), règles, commandes si vous les connaissez.\n3. Rédigez le **prompt de plan** adapté à l'outil que vous pensez utiliser (Bolt.new, Cursor, Claude Code ou Codex).\n4. Rédigez le **prompt d'implémentation** de la première étape, avec l'exigence de tests.\n5. Listez **trois points** que vous vérifierez dans le diff ou dans l'application avant de valider.\n\nLa user story « annuler une réservation » de Créno montre le niveau de détail attendu.\n\nLivrable (texte) : les cinq éléments ci-dessus.","deliverable":"texte","estimatedMinutes":40,"review":"formateur","rubric":["Les critères d'acceptation sont testables et incluent une règle de sécurité","Le fichier de contexte est court, factuel et spécifique au projet","Le prompt de plan interdit de coder avant validation et demande tests et risques","Le prompt d'implémentation limite le périmètre à une seule étape","Les points de vérification sont concrets"]}]$q$::jsonb)
on conflict (id) do nothing;

insert into crm.academy_lessons (id, course_id, module_id, position, title, summary, estimated_minutes, is_preview, blocks)
values ($q$crs_mvp_ia_m02_l05$q$, $q$crs_mvp_ia$q$, $q$crs_mvp_ia_m02$q$, 4, $q$Les agents IA au quotidien$q$, $q$Comprendre ce qu'est un agent, lui confier une mission avec un brief précis, et appliquer les règles de sécurité qui évitent les mauvaises surprises.$q$, 60, false, $q$[{"id":"crs_mvp_ia_m02_l05_b_1","type":"texte","markdown":"À la fin de cette leçon, vous saurez confier une tâche en plusieurs étapes à un agent IA, avec un brief de mission clair et des règles de sécurité qui gardent la décision entre vos mains.\n\n## Assistant ou agent : quelle différence ?\n\nUn **assistant** répond à un message : vous demandez, il rédige, vous copiez. Un **agent** reçoit un objectif et agit pour l'atteindre. Il dispose d'**outils** (lire et écrire des fichiers, chercher sur le web, naviguer sur un site, exécuter des commandes, utiliser une application connectée) et fonctionne en **boucle** :\n\n1. il analyse l'objectif et planifie ;\n2. il choisit une action et utilise un outil ;\n3. il observe le résultat (une page lue, une erreur, un fichier créé) ;\n4. il décide de l'étape suivante, jusqu'à estimer la tâche terminée ou avoir besoin de vous.\n\nCette autonomie est précieuse : un agent peut enchaîner de nombreuses étapes pendant que vous faites autre chose. Elle a un revers : ses actions sont réelles. Un fichier supprimé est supprimé, un formulaire envoyé est envoyé.\n\n## Les agents que vous rencontrerez\n\n- **Claude Cowork** : Claude en mode agent pour le travail de bureau. Vous lui donnez accès à un périmètre (par exemple un dossier de votre ordinateur) et une mission ; il planifie, manipule les fichiers et produit des documents (synthèses, tableaux, rapports).\n- **ChatGPT en mode agent** : ChatGPT enchaîne recherches, navigation sur des sites web et actions pour accomplir une tâche, en vous tenant informé de ce qu'il fait.\n- **Claude Code et Codex** : des agents spécialisés dans le code, qui lisent un dépôt, modifient des fichiers et lancent des commandes (leçon précédente et module 6).\n\nCapacités, conditions d'accès et réglages de ces outils évoluent souvent : vérifiez la documentation de l'éditeur avant de vous appuyer sur une fonction précise.\n\n## Que déléguer ? Des exemples pour votre projet\n\n| Mission | Exemple Créno | Outil adapté | Ce que vous vérifiez |\n| --- | --- | --- | --- |\n| Recherche documentaire | Recenser les obligations d'information pour la vente de prestations en ligne, sources officielles à l'appui | ChatGPT en mode agent, ou un assistant avec recherche web | Que chaque source existe et dit bien ce qui est résumé |\n| Synthèse de fichiers | Synthétiser douze comptes rendus d'entretiens de coachs, anonymisés, rangés dans un dossier | Claude Cowork | Que les citations sont exactes et qu'aucune idée n'est inventée |\n| Organisation de documents | Renommer et classer les documents du projet (PRD, maquettes, notes) selon une convention | Claude Cowork | Le résultat, sur une copie du dossier |\n| Préparation d'un comparatif | Comparer cinq outils de prise de rendez-vous existants : cible, fonctionnalités, modèle économique affiché | ChatGPT en mode agent ou Claude Cowork | Les informations, sur les pages officielles |\n| Tâche de code | Ajouter un test manquant, corriger un bug reproductible | Claude Code, Codex | Le diff, les tests, le comportement réel |\n\n## Rédiger un brief de mission\n\nUn agent prend des décisions seul : il a besoin d'un brief plus complet qu'un assistant. Un bon brief contient :\n\n- **l'objectif** et le livrable final (format, emplacement) ;\n- **le périmètre** : dossiers, sites ou outils autorisés, et ceux qui sont interdits ;\n- **les étapes attendues**, ou au moins les points de passage ;\n- **les points d'arrêt** : quand il doit s'arrêter et vous demander (avant tout envoi, achat, suppression ou publication) ;\n- **les critères de fin** : à quoi il reconnaît que le travail est terminé ;\n- **le compte rendu** : ce qu'il a fait, les sources utilisées, ce qui reste incertain."},{"id":"crs_mvp_ia_m02_l05_b_2","type":"texte","markdown":"## Les règles de sécurité\n\n1. **Permissions minimales.** Donnez accès au strict nécessaire : un dossier précis plutôt que tout votre disque, une copie de travail plutôt que les originaux, un compte de test plutôt que le compte réel.\n2. **Aucun secret.** Ne mettez jamais un mot de passe, une clé d'API ou des coordonnées bancaires dans un brief. Si une connexion à un service est nécessaire, passez par les mécanismes de connexion prévus par l'outil, avec les droits les plus limités possible.\n3. **Validation humaine avant toute action irréversible.** Envoi d'un e-mail, paiement, suppression, publication, modification de données réelles : l'agent prépare, vous validez. Écrivez-le dans le brief, même si l'outil prévoit déjà des confirmations.\n4. **Relecture systématique.** Le livrable d'un agent se relit comme celui d'un stagiaire : sources, chiffres, cohérence. Un agent peut se tromper à une étape, puis construire toute la suite sur cette erreur.\n5. **Méfiance envers les contenus lus.** Une page web ou un document peut contenir des instructions cachées destinées à détourner l'agent : on parle d'**injection de prompt**. Limitez les sources consultées à des sites et documents de confiance, et surveillez les actions inattendues.\n\n## Quand ne pas déléguer\n\n- Quand la tâche engage votre responsabilité ou votre image sans relecture possible (message à un client, publication).\n- Quand elle touche des données personnelles réelles ou des données sensibles.\n- Quand vous ne savez pas vérifier le résultat : déléguer ce qu'on ne sait pas contrôler, c'est prendre un risque à l'aveugle.\n- Quand la tâche est plus rapide à faire qu'à expliquer.\n- Quand l'enjeu est d'apprendre : pendant cette formation, certaines décisions (votre PRD, votre stack) doivent rester les vôtres. L'agent prépare, vous décidez."},{"id":"crs_mvp_ia_m02_l05_b_3","type":"prompt","title":"Brief de mission : synthèse d'un dossier de fichiers","tool":"Claude Cowork","prompt":"Mission : synthétiser les comptes rendus d'entretiens du dossier [NOM DU DOSSIER] (fichiers anonymisés).\n\nPérimètre : travaille uniquement dans ce dossier. Ne supprime, ne renomme et ne déplace aucun fichier existant. Crée ton livrable dans un sous-dossier « synthese ».\n\nÉtapes attendues :\n1. Liste les fichiers que tu vas lire et signale ceux que tu ne peux pas ouvrir.\n2. Pour chaque entretien, extrais les problèmes cités, avec une citation exacte.\n3. Regroupe les problèmes par thème et compte le nombre d'entretiens qui mentionnent chaque thème.\n\nLivrable : un document avec un tableau (thème | nombre d'entretiens | citations représentatives) et une conclusion de 10 lignes maximum.\n\nRègles : n'invente aucune citation ; si une information est ambiguë, signale-la au lieu de trancher. Arrête-toi et demande-moi avant toute action non prévue dans ce brief.\n\nCompte rendu final : fichiers lus, méthode suivie, limites de la synthèse.","tips":"Pour une première mission, travaillez sur une copie du dossier. Vérifiez ensuite trois citations au hasard dans les fichiers d'origine."},{"id":"crs_mvp_ia_m02_l05_b_4","type":"prompt","title":"Brief de mission : comparatif de solutions existantes","tool":"ChatGPT","prompt":"Mission : préparer un comparatif de [NOMBRE] solutions existantes qui répondent au même besoin que mon projet : [DESCRIPTION DU BESOIN EN 2 PHRASES].\n\nMéthode :\n- Utilise uniquement les sites officiels des solutions et leur documentation publique.\n- Pour chaque solution : cible, fonctionnalités principales, modèle économique affiché (abonnement, commission, gratuit…), points faibles visibles.\n- Indique pour chaque information l'adresse de la page consultée et la date de consultation.\n\nInterdits : ne crée aucun compte, ne remplis aucun formulaire, n'accepte aucune condition d'utilisation, ne saisis aucune donnée personnelle.\n\nLivrable : un tableau comparatif, puis cinq pistes de différenciation pour mon projet, en distinguant les faits observés de tes hypothèses.","tips":"À utiliser avec ChatGPT en mode agent ou avec tout assistant disposant de la recherche web. Contrôlez vous-même au moins deux lignes du tableau sur les sites cités."},{"id":"crs_mvp_ia_m02_l05_b_5","type":"texte","markdown":"## Les agents, un levier pour tout ce qui n'est pas technique\n\nPour un profil non technique, les agents de bureau offrent souvent le gain de temps le plus immédiat : classer les documents du projet, transformer des notes en compte rendu structuré, préparer un tableau de veille concurrentielle, consolider les réponses d'un questionnaire exporté en tableur. Commencez par des missions dont vous savez vérifier le résultat en quelques minutes, sur des copies de fichiers. Gardez pour vous les échanges avec vos futurs clients et partenaires : l'agent prépare les brouillons, vous envoyez.","personas":["non_tech"]},{"id":"crs_mvp_ia_m02_l05_b_6","type":"texte","markdown":"## Profil technique : connecteurs, bac à sable et traçabilité\n\nLes agents gagnent en capacité quand on les connecte à des outils. Le **MCP** (Model Context Protocol), un protocole ouvert, permet de brancher un agent sur des services : base de données, gestion de tickets, documentation. Chaque connecteur élargit la surface d'attaque : préférez des accès en lecture seule, des environnements de développement plutôt que de production, et des jetons d'accès à portée limitée et révocables. Pour les agents de code, isolez l'exécution (conteneur, environnement distant de l'outil, branche dédiée) et gardez la main sur les commandes destructrices. Un agent dont on ne peut pas retracer les actions n'a rien à faire sur des données réelles.","personas":["tech"]},{"id":"crs_mvp_ia_m02_l05_b_7","type":"texte","markdown":"## Commencer sans risque\n\nSi vous découvrez les agents, choisissez une première mission sans enjeu : sur une copie d'un dossier de documents non sensibles (vos notes de formation, par exemple), demandez un classement et un sommaire. Observez comment l'agent planifie, ce qu'il vous demande, où il se trompe. Une mission observée vous en apprendra plus que dix descriptions. Et rappelez-vous que ces outils permettent en général d'interrompre un agent en cours de route.","personas":["reconversion"]},{"id":"crs_mvp_ia_m02_l05_b_8","type":"checklist","title":"Avant de lancer un agent","items":[{"id":"crs_mvp_ia_m02_l05_b_8_i_1","label":"L'objectif et le livrable final sont écrits."},{"id":"crs_mvp_ia_m02_l05_b_8_i_2","label":"Le périmètre d'accès est limité au strict nécessaire (dossier, sites, outils)."},{"id":"crs_mvp_ia_m02_l05_b_8_i_3","label":"L'agent travaille sur des copies ou des données de test."},{"id":"crs_mvp_ia_m02_l05_b_8_i_4","label":"Aucun mot de passe, aucune clé ni donnée bancaire ne figure dans le brief."},{"id":"crs_mvp_ia_m02_l05_b_8_i_5","label":"Les actions irréversibles exigent ma validation, et c'est écrit dans le brief."},{"id":"crs_mvp_ia_m02_l05_b_8_i_6","label":"Je sais comment je vais vérifier le résultat."},{"id":"crs_mvp_ia_m02_l05_b_8_i_7","label":"Je sais comment interrompre l'agent en cours de route."}]},{"id":"crs_mvp_ia_m02_l05_b_9","type":"exercice","title":"Votre première mission déléguée","instructions":"1. Choisissez une mission utile à votre projet : recherche documentaire, synthèse de fichiers, organisation de documents ou préparation d'un comparatif.\n2. Rédigez le brief complet : objectif, périmètre, étapes, points d'arrêt, critères de fin, compte rendu attendu.\n3. Préparez l'environnement : copie des fichiers, données anonymisées, aucun secret.\n4. Lancez la mission avec l'agent de votre choix (Claude Cowork, ChatGPT en mode agent ou un autre outil dont vous disposez). Si vous n'avez accès à aucun agent, réalisez la mission étape par étape avec un assistant classique, en suivant votre brief.\n5. Vérifiez le livrable : relevez les erreurs, les oublis et les actions inattendues.\n\nLivrable (texte) : votre brief, un résumé du résultat, la liste de ce que vous avez vérifié et corrigé, et vos règles personnelles de délégation (3 à 5 lignes).","deliverable":"texte","estimatedMinutes":45,"review":"formateur","rubric":["Le brief contient objectif, périmètre, points d'arrêt et critères de fin","Les règles de sécurité sont appliquées (copies, aucun secret, validation humaine)","La vérification du livrable est concrète et documentée","Les règles personnelles de délégation sont réalistes et adaptées au projet"]}]$q$::jsonb)
on conflict (id) do nothing;

insert into crm.academy_lessons (id, course_id, module_id, position, title, summary, estimated_minutes, is_preview, blocks)
values ($q$crs_mvp_ia_m02_l06$q$, $q$crs_mvp_ia$q$, $q$crs_mvp_ia_m02$q$, 5, $q$Construire sa bibliothèque de prompts$q$, $q$Organiser vos meilleurs prompts dans une base Notion, les transformer en gabarits à variables et les améliorer version après version.$q$, 55, false, $q$[{"id":"crs_mvp_ia_m02_l06_b_1","type":"texte","markdown":"À la fin de cette leçon, vous disposerez d'une bibliothèque de prompts organisée dans Notion, avec des gabarits réutilisables et une méthode pour les améliorer tout au long du projet.\n\n## Pourquoi une bibliothèque ?\n\nUn bon prompt demande du travail : contexte, contraintes, format, itérations. Le perdre au fond d'un historique de conversation, c'est refaire ce travail la semaine suivante, en moins bien. Une bibliothèque de prompts vous permet de :\n\n- **réutiliser** ce qui fonctionne, en quelques secondes ;\n- **améliorer** vos prompts au lieu de repartir de zéro ;\n- **partager** une méthode commune avec vos associés ou un prestataire ;\n- **garder la cohérence** du ton et des règles de votre projet.\n\n## Une base Notion en quinze minutes\n\nNotion est un outil de documentation qui permet de créer des **bases de données** : des tableaux dont chaque ligne est une page, avec des **propriétés** (des colonnes typées : texte, choix dans une liste, date, nombre…). Vous l'avez utilisé au module 1 pour votre backlog. Créez une base « Bibliothèque de prompts » avec ces propriétés :\n\n| Propriété | Type de propriété | Rôle | Exemples de valeurs |\n| --- | --- | --- | --- |\n| Nom | Titre | Identifier le prompt d'un coup d'œil | « Page d'accueil — cible coachs » |\n| Usage | Choix unique | Classer par besoin | Rédaction, Analyse, Produit, Code, Agent |\n| Outil | Choix multiples | Savoir où il a été testé | Claude, ChatGPT, Claude Code, Cursor, Bolt.new |\n| Version | Texte | Suivre les évolutions | v1, v2, v3 |\n| Qualité | Choix unique | Niveau de confiance | À tester, Correct, Fiable |\n| Variables | Texte | Savoir quoi remplir | [CIBLE], [TON], [LONGUEUR] |\n| Mise à jour | Date | Repérer les prompts anciens | Date du dernier test |\n\nDans le corps de chaque page, gardez toujours la même structure : le prompt complet (dans un bloc de code, pour le copier facilement), un exemple de résultat obtenu, les remarques d'usage (« meilleur avec un exemple de ton »), et l'historique des versions.\n\n> [!tip] Créez des vues filtrées : « Code » pour vos sessions de développement, « Fiables » pour les prompts éprouvés, « À tester » pour les brouillons. Une bibliothèque où l'on ne retrouve rien en dix secondes n'est pas utilisée.\n\n## Des gabarits avec variables\n\nUn **gabarit** est un prompt dont les parties qui changent sont remplacées par des **variables** : des emplacements repérables, à remplir avant chaque utilisation. Convention simple : des majuscules entre crochets.\n\n```text\nRôle : tu es rédacteur web pour [CIBLE].\nContexte : [DESCRIPTION DU PROJET EN 3 PHRASES].\nTâche : rédige [TYPE DE CONTENU] sur [SUJET].\nContraintes : [LONGUEUR], [TON], vouvoiement, aucun superlatif.\nFormat : [STRUCTURE ATTENDUE].\n```\n\nTrois règles :\n\n- **Figez ce qui fait la qualité** (contraintes de ton, interdits, critères) et ne mettez en variable que ce qui change réellement.\n- **Nommez les variables clairement** : [CIBLE] plutôt que [X].\n- **Documentez un exemple rempli** dans la fiche, pour montrer le niveau de détail attendu.\n\nPour Créno, le même gabarit « message aux utilisateurs » sert pour le rappel de la veille, la confirmation de réservation et l'annonce d'une nouvelle fonctionnalité : seules les variables changent."},{"id":"crs_mvp_ia_m02_l06_b_2","type":"texte","markdown":"## Versionner et améliorer\n\nUn prompt n'est jamais fini. Quand un résultat vous déçoit, demandez-vous : quelle information manquait ? Quelle contrainte a été ignorée ? Corrigez le prompt, testez la nouvelle version sur le même cas, et si elle est meilleure :\n\n1. incrémentez la version (v1 devient v2) ;\n2. notez en une ligne ce qui a changé et pourquoi (« v2 : ajout d'un exemple de ton, les textes étaient trop commerciaux ») ;\n3. conservez l'ancienne version dans l'historique de la page, pour comparer ou revenir en arrière ;\n4. mettez à jour la qualité et la date.\n\nToutes les deux semaines, prenez dix minutes pour faire le ménage : archivez les prompts jamais utilisés, fusionnez les doublons, passez en « Fiable » ceux qui ont fait leurs preuves. Quand vos outils évoluent, retestez vos prompts les plus importants : un prompt qui fonctionnait peut se comporter différemment après une mise à jour du modèle.\n\n## Dix usages pour démarrer\n\nVoici les usages que la plupart des projets de cette formation rencontrent, et la leçon où vous les avez travaillés :\n\n1. consignes persistantes du projet (leçon 3) ;\n2. texte destiné aux utilisateurs (leçon 2) ;\n3. synthèse d'entretiens ou de retours utilisateurs (leçon 3) ;\n4. transformation d'une idée en user stories avec critères d'acceptation (leçons 3 et 4) ;\n5. relecture critique (leçon 3) ;\n6. résumé de passation (leçon 3) ;\n7. plan avant le code (leçon 4) ;\n8. implémentation d'une étape avec tests (leçon 4) ;\n9. explication d'un diff ou d'un message d'erreur (leçon 4) ;\n10. brief de mission pour un agent (leçon 5)."},{"id":"crs_mvp_ia_m02_l06_b_3","type":"prompt","title":"Transformer un prompt réussi en gabarit","tool":"Tout assistant IA","prompt":"Voici un prompt qui m'a donné un bon résultat :\n---\n[COLLEZ LE PROMPT]\n---\nTransforme-le en gabarit réutilisable :\n1. Repère les éléments propres à ce cas (sujet, cible, longueur, exemples…) et remplace-les par des variables en majuscules entre crochets, avec des noms explicites.\n2. Conserve tels quels les éléments qui font la qualité du résultat (contraintes, critères, format).\n3. Sous le gabarit, liste chaque variable avec une ligne d'explication et un exemple de valeur.\n4. Propose un nom court pour ce gabarit et un usage parmi : Rédaction, Analyse, Produit, Code, Agent."},{"id":"crs_mvp_ia_m02_l06_b_4","type":"texte","markdown":"## Profil technique : des prompts versionnés avec le code\n\nLes prompts qui servent au développement (plan, implémentation, revue) et ceux qui seront intégrés à votre produit (module 6) ont leur place dans le dépôt Git : un dossier dédié, un fichier Markdown par prompt. Vous profitez de l'historique, des revues et des branches. Pour les prompts du produit, ajoutez un petit jeu d'entrées de référence et les sorties attendues : c'est votre test de non-régression quand vous modifiez le prompt ou changez de modèle. Notion reste utile pour les prompts non techniques partagés avec l'équipe.","personas":["tech"]},{"id":"crs_mvp_ia_m02_l06_b_5","type":"texte","markdown":"## Pas à pas dans Notion\n\n1. Créez une nouvelle page, puis ajoutez-y une base de données en affichage tableau.\n2. Renommez la colonne principale « Nom ».\n3. Ajoutez les propriétés une par une, en choisissant le type indiqué dans le tableau ci-dessus.\n4. Créez une première fiche avec le gabarit en sept composantes de la leçon 2.\n5. Dans le corps de la fiche, collez le prompt dans un bloc de code.\n\nSi une étape vous bloque, l'aide officielle de [Notion](https://www.notion.so) décrit la création de bases de données. Au tout début, une simple page avec des titres peut suffire : l'essentiel est de conserver vos prompts et de les améliorer.","personas":["non_tech","reconversion"]},{"id":"crs_mvp_ia_m02_l06_b_6","type":"checklist","title":"Une fiche de prompt complète","items":[{"id":"crs_mvp_ia_m02_l06_b_6_i_1","label":"Un nom explicite et un usage renseigné."},{"id":"crs_mvp_ia_m02_l06_b_6_i_2","label":"Le prompt complet, prêt à copier."},{"id":"crs_mvp_ia_m02_l06_b_6_i_3","label":"Les variables listées, avec un exemple de valeur."},{"id":"crs_mvp_ia_m02_l06_b_6_i_4","label":"Le ou les outils sur lesquels il a été testé."},{"id":"crs_mvp_ia_m02_l06_b_6_i_5","label":"Un exemple de résultat obtenu."},{"id":"crs_mvp_ia_m02_l06_b_6_i_6","label":"Une version et une note sur le dernier changement."},{"id":"crs_mvp_ia_m02_l06_b_6_i_7","label":"Un niveau de qualité à jour."}]},{"id":"crs_mvp_ia_m02_l06_b_7","type":"exercice","title":"Votre bibliothèque de dix prompts","instructions":"1. Créez votre base « Bibliothèque de prompts » dans Notion, avec au minimum les propriétés Usage, Outil, Version et Qualité.\n2. Ajoutez **dix prompts pour votre projet**, en vous appuyant sur la liste des dix usages et sur les prompts produits aux leçons 2 à 5. Au moins cinq doivent être des gabarits à variables.\n3. Testez-en au moins trois et renseignez leur qualité (À tester, Correct, Fiable) avec un exemple de résultat.\n4. Améliorez-en au moins un et documentez sa v2 : ce qui a changé, et pourquoi.\n\nAvant de partager, vérifiez qu'aucune fiche ne contient de donnée personnelle réelle ni de secret.\n\nLivrable (texte) : le lien de partage de votre base Notion, avec un accès en lecture pour le formateur, ou, à défaut, le contenu des dix fiches collé en texte.","deliverable":"texte","estimatedMinutes":45,"review":"formateur","rubric":["Dix prompts liés au projet, couvrant au moins quatre usages différents","Propriétés Usage, Outil, Version et Qualité renseignées","Au moins cinq gabarits avec des variables explicites","Au moins une amélioration documentée (v1 vers v2)","Aucune donnée personnelle réelle ni secret"]}]$q$::jsonb)
on conflict (id) do nothing;

insert into crm.academy_lessons (id, course_id, module_id, position, title, summary, estimated_minutes, is_preview, blocks)
values ($q$crs_mvp_ia_m02_l07$q$, $q$crs_mvp_ia$q$, $q$crs_mvp_ia_m02$q$, 6, $q$Évaluation du module$q$, $q$Dix questions pour valider vos acquis sur le fonctionnement des assistants, l'écriture de prompts, le code assisté et les agents.$q$, 20, false, $q$[{"id":"crs_mvp_ia_m02_l07_b_1","type":"texte","markdown":"Cette évaluation vérifie que vous savez choisir quoi confier à une IA, rédiger un prompt efficace, piloter un outil de code et déléguer une tâche à un agent en sécurité.\n\n## Consignes\n\n- Dix questions, une seule bonne réponse par question.\n- Chaque question part d'une situation concrète : raisonnez comme sur votre propre projet.\n- Une explication s'affiche après chaque réponse : lisez-la, même quand vous avez juste.\n- Le score minimal attendu est indiqué dans votre espace. En cas d'échec, relisez les leçons concernées avant de retenter."},{"id":"crs_mvp_ia_m02_l07_b_2","type":"quiz","title":"Évaluation — Bien prompter","graded":true,"questions":[{"id":"crs_mvp_ia_m02_l07_b_2_q_1","prompt":"Un assistant vous propose d'utiliser une fonction d'une bibliothèque de code qui n'existe pas. Quelle est l'explication la plus juste ?","kind":"unique","options":[{"id":"crs_mvp_ia_m02_l07_b_2_q_1_o_1","label":"La fonction a été supprimée pendant la conversation","correct":false},{"id":"crs_mvp_ia_m02_l07_b_2_q_1_o_2","label":"L'assistant copie systématiquement des forums non fiables","correct":false},{"id":"crs_mvp_ia_m02_l07_b_2_q_1_o_3","label":"Le modèle génère le texte le plus plausible, sans vérifier qu'il est exact","correct":true},{"id":"crs_mvp_ia_m02_l07_b_2_q_1_o_4","label":"Votre prompt était trop poli","correct":false}],"explanation":"C'est une hallucination : la génération probabiliste produit du plausible, pas du vérifié. Parade : fournir la documentation officielle et tester le code."},{"id":"crs_mvp_ia_m02_l07_b_2_q_2","prompt":"Qu'est-ce que la fenêtre de contexte d'un modèle de langage ?","kind":"unique","options":[{"id":"crs_mvp_ia_m02_l07_b_2_q_2_o_1","label":"La quantité maximale de texte que le modèle prend en compte pour répondre","correct":true},{"id":"crs_mvp_ia_m02_l07_b_2_q_2_o_2","label":"La liste des sites web lus pendant l'entraînement","correct":false},{"id":"crs_mvp_ia_m02_l07_b_2_q_2_o_3","label":"La durée de conservation de vos conversations","correct":false},{"id":"crs_mvp_ia_m02_l07_b_2_q_2_o_4","label":"La zone de l'écran où s'affiche la réponse","correct":false}],"explanation":"La fenêtre de contexte, mesurée en tokens, limite ce que le modèle « voit » : consignes, historique, fichiers joints. Dans une longue conversation, les éléments anciens peuvent être moins bien pris en compte."},{"id":"crs_mvp_ia_m02_l07_b_2_q_3","prompt":"Vous voulez faire analyser par un assistant les retours de vos trente premiers clients. Que faites-vous ?","kind":"unique","options":[{"id":"crs_mvp_ia_m02_l07_b_2_q_3_o_1","label":"Vous collez l'export complet : l'assistant est tenu au secret","correct":false},{"id":"crs_mvp_ia_m02_l07_b_2_q_3_o_2","label":"Vous anonymisez les données (noms, e-mails, téléphones) avant de les transmettre","correct":true},{"id":"crs_mvp_ia_m02_l07_b_2_q_3_o_3","label":"Vous ajoutez « merci de ne pas conserver ces données » à la fin du prompt","correct":false},{"id":"crs_mvp_ia_m02_l07_b_2_q_3_o_4","label":"Vous activez la recherche web pour protéger les données","correct":false}],"explanation":"Les données personnelles ne doivent pas être transmises sans nécessité (principe de minimisation du RGPD). Une consigne dans le prompt ne change rien à la façon dont le service traite les données."},{"id":"crs_mvp_ia_m02_l07_b_2_q_4","prompt":"« Tu es rédacteur web. Rédige la page d'accueil de Créno en 150 mots, vouvoiement, avec un titre et trois bénéfices. » Quelle composante importante manque ?","kind":"unique","options":[{"id":"crs_mvp_ia_m02_l07_b_2_q_4_o_1","label":"Le rôle","correct":false},{"id":"crs_mvp_ia_m02_l07_b_2_q_4_o_2","label":"Le format de sortie","correct":false},{"id":"crs_mvp_ia_m02_l07_b_2_q_4_o_3","label":"Les contraintes","correct":false},{"id":"crs_mvp_ia_m02_l07_b_2_q_4_o_4","label":"Le contexte (produit, utilisateurs, irritants)","correct":true}],"explanation":"Rôle, contraintes (150 mots, vouvoiement) et format (titre, trois bénéfices) sont présents. Sans contexte, l'IA ignore qui sont les coachs et ce qui les gêne : le texte sera générique."},{"id":"crs_mvp_ia_m02_l07_b_2_q_5","prompt":"Au bout d'une longue conversation, l'assistant réintroduit une option que vous aviez écartée. Quelle est la meilleure réaction ?","kind":"unique","options":[{"id":"crs_mvp_ia_m02_l07_b_2_q_5_o_1","label":"Répéter la demande en majuscules","correct":false},{"id":"crs_mvp_ia_m02_l07_b_2_q_5_o_2","label":"Continuer : l'assistant finira par s'en souvenir","correct":false},{"id":"crs_mvp_ia_m02_l07_b_2_q_5_o_3","label":"Demander un résumé de passation, le corriger, puis repartir d'une nouvelle conversation","correct":true},{"id":"crs_mvp_ia_m02_l07_b_2_q_5_o_4","label":"Supprimer vos consignes persistantes","correct":false}],"explanation":"Dans une conversation trop longue, les consignes se diluent. Un résumé relu et corrigé donne un contexte propre et court à une nouvelle conversation."},{"id":"crs_mvp_ia_m02_l07_b_2_q_6","prompt":"À quoi sert un fichier CLAUDE.md ou AGENTS.md dans un dépôt de code ?","kind":"unique","options":[{"id":"crs_mvp_ia_m02_l07_b_2_q_6_o_1","label":"À transmettre durablement à l'outil de code les règles, la stack et les commandes du projet","correct":true},{"id":"crs_mvp_ia_m02_l07_b_2_q_6_o_2","label":"À stocker les clés d'API du projet","correct":false},{"id":"crs_mvp_ia_m02_l07_b_2_q_6_o_3","label":"À remplacer les tests automatiques","correct":false},{"id":"crs_mvp_ia_m02_l07_b_2_q_6_o_4","label":"À enregistrer l'historique des conversations avec l'IA","correct":false}],"explanation":"Ces fichiers de contexte sont lus par les agents de code (Claude Code, Codex et d'autres outils). Ils ne doivent jamais contenir de secrets."},{"id":"crs_mvp_ia_m02_l07_b_2_q_7","prompt":"Avant qu'un agent de code implémente une fonctionnalité, quelle pratique réduit le plus le risque de malentendu ?","kind":"unique","options":[{"id":"crs_mvp_ia_m02_l07_b_2_q_7_o_1","label":"Lui demander d'écrire tout le code d'un coup pour gagner du temps","correct":false},{"id":"crs_mvp_ia_m02_l07_b_2_q_7_o_2","label":"Lui demander un plan et le valider avant toute modification","correct":true},{"id":"crs_mvp_ia_m02_l07_b_2_q_7_o_3","label":"Désactiver les tests pour aller plus vite","correct":false},{"id":"crs_mvp_ia_m02_l07_b_2_q_7_o_4","label":"Ne rien préciser pour lui laisser de la liberté","correct":false}],"explanation":"Le plan est le moment le moins coûteux pour corriger un malentendu : fichiers concernés, étapes, tests, risques. On code ensuite par petites étapes."},{"id":"crs_mvp_ia_m02_l07_b_2_q_8","prompt":"Un agent de code vous présente un diff qui modifie aussi un fichier non mentionné et supprime un test existant. Que faites-vous ?","kind":"unique","options":[{"id":"crs_mvp_ia_m02_l07_b_2_q_8_o_1","label":"Vous committez : si le reste fonctionne, c'est suffisant","correct":false},{"id":"crs_mvp_ia_m02_l07_b_2_q_8_o_2","label":"Vous supprimez le projet et recommencez","correct":false},{"id":"crs_mvp_ia_m02_l07_b_2_q_8_o_3","label":"Vous désactivez la relecture des diffs pour la suite","correct":false},{"id":"crs_mvp_ia_m02_l07_b_2_q_8_o_4","label":"Vous demandez pourquoi, et refusez la suppression du test sans justification valable","correct":true}],"explanation":"On ne committe jamais sans comprendre. Un test supprimé pour « faire passer » la vérification est un signal d'alerte classique."},{"id":"crs_mvp_ia_m02_l07_b_2_q_9","prompt":"Parmi ces actions confiées à un agent, laquelle doit impérativement passer par votre validation ?","kind":"unique","options":[{"id":"crs_mvp_ia_m02_l07_b_2_q_9_o_1","label":"Lire les fichiers d'un dossier de travail","correct":false},{"id":"crs_mvp_ia_m02_l07_b_2_q_9_o_2","label":"Rédiger un brouillon de synthèse","correct":false},{"id":"crs_mvp_ia_m02_l07_b_2_q_9_o_3","label":"Envoyer un e-mail à vos cinquante premiers inscrits","correct":true},{"id":"crs_mvp_ia_m02_l07_b_2_q_9_o_4","label":"Lister les sources consultées","correct":false}],"explanation":"L'envoi d'un e-mail est irréversible et engage votre image. Règle : l'agent prépare, vous validez toute action irréversible."},{"id":"crs_mvp_ia_m02_l07_b_2_q_10","prompt":"Dans votre bibliothèque de prompts, pourquoi noter la version et ce qui a changé à chaque amélioration ?","kind":"unique","options":[{"id":"crs_mvp_ia_m02_l07_b_2_q_10_o_1","label":"Pour pouvoir comparer, revenir en arrière et comprendre ce qui améliore les résultats","correct":true},{"id":"crs_mvp_ia_m02_l07_b_2_q_10_o_2","label":"Parce que Notion l'exige pour enregistrer une page","correct":false},{"id":"crs_mvp_ia_m02_l07_b_2_q_10_o_3","label":"Pour que l'IA reconnaisse le prompt","correct":false},{"id":"crs_mvp_ia_m02_l07_b_2_q_10_o_4","label":"Pour réduire la longueur du prompt","correct":false}],"explanation":"Versionner ses prompts, comme du code, permet de mesurer l'effet d'un changement et de revenir à une version qui fonctionnait."}]}]$q$::jsonb)
on conflict (id) do nothing;

insert into crm.academy_lessons (id, course_id, module_id, position, title, summary, estimated_minutes, is_preview, blocks)
values ($q$crs_mvp_ia_m03_l01$q$, $q$crs_mvp_ia$q$, $q$crs_mvp_ia_m03$q$, 0, $q$Les grandes familles d'outils$q$, $q$Les briques d'une application web et les familles d'outils qui les couvrent, d'Airtable à Vercel en passant par Supabase et les agents de code.$q$, 40, false, $q$[{"id":"crs_mvp_ia_m03_l01_b_1","type":"texte","markdown":"À la fin de cette leçon, vous saurez situer chaque outil de la formation dans sa famille, expliquer son rôle dans une application, et repérer les briques dont votre projet a besoin.\n\n## Ce dont une application web a besoin\n\nQuelle que soit la façon de la construire, une application comme Créno repose sur les mêmes briques :\n\n- **l'interface** (le *front-end*) : ce que l'utilisateur voit et manipule dans son navigateur, comme la liste des créneaux ou le bouton « Réserver » ;\n- **la logique** (le *back-end*) : les règles exécutées sur un serveur, comme vérifier qu'un créneau est encore libre ou déclencher le paiement ;\n- **la base de données** : l'endroit où les informations sont stockées durablement (profils, créneaux, réservations, paiements) ;\n- **l'authentification** : la gestion des comptes et des connexions, pour savoir qui est coach et qui est client ;\n- **les intégrations** : les services externes branchés à l'application (paiement, envoi d'e-mails, calendrier) ;\n- **l'hébergement** : le serveur, toujours allumé, qui rend l'application accessible sur Internet à une adresse web.\n\nAutour de ces briques, il vous faut des outils pour **construire** (écrire ou générer l'application) et pour **piloter** le projet (documenter, planifier, versionner)."},{"id":"crs_mvp_ia_m03_l01_b_2","type":"video","title":"Anatomie d'une application web","url":"","durationMinutes":6,"script":"- Accroche : la page de réservation de Créno à l'écran. Que se passe-t-il quand on clique sur « Réserver » ?\n- Schéma animé : navigateur (interface) → serveur (logique) → base de données → réponse affichée.\n- Où interviennent l'authentification, le paiement et l'e-mail de confirmation.\n- Les familles d'outils posées sur le schéma : React et Next.js, Supabase, Vercel, n8n.\n- La même application en version « concierge » : formulaire, table Airtable, workflow n8n, et ce qui reste fait à la main.\n- La même application générée avec Bolt.new : ce qui est produit automatiquement, ce qu'il faut vérifier.\n- Conclusion : raisonner en briques avant de choisir des outils."},{"id":"crs_mvp_ia_m03_l01_b_3","type":"texte","markdown":"## Les familles d'outils\n\n### Bases de données « tableur » et no-code : Airtable\nLe **no-code** désigne les outils qui permettent de construire par configuration, sans écrire de code. Airtable ressemble à un tableur, mais chaque tableau est une vraie table de base de données : types de champs, liens entre tables, vues filtrées, formulaires, interfaces simples et automatisations. Idéal pour gérer des données et un processus rapidement. Limite : il n'est pas conçu pour une application grand public sur mesure.\n\n### Automatisation : n8n\nUn outil d'automatisation enchaîne des actions entre applications sous forme de **workflows** (scénarios) : « la veille de la séance, envoyer un rappel au client ». n8n se configure visuellement, avec des blocs (appelés nœuds) reliés entre eux, se connecte à de nombreux services, accepte du code quand c'est nécessaire, et peut être utilisé en version hébergée ou installé sur votre propre serveur.\n\n### Générateurs d'applications par IA : Bolt.new\nVous décrivez l'application en langage naturel ; l'outil génère un projet complet, l'exécute dans le navigateur et vous permet de l'améliorer par prompts. C'est la voie la plus rapide vers un prototype cliquable. Le code produit est un vrai code que vous pouvez récupérer : un point essentiel pour ne pas rester bloqué.\n\n### Code assisté par IA : Cursor, Claude Code, Codex\nVous (ou un agent) travaillez directement dans le code du projet. Cursor est un éditeur de code avec une IA intégrée ; Claude Code et Codex sont des agents qui lisent le dépôt, modifient les fichiers et lancent des commandes. Plus de contrôle, plus d'exigence : il faut savoir relire et tester (module 2, leçon 4).\n\n### Bibliothèques et frameworks front : React, Next.js\nUne **bibliothèque** fournit des briques de code réutilisables ; un **framework** fournit en plus une structure et des conventions. React sert à construire des interfaces à partir de composants (un bouton, une carte de créneau, un calendrier). Next.js est un framework construit sur React qui ajoute les pages, la navigation et l'exécution de code côté serveur. Ce sont des technologies très répandues, donc bien connues des outils d'IA.\n\n### Backend as a service : Supabase\nUn **backend as a service** fournit « clés en main » ce qu'il faudrait sinon développer côté serveur. Supabase propose une base de données **Postgres** (un système de base de données relationnelle open source, très répandu), l'**authentification** des utilisateurs, le **stockage** de fichiers et la **sécurité par lignes** (*Row Level Security*, ou RLS) : des règles écrites dans la base qui déterminent quelles lignes chaque utilisateur peut lire ou modifier (« un client ne voit que ses propres réservations »).\n\n### Hébergement : Vercel\nVercel héberge des applications web, en particulier celles construites avec Next.js, dont il est l'éditeur. Il se connecte à votre dépôt GitHub : à chaque modification envoyée, il construit et publie une nouvelle version, avec des adresses de prévisualisation pour tester avant la mise en production.\n\n### Outils de pilotage : Notion, GitHub\nNotion sert à documenter et à organiser : PRD, backlog, comptes rendus, bibliothèque de prompts. GitHub héberge le code et son historique (géré avec Git), et offre des outils de collaboration : tickets, revues de code, automatisations."},{"id":"crs_mvp_ia_m03_l01_b_4","type":"texte","markdown":"## Tableau récapitulatif\n\n| Famille | Outil de la formation | Briques couvertes | Niveau technique | Rôle dans Créno |\n| --- | --- | --- | --- | --- |\n| Base no-code | Airtable | Données, formulaires | Faible | MVP concierge : créneaux et réservations gérés à la main |\n| Automatisation | n8n | Intégrations, tâches planifiées | Faible à moyen | Rappel automatique la veille de la séance |\n| Générateur d'application | Bolt.new | Interface, logique, prototype | Faible au départ | Prototype rapide pour un profil non technique |\n| Code assisté | Cursor, Claude Code, Codex | Tout le code | Moyen à élevé | Construction de la version robuste |\n| Front | React, Next.js | Interface, logique serveur | Moyen à élevé | Pages coach et client |\n| Backend as a service | Supabase | Base, authentification, stockage, sécurité | Moyen | Profils, créneaux, réservations, paiements |\n| Hébergement | Vercel | Mise en ligne | Faible à moyen | Publication de l'application |\n| Pilotage | Notion, GitHub | Documentation, code, suivi | Faible | PRD, backlog, dépôt de code |\n\nLe paiement (Stripe pour Créno) et l'envoi d'e-mails relèvent de services spécialisés que l'on branche en intégration : vous les verrez aux modules 4 et 6.\n\n> [!info] Un même outil peut couvrir plusieurs familles, et les frontières bougent vite : les générateurs ajoutent des bases de données, les éditeurs ajoutent des agents, les outils no-code ajoutent de l'IA. Raisonnez d'abord en briques (de quoi ai-je besoin ?), ensuite en outils."},{"id":"crs_mvp_ia_m03_l01_b_5","type":"texte","markdown":"## Une image pour tout retenir : le restaurant\n\n- La **salle**, où les clients s'installent et commandent, c'est l'interface.\n- La **cuisine**, où les commandes sont préparées selon des règles, c'est la logique.\n- La **réserve**, où sont rangés les ingrédients, c'est la base de données.\n- L'**accueil**, qui vérifie la réservation au nom du client, c'est l'authentification.\n- Les **fournisseurs** livrés automatiquement, ce sont les intégrations et les automatisations.\n- Le **local** loué dans une rue passante, c'est l'hébergement.\n- Le **cahier de l'équipe** et le planning, ce sont les outils de pilotage.\n\nQuand un terme technique vous échappe, demandez-vous à quelle pièce du restaurant il correspond.","personas":["reconversion"]},{"id":"crs_mvp_ia_m03_l01_b_6","type":"texte","markdown":"## Profil non technique : vos familles prioritaires\n\nQuatre familles vous permettent d'aller loin sans coder : la base no-code (Airtable), l'automatisation (n8n), le générateur d'application (Bolt.new) et le backend as a service (Supabase), que Bolt.new peut utiliser pour vous. Vous n'avez pas besoin de maîtriser React ou Next.js, mais savoir ce qu'ils sont vous permettra de dialoguer avec un développeur ou un prestataire, et de comprendre ce que génèrent vos outils.","personas":["non_tech"]},{"id":"crs_mvp_ia_m03_l01_b_7","type":"texte","markdown":"## Profil technique : les vraies questions\n\nVous connaissez probablement ces briques. Les questions utiles pour un MVP sont ailleurs : quelle part de la logique métier vit dans la base (contraintes, fonctions, RLS) plutôt que dans le code applicatif ; comment les générateurs structurent le code (à relire avant de le reprendre) ; quels services vous enferment. Supabase repose sur un Postgres standard, ce qui facilite une migration éventuelle ; les fonctions propres à une plateforme se remplacent moins facilement. Gardez ce critère de portabilité en tête pour la leçon suivante.","personas":["tech"]},{"id":"crs_mvp_ia_m03_l01_b_8","type":"quiz","title":"Auto-évaluation : à chaque outil sa famille","graded":false,"questions":[{"id":"crs_mvp_ia_m03_l01_b_8_q_1","prompt":"Quel outil fournit une base Postgres, l'authentification, le stockage de fichiers et la sécurité par lignes ?","kind":"unique","options":[{"id":"crs_mvp_ia_m03_l01_b_8_q_1_o_1","label":"Vercel","correct":false},{"id":"crs_mvp_ia_m03_l01_b_8_q_1_o_2","label":"Supabase","correct":true},{"id":"crs_mvp_ia_m03_l01_b_8_q_1_o_3","label":"n8n","correct":false},{"id":"crs_mvp_ia_m03_l01_b_8_q_1_o_4","label":"Notion","correct":false}],"explanation":"Supabase est un backend as a service : base Postgres, authentification, stockage et règles RLS."},{"id":"crs_mvp_ia_m03_l01_b_8_q_2","prompt":"Vous voulez envoyer automatiquement un rappel la veille de chaque séance, sans coder. Quelle famille d'outils ?","kind":"unique","options":[{"id":"crs_mvp_ia_m03_l01_b_8_q_2_o_1","label":"Un framework front comme React","correct":false},{"id":"crs_mvp_ia_m03_l01_b_8_q_2_o_2","label":"Un hébergeur comme Vercel","correct":false},{"id":"crs_mvp_ia_m03_l01_b_8_q_2_o_3","label":"Un outil d'automatisation comme n8n","correct":true},{"id":"crs_mvp_ia_m03_l01_b_8_q_2_o_4","label":"Un outil de pilotage comme GitHub","correct":false}],"explanation":"Un workflow d'automatisation (déclencheur planifié, puis envoi d'un message) est exactement le rôle de n8n."},{"id":"crs_mvp_ia_m03_l01_b_8_q_3","prompt":"Qu'est-ce que Next.js ?","kind":"unique","options":[{"id":"crs_mvp_ia_m03_l01_b_8_q_3_o_1","label":"Une base de données relationnelle","correct":false},{"id":"crs_mvp_ia_m03_l01_b_8_q_3_o_2","label":"Un générateur d'applications par IA","correct":false},{"id":"crs_mvp_ia_m03_l01_b_8_q_3_o_3","label":"Un service d'envoi d'e-mails","correct":false},{"id":"crs_mvp_ia_m03_l01_b_8_q_3_o_4","label":"Un framework construit sur React qui ajoute pages, navigation et code côté serveur","correct":true}],"explanation":"React construit les interfaces à partir de composants ; Next.js ajoute une structure de projet, les pages et l'exécution côté serveur."},{"id":"crs_mvp_ia_m03_l01_b_8_q_4","prompt":"Quel est le rôle principal de Vercel dans une stack ?","kind":"unique","options":[{"id":"crs_mvp_ia_m03_l01_b_8_q_4_o_1","label":"Héberger et publier l'application à partir du dépôt de code","correct":true},{"id":"crs_mvp_ia_m03_l01_b_8_q_4_o_2","label":"Stocker les réservations","correct":false},{"id":"crs_mvp_ia_m03_l01_b_8_q_4_o_3","label":"Rédiger le code à votre place","correct":false},{"id":"crs_mvp_ia_m03_l01_b_8_q_4_o_4","label":"Gérer le backlog du projet","correct":false}],"explanation":"Vercel construit et publie l'application à chaque modification du dépôt, avec des adresses de prévisualisation."},{"id":"crs_mvp_ia_m03_l01_b_8_q_5","prompt":"Quelle affirmation sur Bolt.new est juste ?","kind":"unique","options":[{"id":"crs_mvp_ia_m03_l01_b_8_q_5_o_1","label":"Il ne produit que des maquettes non fonctionnelles","correct":false},{"id":"crs_mvp_ia_m03_l01_b_8_q_5_o_2","label":"Il génère un projet de code à partir d'une description, que l'on peut récupérer","correct":true},{"id":"crs_mvp_ia_m03_l01_b_8_q_5_o_3","label":"Il remplace la nécessité de vérifier la sécurité","correct":false},{"id":"crs_mvp_ia_m03_l01_b_8_q_5_o_4","label":"Il sert uniquement à héberger des sites","correct":false}],"explanation":"Bolt.new génère un vrai projet de code, exécuté dans le navigateur et récupérable. La sécurité reste à vérifier."}]},{"id":"crs_mvp_ia_m03_l01_b_9","type":"exercice","title":"Cartographier les briques de votre projet","instructions":"1. Listez les briques nécessaires à votre MVP : interface, logique, données, authentification, intégrations (paiement, e-mail, calendrier…), hébergement.\n2. Pour chaque brique, écrivez en une phrase ce qu'elle doit faire dans votre projet. Exemple Créno : « intégration paiement : encaisser la séance au moment de la réservation ».\n3. Indiquez pour chacune les familles d'outils possibles (pas encore le choix final).\n4. Repérez les briques dont vous pourriez vous passer au départ, en les remplaçant par une action manuelle (exemple : confirmer les réservations à la main pendant les premières semaines).\n\nLivrable (texte) : un tableau brique / besoin / familles possibles / faisable à la main au début ?","deliverable":"texte","estimatedMinutes":20,"review":"auto","rubric":["Toutes les briques nécessaires au MVP sont identifiées","Chaque besoin est formulé concrètement pour le projet","Les familles d'outils proposées correspondent aux briques","Au moins une brique « faisable à la main » est identifiée ou explicitement écartée"]}]$q$::jsonb)
on conflict (id) do nothing;

insert into crm.academy_lessons (id, course_id, module_id, position, title, summary, estimated_minutes, is_preview, blocks)
values ($q$crs_mvp_ia_m03_l02$q$, $q$crs_mvp_ia$q$, $q$crs_mvp_ia_m03$q$, 1, $q$Les critères de choix$q$, $q$Huit critères pour évaluer une stack et une matrice de décision pondérée pour choisir en connaissance de cause.$q$, 45, false, $q$[{"id":"crs_mvp_ia_m03_l02_b_1","type":"texte","markdown":"À la fin de cette leçon, vous saurez évaluer des options techniques selon huit critères et les comparer avec une matrice de décision pondérée, pour choisir en connaissance de cause plutôt que par effet de mode.\n\n## Il n'y a pas de meilleure stack, seulement une stack adaptée\n\nUne **stack** est l'ensemble des outils et technologies utilisés pour construire et faire fonctionner votre produit. La bonne stack de MVP est celle qui vous permet de **tester votre hypothèse principale le plus vite possible, avec une qualité suffisante, sans vous enfermer**. Elle dépend de vous, de votre projet et de votre contexte.\n\n## Les huit critères\n\n### 1. Compétences disponibles\nQui va construire ? Vous seul, un associé technique, un prestataire ? Un outil que personne ne maîtrise coûte des semaines d'apprentissage. L'IA abaisse la barrière sans la supprimer : il faut toujours savoir relire, tester et corriger ce qui est produit.\n\n### 2. Délai\nCombien de temps avant de mettre le produit entre les mains d'utilisateurs ? Un délai court favorise le no-code et les générateurs ; un délai plus long permet d'investir dans une base plus solide.\n\n### 3. Budget\nCe que vous pouvez dépenser chaque mois en abonnements et services, et en prestations éventuelles. Beaucoup d'outils de cette formation proposent une offre gratuite ou d'essai pour démarrer : vérifiez ce qu'elle inclut (leçon 4).\n\n### 4. Données et conformité\nQuelles données allez-vous traiter ? Des données personnelles (noms, e-mails, téléphones) impliquent le respect du RGPD : minimisation, sécurité, information des personnes, encadrement contractuel des prestataires qui les hébergent. Vérifiez où les données sont hébergées (certains services permettent de choisir la région), quelles garanties sont proposées, et si des données sensibles (de santé, par exemple) sont en jeu. Ce sont des informations générales, pas un conseil juridique : consultez [cnil.fr](https://www.cnil.fr).\n\n### 5. Montée en charge\nLa capacité à supporter davantage d'utilisateurs, de données et de trafic sans tout refaire. Pour un MVP, c'est rarement le critère principal : mieux vaut valider la demande avec dix utilisateurs que préparer une architecture pour cent mille. Évitez seulement les impasses connues, comme un outil dont les limites seraient atteintes dès les premiers mois de succès.\n\n### 6. Dépendance et portabilité\nPouvez-vous **récupérer votre code et vos données** si vous changez d'outil ? Un outil qui permet d'exporter le code (vers un dépôt GitHub, par exemple) et les données dans des formats standards vous laisse libre. Un outil fermé peut vous obliger à tout reconstruire le jour où il ne suffit plus, change ses conditions ou disparaît.\n\n### 7. Coût à l'usage\nAu-delà de l'abonnement, certains coûts augmentent avec l'activité : appels à un modèle d'IA, stockage, e-mails envoyés, exécutions d'automatisations, commissions de paiement. Un outil bon marché au départ peut devenir coûteux avec le succès, et inversement.\n\n### 8. Écosystème et communauté\nDocumentation, tutoriels, forums, intégrations disponibles, développeurs qui connaissent l'outil. Un outil très répandu a aussi l'avantage d'être bien connu des assistants IA, ce qui tend à améliorer la qualité de leur aide."},{"id":"crs_mvp_ia_m03_l02_b_2","type":"texte","markdown":"## La matrice de décision pondérée\n\nUne **matrice de décision pondérée** compare plusieurs options sur plusieurs critères, en tenant compte de leur importance relative :\n\n1. Listez deux à quatre options.\n2. Donnez à chaque critère un **poids** de 1 (secondaire) à 5 (décisif), selon *votre* situation.\n3. Notez chaque option sur chaque critère, de 1 (mauvais) à 5 (excellent).\n4. Multipliez chaque note par le poids du critère et additionnez : c'est le score de l'option.\n5. Relisez le résultat d'un œil critique : la matrice éclaire la décision, elle ne la prend pas.\n\nExemple : la fondatrice de Créno ne code pas, dispose de six semaines et veut vérifier que dix coachs sont prêts à utiliser le service. Elle compare trois options, détaillées à la leçon suivante. Les notes sont ses appréciations pour ce cas précis, pas une évaluation générale des outils. Entre parenthèses : note × poids.\n\n| Critère | Poids | A. Bolt.new + Supabase | B. Next.js + Supabase + Vercel | C. Concierge Airtable + n8n |\n| --- | --- | --- | --- | --- |\n| Compétences disponibles | 5 | 4 (20) | 1 (5) | 5 (25) |\n| Délai | 4 | 4 (16) | 2 (8) | 5 (20) |\n| Budget | 3 | 4 (12) | 4 (12) | 4 (12) |\n| Données et conformité | 3 | 4 (12) | 4 (12) | 3 (9) |\n| Montée en charge | 1 | 3 (3) | 5 (5) | 1 (1) |\n| Portabilité | 2 | 4 (8) | 5 (10) | 2 (4) |\n| Coût à l'usage | 2 | 3 (6) | 3 (6) | 3 (6) |\n| Écosystème | 2 | 4 (8) | 5 (10) | 4 (8) |\n| **Score** | | **85** | **68** | **85** |\n\nÉgalité entre A et C : c'est fréquent, et instructif. Ce qui départage, c'est l'**hypothèse à valider en premier**. Ici, la question est « les coachs veulent-ils ce service ? », pas « sait-on construire l'application ? ». La fondatrice choisit C pour les premières semaines, puis A dès que la demande est confirmée. L'option B reste la cible si Créno grandit ou accueille un profil technique.\n\n> [!warning] Pièges classiques : ajuster les poids après coup pour retrouver l'option que l'on préférait déjà, choisir un outil parce qu'il est à la mode, sous-estimer le critère « compétences disponibles »."},{"id":"crs_mvp_ia_m03_l02_b_3","type":"texte","markdown":"## Votre critère décisif : l'autonomie\n\nPour un profil non technique, la question clé est souvent : **puis-je faire évoluer le produit seul, sans attendre quelqu'un ?** Une stack que vous comprenez vous permet d'avancer au rythme des retours utilisateurs. Donnez un poids fort aux compétences et au délai, et un poids réel à la portabilité : si un développeur vous rejoint plus tard, il devra pouvoir reprendre le code et les données. Méfiez-vous des outils qui ne permettent aucun export.","personas":["non_tech"]},{"id":"crs_mvp_ia_m03_l02_b_4","type":"texte","markdown":"## Profil technique : résister à la sur-ingénierie\n\nVotre risque n'est pas de ne pas savoir construire, mais de trop construire : architecture en microservices, files de messages, infrastructure sur mesure pour dix utilisateurs. Au stade du MVP, donnez un poids faible à la montée en charge et un poids fort au délai. Préférez les services gérés (base, authentification, hébergement) à l'auto-hébergement, sauf contrainte forte sur les données. Votre avantage technique doit vous servir à apprendre plus vite du marché, pas à peaufiner une stack.","personas":["tech"]},{"id":"crs_mvp_ia_m03_l02_b_5","type":"texte","markdown":"## Si vous hésitez sur une note\n\nIl est normal de ne pas savoir noter certains critères au départ. Mettez 3 (neutre) et posez la question à votre formateur. Un bon réflexe : pour chaque option, suivez pendant trente minutes le tutoriel officiel de démarrage. Votre ressenti (clair, confus, bloquant) est une information précieuse pour le critère « compétences disponibles ».","personas":["reconversion"]},{"id":"crs_mvp_ia_m03_l02_b_6","type":"prompt","title":"Faire challenger sa matrice de décision","tool":"Tout assistant IA","prompt":"Je dois choisir la stack technique du MVP de mon projet.\nProjet : [DESCRIPTION EN 3 PHRASES]\nMon profil et mon équipe : [COMPÉTENCES]\nDélai avant les premiers utilisateurs : [DÉLAI]\nHypothèse principale à valider : [HYPOTHÈSE]\nDonnées traitées : [TYPES DE DONNÉES, SANS AUCUNE DONNÉE RÉELLE]\n\nVoici ma matrice de décision pondérée :\n[COLLEZ LE TABLEAU]\n\n1. Signale les poids qui te semblent incohérents avec ma situation, et explique pourquoi.\n2. Signale les notes qui mériteraient d'être vérifiées, et comment les vérifier (documentation officielle, test rapide).\n3. Indique les critères importants que j'aurais oubliés.\n\nNe choisis pas à ma place et ne cite aucun prix : je vérifierai les tarifs sur les sites officiels.","tips":"L'IA peut avoir des informations dépassées sur les outils : utilisez ses remarques comme des questions à vérifier, pas comme des faits."},{"id":"crs_mvp_ia_m03_l02_b_7","type":"exercice","title":"Votre matrice de décision pondérée","instructions":"1. Décrivez votre situation en quelques lignes : profil et compétences de l'équipe, délai, hypothèse principale à valider, types de données traitées.\n2. Retenez deux ou trois options de stack. Les trois stacks de la leçon suivante sont un bon point de départ ; vous pourrez ajuster votre choix pendant l'atelier de la leçon 5.\n3. Pondérez les huit critères de 1 à 5, en justifiant d'une phrase chaque poids de 4 ou 5.\n4. Notez chaque option, puis calculez les scores.\n5. Soumettez votre matrice au prompt « Faire challenger sa matrice de décision » et corrigez ce qui doit l'être.\n6. Concluez en trois lignes : quelle option, pour quelle étape du projet, et ce qui vous ferait changer d'avis.\n\nLivrable (texte) : la matrice, les justifications et la conclusion.","deliverable":"texte","estimatedMinutes":30,"review":"auto","rubric":["La situation du projet est décrite (profil, délai, hypothèse, données)","Les huit critères sont pondérés et les poids forts justifiés","Les scores sont correctement calculés","La conclusion relie le choix à l'hypothèse à valider"]}]$q$::jsonb)
on conflict (id) do nothing;

insert into crm.academy_lessons (id, course_id, module_id, position, title, summary, estimated_minutes, is_preview, blocks)
values ($q$crs_mvp_ia_m03_l03$q$, $q$crs_mvp_ia$q$, $q$crs_mvp_ia_m03$q$, 2, $q$Trois stacks de référence$q$, $q$Bolt.new + Supabase, Next.js + Supabase + Vercel, et le MVP concierge Airtable + n8n : cas d'usage, forces, limites et trajectoires.$q$, 60, false, $q$[{"id":"crs_mvp_ia_m03_l03_b_1","type":"texte","markdown":"À la fin de cette leçon, vous connaîtrez trois stacks de référence pour un MVP, leurs forces et leurs limites, et vous saurez laquelle choisir pour démarrer selon votre profil et votre hypothèse.\n\n## Trois stacks, trois intentions\n\n- **Stack A — Bolt.new + Supabase** : obtenir vite un prototype fonctionnel sans coder, avec un code que l'on peut récupérer.\n- **Stack B — Next.js + React + Supabase + Vercel, avec Cursor, Claude Code ou Codex** : garder le contrôle total sur un produit destiné à durer.\n- **Stack C — Airtable + n8n + une page simple** : valider la demande avec un MVP « concierge » avant de construire.\n\nCes stacks ne s'opposent pas : ce sont souvent les étapes successives d'un même projet."},{"id":"crs_mvp_ia_m03_l03_b_2","type":"video","title":"Trois stacks, un même projet : Créno","url":"","durationMinutes":8,"script":"- Accroche : le même besoin (« un client réserve un créneau et paie ») construit trois fois.\n- Stack C : page de présentation et formulaire, table Airtable des réservations, workflow n8n de rappel ; ce qui reste manuel.\n- Stack A : prompt dans Bolt.new, génération de l'application, tables créées dans Supabase ; vérification rapide des règles d'accès ; récupération du code.\n- Stack B : dépôt GitHub, fichier de contexte, agent de code, migration Supabase avec règles RLS, déploiement sur Vercel avec prévisualisation.\n- Tableau comparatif à l'écran : délai, contrôle, portabilité, risques.\n- Trajectoires : de C vers A puis B, et les signaux qui déclenchent le passage à l'étape suivante.\n- Conclusion : choisir sa stack de départ selon son profil et l'hypothèse à valider."},{"id":"crs_mvp_ia_m03_l03_b_3","type":"texte","markdown":"## Stack A — Bolt.new + Supabase\n\n**Principe.** Vous décrivez votre application dans Bolt.new ; il génère l'interface et la logique, et s'appuie sur Supabase pour la base de données et l'authentification. Vous l'améliorez par prompts, en voyant le résultat en direct dans le navigateur.\n\n**Cas d'usage.** Prototype fonctionnel pour des tests utilisateurs, démonstration à des partenaires, premier MVP d'un profil non technique.\n\n**Forces.**\n- Délai très court entre l'idée et une application cliquable.\n- Une vraie base de données relationnelle dès le départ.\n- Du code standard, que vous pouvez récupérer et confier plus tard à un développeur ou à un agent de code.\n\n**Limites.**\n- Le code généré n'est pas toujours bien structuré : quand l'application grossit, les modifications par prompts deviennent moins fiables.\n- La sécurité (règles RLS, clés, validation des données) doit être vérifiée : elle n'est pas garantie par la génération.\n- L'usage de la génération par IA est limité selon l'offre choisie : vérifiez les conditions sur la page tarifs.\n\n**Parcours de Créno.** Un prompt décrit les rôles, les écrans et les données ; Bolt.new génère l'application et les tables dans Supabase (profils, créneaux, réservations). La fondatrice teste chaque écran, corrige par petits prompts, vérifie les règles d'accès avec la checklist du module 4, puis récupère le code (export ou synchronisation avec GitHub, selon les options disponibles). Le paiement vient dans un second temps.\n\n## Stack B — Next.js + React + Supabase + Vercel, avec un outil de code assisté\n\n**Principe.** Le code vit dans un dépôt GitHub : Next.js et React pour l'interface et la logique serveur, Supabase pour la base, l'authentification et la sécurité, Vercel pour l'hébergement. Cursor, Claude Code ou Codex accélèrent l'écriture, sous votre contrôle : plan, petites étapes, tests, relecture des diffs.\n\n**Cas d'usage.** Produit appelé à durer, logique métier spécifique (règles d'annulation, paiements, rôles), profil technique ou très motivé pour apprendre, équipe avec un développeur.\n\n**Forces.**\n- Contrôle total sur le code, l'architecture et la sécurité.\n- Technologies très répandues : documentation abondante, recrutement facilité, assistants IA à l'aise.\n- Portabilité : le code vous appartient, la base est un Postgres standard, l'hébergeur peut être changé.\n- Déploiement continu : chaque modification envoyée sur GitHub peut être publiée automatiquement par Vercel, avec une version de prévisualisation.\n\n**Limites.**\n- Courbe d'apprentissage réelle : Git, terminal, structure d'un projet, variables d'environnement.\n- Plus de décisions à prendre, donc plus de risques de s'éparpiller.\n- Vous êtes responsable de la qualité : tests, sécurité, mises à jour des dépendances.\n\n**Parcours de Créno.** C'est la stack de démonstration de la formation. Le dépôt contient un fichier de contexte ; les tables sont créées par des migrations Supabase avec leurs règles RLS ; les écrans coach et client sont développés un par un avec un agent de code ; Stripe gère les paiements et n8n les rappels ; Vercel publie chaque version. Vous suivrez ce parcours au module 6.\n\n## Stack C — Airtable + n8n + page simple (MVP concierge)\n\n**Principe.** Un **MVP concierge** rend le service en grande partie à la main, en coulisses, pour vérifier que des clients en veulent avant d'automatiser. L'utilisateur voit une page simple et un formulaire ; vous gérez le reste avec une base Airtable et quelques automatisations n8n.\n\n**Cas d'usage.** Demande non encore validée, délai très court, service que l'on peut rendre manuellement pour quelques dizaines d'utilisateurs.\n\n**Forces.**\n- Mise en place en quelques jours, sans code.\n- Contact direct avec les premiers utilisateurs : chaque demande traitée vous apprend quelque chose.\n- Investissement minimal : si l'hypothèse est invalidée, presque rien n'est à jeter.\n\n**Limites.**\n- Ne passe pas à l'échelle : le travail manuel augmente avec chaque utilisateur.\n- Expérience utilisateur limitée (pas d'espace personnel, peu d'interactivité).\n- Données réparties entre plusieurs outils : soignez la conformité (qui a accès, où sont les données) et prévoyez l'export.\n\n**Parcours de Créno.** Une page par coach avec un formulaire de réservation. Chaque demande arrive dans une table Airtable « Réservations ». La fondatrice confirme à la main et envoie un lien de paiement ; un workflow n8n envoie le rappel la veille. Après quelques semaines, elle sait si coachs et clients utilisent vraiment le service, quelles règles d'annulation sont nécessaires, et quoi automatiser en priorité.\n\n## En résumé\n\n| | A. Bolt.new + Supabase | B. Next.js + Supabase + Vercel | C. Concierge Airtable + n8n |\n| --- | --- | --- | --- |\n| Objectif | Prototype fonctionnel rapide | Produit robuste et durable | Valider la demande |\n| Profil | Non technique à intermédiaire | Technique ou très motivé | Tous profils |\n| Mise en place | Courte | Plus longue | Très courte |\n| Contrôle et portabilité | Moyens à bons (code récupérable) | Maximaux | Faibles |\n| Principal risque | Code difficile à maintenir, sécurité non vérifiée | S'éparpiller, construire trop tôt | Travail manuel, expérience limitée |\n\nLa **trajectoire** typique va de C vers A ou B : valider la demande, puis construire. Passer de A à B est aussi naturel : le code récupéré depuis Bolt.new est repris dans un éditeur et restructuré avec un agent de code. Si les deux étapes utilisent le même projet Supabase, les données restent en place pendant la transition."},{"id":"crs_mvp_ia_m03_l03_b_4","type":"texte","markdown":"## Votre point de départ recommandé : C, puis A\n\nCommencez par la stack C si la demande n'est pas encore validée : vous la mettez en place seul, en quelques jours. Dès que la demande est confirmée, passez à la stack A pour offrir une vraie expérience applicative. Deux précautions : récupérez le code sur GitHub dès les premières versions, et faites relire la sécurité (règles RLS, clés) par une personne technique avant d'ouvrir l'application à de vrais clients. Trajectoire à moyen terme : la stack B, avec un associé technique ou un prestataire qui reprend le code existant.","personas":["non_tech"]},{"id":"crs_mvp_ia_m03_l03_b_5","type":"texte","markdown":"## Votre point de départ recommandé : B, précédée de C si la demande est incertaine\n\nVous pouvez aller directement vers la stack B : c'est elle qui vous donnera le plus de levier à moyen terme. Mais si la demande n'est pas validée, la meilleure décision technique est parfois de ne pas coder : une ou deux semaines de MVP concierge peuvent vous éviter des semaines de développement inutile. Utilisez Bolt.new comme outil d'esquisse pour tester des parcours, sans vous sentir obligé d'en garder le code. Trajectoire : B dès que la demande est confirmée, en gardant n8n pour les automatisations périphériques.","personas":["tech"]},{"id":"crs_mvp_ia_m03_l03_b_6","type":"texte","markdown":"## Votre point de départ recommandé : C, puis A, en apprenant au passage\n\nLa stack C vous permet de démarrer sans bloquer sur la technique, tout en rencontrant vos premiers utilisateurs. Profitez-en pour vous familiariser avec les notions de tables, de champs et d'automatisations : ce sont exactement celles que vous retrouverez dans Supabase. Passez ensuite à la stack A. Si vous visez un métier du numérique, la stack B est une excellente trajectoire d'apprentissage : vous la découvrirez progressivement au module 6, avec l'aide des agents de code.","personas":["reconversion"]},{"id":"crs_mvp_ia_m03_l03_b_7","type":"checklist","title":"Ma stack de départ est adaptée si…","items":[{"id":"crs_mvp_ia_m03_l03_b_7_i_1","label":"Je peux la mettre en place avant la date prévue de mes premiers tests utilisateurs."},{"id":"crs_mvp_ia_m03_l03_b_7_i_2","label":"Au moins une personne de l'équipe sait la faire évoluer."},{"id":"crs_mvp_ia_m03_l03_b_7_i_3","label":"Elle me permet de tester mon hypothèse principale."},{"id":"crs_mvp_ia_m03_l03_b_7_i_4","label":"Je peux récupérer mon code et mes données."},{"id":"crs_mvp_ia_m03_l03_b_7_i_5","label":"Je sais où sont hébergées les données personnelles de mes utilisateurs."},{"id":"crs_mvp_ia_m03_l03_b_7_i_6","label":"Je connais l'étape suivante de ma trajectoire, et le signal qui la déclenchera."}]},{"id":"crs_mvp_ia_m03_l03_b_8","type":"exercice","title":"Votre projet dans chacune des trois stacks","instructions":"1. Pour chacune des trois stacks, décrivez en 5 à 8 lignes le parcours de votre projet, sur le modèle de Créno : pages ou écrans, emplacement des données, ce qui est automatisé, ce qui reste manuel.\n2. Pour chaque stack, identifiez la limite qui vous gênerait le plus, et à quel moment elle apparaîtrait.\n3. Indiquez la stack de départ qui vous semble la plus adaptée et la trajectoire envisagée : étape suivante et signal mesurable qui la déclenche (par exemple, pour Créno : « vingt réservations payées en un mois »).\n\nLivrable (texte) : les trois parcours, les limites et votre recommandation. Vous la consoliderez dans la fiche stack de la leçon 5.","deliverable":"texte","estimatedMinutes":35,"review":"auto","rubric":["Les trois parcours sont décrits concrètement pour le projet","Les limites identifiées sont spécifiques au projet, pas génériques","La stack de départ est cohérente avec le profil et l'hypothèse à valider","La trajectoire comporte un signal de passage mesurable"]}]$q$::jsonb)
on conflict (id) do nothing;

insert into crm.academy_lessons (id, course_id, module_id, position, title, summary, estimated_minutes, is_preview, blocks)
values ($q$crs_mvp_ia_m03_l04$q$, $q$crs_mvp_ia$q$, $q$crs_mvp_ia_m03$q$, 3, $q$Estimer les coûts et les limites$q$, $q$Coûts fixes, coûts à l'usage et coûts cachés : une méthode pour construire votre tableau de coûts à partir des pages tarifs officielles.$q$, 35, false, $q$[{"id":"crs_mvp_ia_m03_l04_b_1","type":"texte","markdown":"À la fin de cette leçon, vous saurez construire le tableau de coûts de votre stack à partir des pages tarifs officielles, en anticipant les coûts qui augmentent avec l'usage et ceux que l'on oublie.\n\n> [!info] Cette leçon ne donne volontairement aucun prix : tarifs et offres changent souvent. Vous apprenez une méthode, et vous relevez les chiffres vous-même, à la date de votre décision.\n\n## Trois natures de coûts\n\n### Les coûts fixes : offres et paliers\nLa plupart des outils fonctionnent par **paliers** : une offre gratuite limitée, puis des offres payantes, souvent mensuelles, avec des limites plus élevées et des fonctions supplémentaires (collaboration, sauvegardes, assistance). Le passage au palier supérieur est généralement déclenché par une limite : nombre d'utilisateurs, de projets, de lignes de données, d'exécutions.\n\n### Les coûts à l'usage\nIls varient avec l'activité de votre produit :\n\n- **Appels à un modèle d'IA** : si votre produit utilise un modèle (Claude, ou les modèles d'OpenAI, par exemple) via une **API** (une interface qui permet à un programme d'utiliser un service), la facturation dépend du volume de texte traité, mesuré en tokens : en entrée (ce que vous envoyez) et en sortie (ce que le modèle génère). Le tarif varie selon le modèle choisi.\n- **Stockage et transfert** : volume de la base de données, fichiers stockés (photos de profil, documents), données transférées.\n- **E-mails et SMS** : les services d'envoi facturent généralement au-delà d'un volume inclus.\n- **Paiements** : les prestataires de paiement prélèvent généralement une commission sur chaque transaction.\n- **Automatisations et fonctions serveur** : nombre d'exécutions, temps de calcul.\n- **Outils de construction assistée par IA** : l'usage des générateurs et des agents de code est souvent encadré par des quotas ou des crédits, selon l'offre.\n\nPour Créno, chaque réservation peut déclencher : une écriture en base, un paiement (et sa commission), un e-mail de confirmation, une exécution n8n et un e-mail de rappel. Multiplié par le nombre de réservations attendues, cela donne une première idée du coût à l'usage.\n\n### Les coûts cachés\n- **Votre temps** : apprentissage, construction, support aux utilisateurs, tâches manuelles (surtout dans un MVP concierge).\n- **La maintenance** : mises à jour, corrections, surveillance, sauvegardes.\n- **Les coûts de sortie** : migrer vers un autre outil quand le premier ne suffit plus.\n- **Les à-côtés** : nom de domaine, adresse e-mail professionnelle, outils de conception, conseil juridique ou comptable."},{"id":"crs_mvp_ia_m03_l04_b_2","type":"texte","markdown":"## Lire une page tarifs avec méthode\n\nLes pages tarifs sont conçues pour vendre : lisez-les avec une grille. Pour chaque outil, cherchez :\n\n1. **ce qu'inclut l'offre gratuite**, et ses limites exactes (volumes, nombre de projets, fonctions exclues) ;\n2. **ce qui se passe quand une limite est atteinte** : blocage, mise en pause, facturation du dépassement ;\n3. **les conditions d'usage** : l'offre autorise-t-elle un usage commercial ? Les projets inactifs peuvent-ils être suspendus ?\n4. **le mode de facturation** : par utilisateur, par projet, à l'usage, mensuel ou annuel, avec ou sans engagement ;\n5. **les garde-fous** : peut-on fixer un plafond de dépenses ou recevoir des alertes ?\n6. **la conformité** : région d'hébergement, et existence d'un accord de traitement des données (le contrat qui encadre, au sens du RGPD, ce que le prestataire fait de vos données).\n\nNotez la **date de consultation** à côté de chaque information : dans quelques mois, elle aura peut-être changé.\n\n## Construire son tableau de coûts\n\n1. Listez tous les outils et services de votre stack, y compris ceux de pilotage (Notion, GitHub) et de construction (Bolt.new, Cursor, Claude Code, Codex…).\n2. Définissez **trois scénarios d'usage** : test (vos premiers utilisateurs), lancement, succès. Exprimez-les en unités concrètes : utilisateurs, réservations par mois, e-mails, appels à l'IA.\n3. Pour chaque outil, relevez sur la page tarifs l'offre nécessaire dans chaque scénario.\n4. Ajoutez les coûts à l'usage, calculés à partir de vos unités.\n5. Ajoutez une ligne « temps » (heures par mois) et une ligne « imprévus ».\n6. Repérez les **seuils** : à partir de quel volume passez-vous au palier supérieur ?\n\n| Outil ou service | Rôle | Offre (test) | Offre (lancement) | Offre (succès) | Coûts à l'usage | Seuil de changement de palier | Source et date |\n| --- | --- | --- | --- | --- | --- | --- | --- |\n| Supabase | Base, authentification | À relever | À relever | À relever | Stockage, transfert | À relever | Page tarifs, date |\n| n8n | Rappels | À relever | À relever | À relever | Exécutions | À relever | Page tarifs, date |\n| … | … | … | … | … | … | … | … |\n\nCe tableau alimente votre modèle financier et vos décisions de stack : un seuil proche de votre scénario de lancement est un risque à anticiper."},{"id":"crs_mvp_ia_m03_l04_b_3","type":"ressource","resourceId":"res_modele_financier","note":"Reportez les coûts de votre scénario « lancement » dans les charges du modèle financier : vous y reviendrez lors de la préparation de votre lancement et de votre pitch."},{"id":"crs_mvp_ia_m03_l04_b_4","type":"prompt","title":"Préparer la lecture des pages tarifs","tool":"Tout assistant IA","prompt":"Voici la stack envisagée pour mon MVP : [LISTE DES OUTILS ET DE LEUR RÔLE].\nMes scénarios d'usage : [TEST], [LANCEMENT], [SUCCÈS] (utilisateurs, actions par mois, e-mails, appels à l'IA…).\n\nPour chaque outil :\n1. Liste les unités de facturation probables à vérifier (par utilisateur, par projet, à l'usage…).\n2. Liste les questions précises à me poser en lisant sa page tarifs officielle : limites de l'offre gratuite, dépassements, usage commercial, plafond de dépenses, région d'hébergement.\n3. Indique les coûts à l'usage que mes scénarios risquent de déclencher.\n\nN'indique aucun prix ni aucun nom d'offre : tes informations peuvent être dépassées. Je relèverai moi-même les tarifs sur les sites officiels.","tips":"Utilisez les questions obtenues comme grille de lecture, page tarifs par page tarifs. Si l'assistant cite malgré tout des chiffres, ignorez-les."},{"id":"crs_mvp_ia_m03_l04_b_5","type":"texte","markdown":"## Profil technique : estimer le coût d'une fonction d'IA\n\nSi votre produit appelle un modèle, estimez le coût par action utilisateur : nombre moyen de tokens envoyés (consignes, contexte, données) et générés, multiplié par le tarif du modèle choisi, multiplié par le nombre d'actions par mois. Mesurez ensuite le réel : l'estimation initiale reste approximative, et les éditeurs fournissent en général un suivi de consommation. Leviers : un modèle plus léger pour les tâches simples, des consignes plus courtes, la mise en cache quand l'éditeur la propose, des limites par utilisateur. Configurez plafonds ou alertes de dépenses dès la création de la clé d'API, et gardez cette clé côté serveur.","personas":["tech"]},{"id":"crs_mvp_ia_m03_l04_b_6","type":"texte","markdown":"## Votre temps a une valeur\n\nAu démarrage, on a tendance à ne compter que ce que l'on paie. Pourtant, une stack gratuite qui vous impose de longues manipulations manuelles chaque semaine coûte cher en temps : celui que vous ne passez pas avec vos clients. Estimez vos heures mensuelles dans chaque scénario et donnez-leur une valeur, par exemple le tarif horaire que vous factureriez à un client. Le bon choix n'est pas toujours le moins cher sur la facture.","personas":["non_tech","reconversion"]},{"id":"crs_mvp_ia_m03_l04_b_7","type":"checklist","title":"Vérifier une page tarifs","items":[{"id":"crs_mvp_ia_m03_l04_b_7_i_1","label":"J'ai noté ce qu'inclut l'offre gratuite et ses limites."},{"id":"crs_mvp_ia_m03_l04_b_7_i_2","label":"Je sais ce qui se passe quand une limite est atteinte."},{"id":"crs_mvp_ia_m03_l04_b_7_i_3","label":"J'ai vérifié que l'usage commercial est autorisé dans l'offre retenue."},{"id":"crs_mvp_ia_m03_l04_b_7_i_4","label":"J'ai identifié les coûts à l'usage et leur unité de facturation."},{"id":"crs_mvp_ia_m03_l04_b_7_i_5","label":"J'ai cherché s'il existe un plafond de dépenses ou des alertes."},{"id":"crs_mvp_ia_m03_l04_b_7_i_6","label":"J'ai noté la région d'hébergement et l'existence d'un accord de traitement des données."},{"id":"crs_mvp_ia_m03_l04_b_7_i_7","label":"J'ai noté l'adresse de la page et la date de consultation."}]},{"id":"crs_mvp_ia_m03_l04_b_8","type":"exercice","title":"Votre tableau de coûts","instructions":"1. Reprenez la stack que vous envisagez (leçon 3).\n2. Définissez vos trois scénarios d'usage en unités concrètes.\n3. Construisez le tableau de coûts sur le modèle ci-dessus, dans un tableur, en relevant chaque information sur la page tarifs officielle, avec l'adresse et la date de consultation.\n4. Ajoutez une ligne « temps » et une ligne « imprévus ».\n5. Surlignez les trois seuils les plus proches de votre scénario de lancement.\n\nLivrable (fichier) : votre tableau, au format tableur ou PDF.","deliverable":"fichier","estimatedMinutes":25,"review":"auto","rubric":["Tous les outils de la stack figurent, y compris pilotage et construction","Les trois scénarios sont exprimés en unités concrètes","Chaque information tarifaire est sourcée et datée","Coûts à l'usage, temps et seuils sont identifiés"]}]$q$::jsonb)
on conflict (id) do nothing;

insert into crm.academy_lessons (id, course_id, module_id, position, title, summary, estimated_minutes, is_preview, blocks)
values ($q$crs_mvp_ia_m03_l05$q$, $q$crs_mvp_ia$q$, $q$crs_mvp_ia_m03$q$, 4, $q$Atelier : choisir et justifier sa stack$q$, $q$Rédiger la fiche stack de votre MVP : outils retenus, justifications, coûts, données, portabilité, trajectoire et risques.$q$, 40, false, $q$[{"id":"crs_mvp_ia_m03_l05_b_1","type":"texte","markdown":"À la fin de cet atelier, vous aurez rédigé la fiche stack de votre MVP : un document court qui présente vos outils, justifie vos choix et prévoit leur évolution. Relue par votre formateur, elle servira de référence aux modules 4 à 6.\n\n## Ce que contient une fiche stack\n\n1. **Contexte** : le projet en deux lignes, l'hypothèse principale à valider, le profil de l'équipe, le délai.\n2. **Stack retenue** : un tableau brique / outil / rôle / justification.\n3. **Options écartées** : ce que vous n'avez pas retenu, et pourquoi, en une ligne chacune.\n4. **Matrice de décision** : la version finale de votre matrice pondérée (leçon 2).\n5. **Coûts et limites** : le résumé de votre tableau de coûts (leçon 4) et les seuils à surveiller.\n6. **Données et conformité** : quelles données personnelles, où elles sont hébergées, comment vous les protégez.\n7. **Portabilité** : comment vous récupérez votre code et vos données.\n8. **Trajectoire** : la prochaine évolution de la stack et le signal qui la déclenchera.\n9. **Risques** : les trois principaux risques et la parade prévue.\n\n## Exemple : la fiche stack de Créno (extraits)\n\nQuelques semaines ont passé. Le MVP concierge a montré que plusieurs coachs utilisent le service chaque semaine, et un associé développeur a rejoint le projet à temps partiel. La fiche stack est mise à jour pour la version applicative.\n\n**Contexte.** Réservation et paiement de séances pour coachs sportifs indépendants. Hypothèse : les coachs testeurs et leurs clients adoptent la réservation avec paiement en ligne. Équipe : une fondatrice non technique, un associé développeur à temps partiel. Ouverture aux coachs testeurs prévue dans six semaines.\n\n| Brique | Outil | Rôle | Justification |\n| --- | --- | --- | --- |\n| Interface et logique | Next.js + React | Pages coach et client | Maîtrisés par l'associé, très répandus, bien connus des outils d'IA |\n| Base, authentification, sécurité | Supabase | Profils, créneaux, réservations, paiements ; règles RLS | Postgres standard (portabilité), sécurité au niveau des données |\n| Paiement | Stripe | Paiement à la réservation | Intégration documentée, aucune donnée bancaire stockée par Créno |\n| Automatisation | n8n | Rappel la veille | La fondatrice peut modifier les workflows sans coder |\n| Hébergement | Vercel | Publication, prévisualisations | Intégration directe avec GitHub et Next.js |\n| Construction | Claude Code, Cursor | Écriture du code | Plan, petites étapes, tests, relecture des diffs |\n| Pilotage | Notion, GitHub | PRD, backlog, code | Déjà en place depuis le module 1 |\n\n**Option écartée.** Stack A (Bolt.new + Supabase) : rapide, mais l'associé préfère structurer le code dès le départ. Bolt.new reste utilisé pour esquisser des écrans avant de les coder.\n\n**Trajectoire.** Si au moins la moitié des coachs testeurs utilisent Créno chaque semaine après un mois, ajout de l'annulation en libre-service et des statistiques du coach. Sinon, entretiens pour comprendre les freins avant tout nouveau développement.\n\n**Risques.** Règles RLS mal écrites (parade : tests d'accès systématiques, relecture au module 4) ; dépendance à l'associé (parade : fichier de contexte et documentation à jour) ; commissions de paiement mal anticipées (parade : intégration au modèle financier).\n\n## Les erreurs fréquentes\n\n- **La liste d'outils sans justification** : « Supabase, Vercel, n8n » ne dit rien de vos besoins ni de vos contraintes.\n- **La stack choisie pour impressionner** : une architecture complexe pour un MVP qui doit d'abord trouver ses utilisateurs.\n- **L'oubli des briques invisibles** : e-mails de confirmation, sauvegardes, gestion des clés secrètes.\n- **La trajectoire sans signal** : « on changera plus tard » n'est pas une trajectoire ; précisez quand, et sur quel constat.\n\n> [!tip] Une bonne fiche stack tient sur une à deux pages. Si la vôtre est plus longue, vous êtes probablement en train de concevoir l'architecture détaillée : c'est l'objet du module 4."},{"id":"crs_mvp_ia_m03_l05_b_2","type":"ressource","resourceId":"res_stack_nocode","note":"Le guide des outils no-code & IA récapitule les outils de ce module : appuyez-vous dessus pour compléter les colonnes « rôle » et « justification » de votre fiche."},{"id":"crs_mvp_ia_m03_l05_b_3","type":"prompt","title":"Faire challenger sa fiche stack","tool":"Claude","prompt":"Tu es un directeur technique expérimenté qui accompagne des fondateurs de startups en phase de MVP. Voici la fiche stack de mon projet :\n\n<fiche>\n[COLLEZ VOTRE FICHE STACK]\n</fiche>\n\nRelis-la de façon critique :\n1. Les choix sont-ils cohérents avec l'hypothèse à valider, le délai et les compétences de l'équipe ?\n2. Manque-t-il une brique (authentification, e-mails, paiement, sauvegardes…) ?\n3. Les risques de sécurité et de conformité des données sont-ils traités ?\n4. La portabilité (récupération du code et des données) est-elle réelle ?\n5. La trajectoire a-t-elle un signal de passage mesurable ?\n\nTermine par les trois améliorations prioritaires. Ne cite aucun prix, et signale les points à vérifier dans la documentation officielle des outils.","tips":"Fonctionne aussi avec ChatGPT. Gardez votre jugement : intégrez les remarques pertinentes, et notez celles que vous écartez, avec la raison."},{"id":"crs_mvp_ia_m03_l05_b_4","type":"texte","markdown":"## Profil non technique : une fiche qui servira de brief\n\nSi un développeur ou un prestataire vous rejoint, votre fiche stack sera le premier document qu'il lira. Rédigez les justifications avec vos mots, mais soyez précis sur les besoins : « le coach doit pouvoir modifier ses créneaux depuis son téléphone » est plus utile que « application moderne ». Indiquez aussi ce que vous voulez pouvoir faire seul après la livraison : modifier un texte, un workflow, un prix.","personas":["non_tech"]},{"id":"crs_mvp_ia_m03_l05_b_5","type":"texte","markdown":"## Profil technique : ajoutez les décisions structurantes\n\nComplétez la fiche par une courte section « décisions d'architecture » : où vit la logique métier (base ou code applicatif), stratégie d'authentification, gestion des secrets et des environnements (développement, prévisualisation, production), stratégie de tests. Une ligne par décision, avec l'alternative écartée. Vous les détaillerez au module 4, mais les poser maintenant évite qu'un agent de code fasse ces choix implicitement à votre place.","personas":["tech"]},{"id":"crs_mvp_ia_m03_l05_b_6","type":"texte","markdown":"## Si vous doutez de votre choix\n\nC'est normal : aucun choix de stack n'est définitif au stade du MVP. Votre formateur évalue la cohérence de votre raisonnement, pas le prestige des outils. Une stack C bien justifiée vaut mieux qu'une stack B choisie pour impressionner. Notez vos doutes dans la section « risques » : c'est un signe de lucidité, et votre formateur pourra vous aider à les lever.","personas":["reconversion"]},{"id":"crs_mvp_ia_m03_l05_b_7","type":"checklist","title":"Ma fiche stack est prête","items":[{"id":"crs_mvp_ia_m03_l05_b_7_i_1","label":"Chaque brique nécessaire au MVP a un outil et une justification."},{"id":"crs_mvp_ia_m03_l05_b_7_i_2","label":"Le choix est relié à l'hypothèse à valider et au délai."},{"id":"crs_mvp_ia_m03_l05_b_7_i_3","label":"Les options écartées sont mentionnées, avec leur raison."},{"id":"crs_mvp_ia_m03_l05_b_7_i_4","label":"Les coûts et les seuils principaux sont résumés et sourcés."},{"id":"crs_mvp_ia_m03_l05_b_7_i_5","label":"La localisation et la protection des données personnelles sont traitées."},{"id":"crs_mvp_ia_m03_l05_b_7_i_6","label":"La récupération du code et des données est prévue."},{"id":"crs_mvp_ia_m03_l05_b_7_i_7","label":"La trajectoire comporte un signal de passage mesurable."}]},{"id":"crs_mvp_ia_m03_l05_b_8","type":"exercice","title":"Votre fiche stack","instructions":"Rédigez la fiche stack de votre MVP en suivant les neuf rubriques de cette leçon, sur une à deux pages. Appuyez-vous sur vos livrables précédents : cartographie des briques (leçon 1), matrice de décision (leçon 2), parcours dans les trois stacks (leçon 3), tableau de coûts (leçon 4).\n\nAvant de rendre votre fiche :\n\n- faites-la challenger avec le prompt proposé et intégrez les remarques pertinentes ;\n- vérifiez chaque point de la checklist ;\n- relisez-la pour vous assurer qu'elle ne contient aucune donnée personnelle réelle ni aucun secret.\n\nLivrable (texte) : votre fiche stack. Votre formateur vous répondra par des questions et des recommandations ; vous pourrez l'ajuster avant le module 4.","deliverable":"texte","estimatedMinutes":30,"review":"formateur","rubric":["Cohérence entre la stack, l'hypothèse à valider, le délai et les compétences de l'équipe","Justifications concrètes et options écartées explicitées","Coûts, limites et conformité des données traités de façon sourcée","Portabilité et trajectoire d'évolution avec un signal mesurable","Risques identifiés, chacun avec une parade réaliste"]}]$q$::jsonb)
on conflict (id) do nothing;

insert into crm.academy_lessons (id, course_id, module_id, position, title, summary, estimated_minutes, is_preview, blocks)
values ($q$crs_mvp_ia_m03_l06$q$, $q$crs_mvp_ia$q$, $q$crs_mvp_ia_m03$q$, 5, $q$Évaluation du module$q$, $q$Dix questions pour valider vos acquis sur les familles d'outils, les critères de choix, les trois stacks de référence et l'estimation des coûts.$q$, 20, false, $q$[{"id":"crs_mvp_ia_m03_l06_b_1","type":"texte","markdown":"Cette évaluation vérifie que vous savez situer les outils, comparer des options avec méthode, choisir une stack de départ et anticiper ses coûts.\n\n## Consignes\n\n- Dix questions, une seule bonne réponse par question.\n- Plusieurs questions décrivent une situation : raisonnez comme pour votre propre projet.\n- Une explication s'affiche après chaque réponse : lisez-la, même quand vous avez juste.\n- Le score minimal attendu est indiqué dans votre espace. En cas d'échec, relisez les leçons concernées avant de retenter."},{"id":"crs_mvp_ia_m03_l06_b_2","type":"quiz","title":"Évaluation — Choisir sa stack","graded":true,"questions":[{"id":"crs_mvp_ia_m03_l06_b_2_q_1","prompt":"Quel outil de la formation fournit à la fois une base Postgres, l'authentification, le stockage de fichiers et la sécurité par lignes (RLS) ?","kind":"unique","options":[{"id":"crs_mvp_ia_m03_l06_b_2_q_1_o_1","label":"Vercel","correct":false},{"id":"crs_mvp_ia_m03_l06_b_2_q_1_o_2","label":"n8n","correct":false},{"id":"crs_mvp_ia_m03_l06_b_2_q_1_o_3","label":"Supabase","correct":true},{"id":"crs_mvp_ia_m03_l06_b_2_q_1_o_4","label":"Airtable","correct":false}],"explanation":"Supabase est un backend as a service. Vercel héberge, n8n automatise, Airtable est une base no-code de type tableur."},{"id":"crs_mvp_ia_m03_l06_b_2_q_2","prompt":"Qu'est-ce qu'un MVP « concierge » ?","kind":"unique","options":[{"id":"crs_mvp_ia_m03_l06_b_2_q_2_o_1","label":"Une application entièrement automatisée dès le premier jour","correct":false},{"id":"crs_mvp_ia_m03_l06_b_2_q_2_o_2","label":"Un service rendu en grande partie à la main, en coulisses, pour valider la demande avant d'automatiser","correct":true},{"id":"crs_mvp_ia_m03_l06_b_2_q_2_o_3","label":"Une maquette non cliquable présentée à des investisseurs","correct":false},{"id":"crs_mvp_ia_m03_l06_b_2_q_2_o_4","label":"Une application générée par IA sans intervention humaine","correct":false}],"explanation":"Le MVP concierge (par exemple Airtable + n8n + page simple) teste la demande avec un investissement minimal ; l'automatisation vient ensuite."},{"id":"crs_mvp_ia_m03_l06_b_2_q_3","prompt":"Dans votre matrice de décision pondérée, deux options obtiennent le même score. Que faites-vous ?","kind":"unique","options":[{"id":"crs_mvp_ia_m03_l06_b_2_q_3_o_1","label":"Vous modifiez les poids jusqu'à ce que votre option préférée gagne","correct":false},{"id":"crs_mvp_ia_m03_l06_b_2_q_3_o_2","label":"Vous tirez au sort","correct":false},{"id":"crs_mvp_ia_m03_l06_b_2_q_3_o_3","label":"Vous choisissez l'outil le plus populaire du moment","correct":false},{"id":"crs_mvp_ia_m03_l06_b_2_q_3_o_4","label":"Vous départagez selon l'hypothèse à valider en premier : la matrice éclaire, elle ne décide pas","correct":true}],"explanation":"Ajuster les poids après coup est un piège classique. L'hypothèse prioritaire (la demande existe-t-elle ? sait-on construire ?) oriente le choix."},{"id":"crs_mvp_ia_m03_l06_b_2_q_4","prompt":"Que recouvre le critère « dépendance et portabilité » ?","kind":"unique","options":[{"id":"crs_mvp_ia_m03_l06_b_2_q_4_o_1","label":"La capacité à récupérer son code et ses données pour changer d'outil si nécessaire","correct":true},{"id":"crs_mvp_ia_m03_l06_b_2_q_4_o_2","label":"La possibilité d'utiliser l'outil sur un téléphone","correct":false},{"id":"crs_mvp_ia_m03_l06_b_2_q_4_o_3","label":"La vitesse de chargement des pages","correct":false},{"id":"crs_mvp_ia_m03_l06_b_2_q_4_o_4","label":"Le nombre de fonctionnalités de l'outil","correct":false}],"explanation":"Un outil qui permet d'exporter le code (vers GitHub, par exemple) et les données dans des formats standards évite de devoir tout reconstruire."},{"id":"crs_mvp_ia_m03_l06_b_2_q_5","prompt":"Une fondatrice non technique veut vérifier en deux semaines que des clients sont prêts à payer son service. Quelle stack de départ est la plus cohérente ?","kind":"unique","options":[{"id":"crs_mvp_ia_m03_l06_b_2_q_5_o_1","label":"Next.js + Supabase + Vercel, développée seule avec un agent de code","correct":false},{"id":"crs_mvp_ia_m03_l06_b_2_q_5_o_2","label":"Airtable + n8n + une page simple (MVP concierge)","correct":true},{"id":"crs_mvp_ia_m03_l06_b_2_q_5_o_3","label":"Une architecture en microservices","correct":false},{"id":"crs_mvp_ia_m03_l06_b_2_q_5_o_4","label":"Aucune : attendre d'avoir recruté un développeur","correct":false}],"explanation":"Délai très court, profil non technique, hypothèse de demande : le MVP concierge permet de tester vite, sans code, avant d'investir."},{"id":"crs_mvp_ia_m03_l06_b_2_q_6","prompt":"Quel est le principal point de vigilance de la stack Bolt.new + Supabase avant d'ouvrir l'application à de vrais utilisateurs ?","kind":"unique","options":[{"id":"crs_mvp_ia_m03_l06_b_2_q_6_o_1","label":"Il est impossible de récupérer le code","correct":false},{"id":"crs_mvp_ia_m03_l06_b_2_q_6_o_2","label":"Supabase ne permet pas de créer des comptes utilisateurs","correct":false},{"id":"crs_mvp_ia_m03_l06_b_2_q_6_o_3","label":"Vérifier la sécurité (règles RLS, clés) et la structure du code généré","correct":true},{"id":"crs_mvp_ia_m03_l06_b_2_q_6_o_4","label":"L'application ne peut pas s'afficher sur mobile","correct":false}],"explanation":"La génération par IA ne garantit ni la sécurité ni une bonne structure. Les règles d'accès et la gestion des clés doivent être vérifiées."},{"id":"crs_mvp_ia_m03_l06_b_2_q_7","prompt":"Comment l'utilisation d'un modèle d'IA via une API est-elle généralement facturée ?","kind":"unique","options":[{"id":"crs_mvp_ia_m03_l06_b_2_q_7_o_1","label":"Au nombre d'utilisateurs inscrits sur votre application","correct":false},{"id":"crs_mvp_ia_m03_l06_b_2_q_7_o_2","label":"Au volume de texte traité, mesuré en tokens, en entrée et en sortie, selon le modèle choisi","correct":true},{"id":"crs_mvp_ia_m03_l06_b_2_q_7_o_3","label":"Par un forfait unique à vie","correct":false},{"id":"crs_mvp_ia_m03_l06_b_2_q_7_o_4","label":"Au nombre de pages de votre site","correct":false}],"explanation":"Les API de modèles facturent le volume de texte envoyé et généré (tokens) ; le tarif dépend du modèle. Vérifiez toujours la page tarifs officielle."},{"id":"crs_mvp_ia_m03_l06_b_2_q_8","prompt":"Lequel de ces éléments est un coût caché typique d'un MVP ?","kind":"unique","options":[{"id":"crs_mvp_ia_m03_l06_b_2_q_8_o_1","label":"L'abonnement mensuel affiché sur la page tarifs","correct":false},{"id":"crs_mvp_ia_m03_l06_b_2_q_8_o_2","label":"La commission indiquée par le prestataire de paiement","correct":false},{"id":"crs_mvp_ia_m03_l06_b_2_q_8_o_3","label":"Le prix du nom de domaine affiché à l'achat","correct":false},{"id":"crs_mvp_ia_m03_l06_b_2_q_8_o_4","label":"Le temps passé en tâches manuelles et en maintenance","correct":true}],"explanation":"Le temps (apprentissage, gestion manuelle, maintenance, support) ne figure sur aucune facture, mais pèse lourdement sur un projet de MVP."},{"id":"crs_mvp_ia_m03_l06_b_2_q_9","prompt":"Votre MVP stockera les noms et les téléphones de clients. Que vérifiez-vous au titre du critère « données et conformité » ?","kind":"unique","options":[{"id":"crs_mvp_ia_m03_l06_b_2_q_9_o_1","label":"La région d'hébergement, les garanties contractuelles du prestataire et la limitation des données collectées au nécessaire","correct":true},{"id":"crs_mvp_ia_m03_l06_b_2_q_9_o_2","label":"Uniquement la couleur de l'interface","correct":false},{"id":"crs_mvp_ia_m03_l06_b_2_q_9_o_3","label":"Rien : le RGPD ne concerne que les grandes entreprises","correct":false},{"id":"crs_mvp_ia_m03_l06_b_2_q_9_o_4","label":"Uniquement que l'outil soit gratuit","correct":false}],"explanation":"Le RGPD s'applique aussi aux petites structures. Hébergement, contrat de traitement des données et minimisation sont les premiers points à vérifier (sources : cnil.fr)."},{"id":"crs_mvp_ia_m03_l06_b_2_q_10","prompt":"Quel est le rôle de Vercel dans la stack Next.js + React + Supabase + Vercel ?","kind":"unique","options":[{"id":"crs_mvp_ia_m03_l06_b_2_q_10_o_1","label":"Stocker les réservations et gérer les règles RLS","correct":false},{"id":"crs_mvp_ia_m03_l06_b_2_q_10_o_2","label":"Envoyer les rappels la veille des séances","correct":false},{"id":"crs_mvp_ia_m03_l06_b_2_q_10_o_3","label":"Héberger et publier l'application, avec des versions de prévisualisation à chaque modification","correct":true},{"id":"crs_mvp_ia_m03_l06_b_2_q_10_o_4","label":"Rédiger le code à partir des user stories","correct":false}],"explanation":"Vercel se connecte au dépôt GitHub, construit et publie chaque version. Supabase gère les données, n8n les rappels, les agents de code l'écriture."}]}]$q$::jsonb)
on conflict (id) do nothing;

insert into crm.academy_lessons (id, course_id, module_id, position, title, summary, estimated_minutes, is_preview, blocks)
values ($q$crs_mvp_ia_m04_l01$q$, $q$crs_mvp_ia$q$, $q$crs_mvp_ia_m04$q$, 0, $q$Penser en architecture$q$, $q$Découper votre application en quatre couches, suivre le trajet d'une requête et décider ce qui doit rester côté serveur.$q$, 45, false, $q$[{"id":"crs_mvp_ia_m04_l01_b_1","type":"texte","markdown":"**À la fin de cette leçon**, vous saurez décrire votre application en quatre couches, suivre le trajet d'une action utilisateur de l'écran jusqu'à la base de données, et décider ce qui doit impérativement rester côté serveur.\n\n## Pourquoi penser l'architecture avant de générer du code\n\nUn outil d'IA peut produire un écran fonctionnel en quelques minutes. Mais sans plan d'ensemble, les problèmes arrivent vite : données dupliquées dans deux tables, prix calculé dans le navigateur, clé secrète copiée dans du code visible par tous, règles métier dispersées. Chaque correction en provoque une autre.\n\nL'**architecture** est le plan de votre application : ses grandes parties, le rôle de chacune et la façon dont elles communiquent. C'est le plan de l'architecte avant le chantier : on ne décide pas de l'emplacement des canalisations une fois les murs montés. Pour un MVP, ce plan tient sur une page. Il vous sert à prendre de bonnes décisions, à donner du contexte aux outils IA (leçon 6) et à expliquer votre produit à un développeur ou à un investisseur.\n\n## Les quatre couches d'une application web\n\n| Couche | Rôle | Chez Créno | Question à se poser |\n| --- | --- | --- | --- |\n| Front (interface) | Ce que l'utilisateur voit et manipule : pages, boutons, formulaires | Pages Next.js / React : agenda du coach, page de réservation | Que voit et que fait l'utilisateur ? |\n| Back (logique serveur) | Applique les règles métier, vérifie les droits, orchestre les échanges | Code serveur Next.js, réception des notifications de Stripe | Quelles règles doivent être garanties, quoi qu'il arrive ? |\n| Base de données | Stocke les informations durablement | Supabase (Postgres) : profils, créneaux, réservations, paiements | Que doit-on retrouver demain, dans un an ? |\n| Services externes | Spécialistes branchés à votre application | Stripe (paiement), service d'email, n8n (rappels), Supabase Auth (connexion) | Qu'est-ce qu'on ne construit pas soi-même ? |\n\nUne image aide à fixer les idées : le restaurant. La **salle** est le front : le client y lit la carte et commande. La **cuisine** est le back : on y applique les recettes et les règles d'hygiène, et le client n'y entre jamais. La **réserve** est la base de données. Les **fournisseurs** sont les services externes.\n\nTrois mots reviennent sans cesse. Un **serveur** est un ordinateur qui exécute votre code et répond aux demandes. Une **requête** est un message envoyé par un programme à un autre pour demander quelque chose (« donne-moi les créneaux de mardi »). Une **API** (interface de programmation) est l'ensemble des requêtes qu'un service accepte, avec leur format : c'est la carte du restaurant.\n\n## Le trajet d'une requête : le client de Créno réserve un créneau\n\nSuivons Léa, cliente de Julie, coach sportive, qui réserve une séance depuis son téléphone.\n\n1. Léa ouvre le lien de réservation de Julie. Son navigateur demande la page à l'hébergeur (Vercel), qui renvoie l'interface.\n2. La page affiche les créneaux ouverts, lus dans la base Supabase. La base ne renvoie que les lignes que Léa a le droit de voir (leçon 3).\n3. Léa touche « Réserver mardi 18 h ». Le front envoie au back une requête : « je souhaite le créneau n° X ». Il n'envoie pas le prix.\n4. Le back vérifie que Léa est connectée, que le créneau est ouvert et qu'il reste une place. Il lit le prix dans la base.\n5. Le back enregistre une réservation « en attente », crée une session de paiement chez Stripe et redirige Léa vers la page de paiement.\n6. Léa paie. Stripe prévient alors le back par un **webhook** : un message automatique envoyé à une adresse de votre application (« paiement confirmé »).\n7. Le back vérifie l'authenticité du message, passe le paiement à « réussi » et la réservation à « confirmée », puis déclenche l'email de confirmation.\n8. La veille de la séance, un scénario n8n interroge la base, trouve la réservation et envoie le rappel.\n\n> [!tip] Pourquoi le front n'envoie-t-il pas le prix à l'étape 3 ? Parce que tout ce qui part du navigateur peut être modifié par l'utilisateur. Si le back acceptait un prix venu du front, n'importe qui pourrait payer 1 € une séance à 35 €.\n\n## Le schéma textuel de l'architecture de Créno\n\nInutile d'avoir un logiciel de dessin : un schéma en texte suffit. Il se versionne avec le code, se colle dans un prompt et reste lisible par les outils IA.\n\n```text\n[Navigateur du client ou du coach]\n        |  HTTPS\n        v\n[Front : Next.js + React, hébergé sur Vercel]\n        |  actions serveur / routes API\n        v\n[Back : code serveur Next.js] ----> [Stripe : paiement en ligne]\n        |        ^                          |\n        |        +---- webhook « paiement confirmé »\n        v\n[Supabase : base Postgres + Auth + règles RLS]\n        ^\n        |  lecture planifiée chaque soir\n[n8n : rappel la veille] ----> [Service d'email]\n```\n\n## Client ou serveur : ce qui doit rester côté serveur\n\nLe **client** est le navigateur (ou l'application mobile) de l'utilisateur. Tout ce qui s'y trouve est visible et modifiable : le code, les données, les requêtes envoyées. Les outils de développement intégrés à chaque navigateur le montrent en deux clics. Le **serveur** est la machine que vous contrôlez.\n\nDoivent rester côté serveur :\n\n- les clés secrètes (Stripe, clé secrète Supabase, clés d'API des modèles d'IA) ;\n- le calcul des montants, des remises et des remboursements ;\n- la vérification des droits (« ce créneau appartient-il bien à ce coach ? »), en complément des règles de la base ;\n- la confirmation d'un paiement, uniquement à partir du webhook de Stripe, jamais à partir de la page « Merci » affichée dans le navigateur ;\n- l'envoi d'emails et les appels payants à des API, sinon n'importe qui peut les déclencher en boucle.\n\nPeuvent rester côté client : l'affichage, la navigation, l'état de l'interface (un menu ouvert, un onglet actif) et la validation des formulaires pour le confort de l'utilisateur, à condition de la refaire côté serveur.\n\n> [!warning] Règle d'or : le front vérifie pour le confort, le back vérifie pour la sécurité."},{"id":"crs_mvp_ia_m04_l01_b_2","type":"video","title":"Le trajet d'une réservation dans Créno","url":"","durationMinutes":6,"script":"- Ouverture (30 s) : l'application Créno à l'écran, sur mobile. Question posée : « que se passe-t-il vraiment quand Léa touche Réserver ? »\n- Présenter les quatre couches à partir du schéma textuel, en surlignant chaque bloc au fur et à mesure.\n- Dérouler les étapes 1 à 5 : le navigateur, puis le code serveur qui vérifie la session, le statut du créneau et lit le prix en base.\n- Montrer la page de paiement Stripe en mode test, puis l'arrivée du webhook dans les journaux du serveur.\n- Démonstration du risque : modifier une requête dans les outils de développement du navigateur pour changer le prix, et constater que le back l'ignore.\n- Montrer le scénario n8n du rappel de la veille et la colonne qui évite les doubles envois.\n- Conclusion : trois règles à retenir (secrets côté serveur, prix lu en base, paiement confirmé par webhook)."},{"id":"crs_mvp_ia_m04_l01_b_3","type":"texte","markdown":"## Le vocabulaire de l'architecture, sans jargon\n\nVous découvrez ces notions ? Il est normal de se sentir un peu perdu au début. Retenez d'abord ces huit mots : ils reviendront dans tous les modules suivants.\n\n| Terme | En une phrase | Dans Créno |\n| --- | --- | --- |\n| Front-end (front) | La partie visible de l'application | La page où Léa choisit son créneau |\n| Back-end (back) | La partie invisible qui applique les règles | Le code qui vérifie qu'il reste une place |\n| Base de données | Le classeur où tout est rangé durablement | Les tables des créneaux et des réservations |\n| Serveur | Un ordinateur allumé en permanence qui exécute le back | Les serveurs de l'hébergeur Vercel |\n| Requête | Une demande envoyée d'un programme à un autre | « Donne-moi les créneaux de mardi » |\n| API | La liste des demandes qu'un service accepte | L'API de Stripe pour créer un paiement |\n| Webhook | Un message automatique qu'un service vous envoie quand un événement se produit | Stripe signale « paiement confirmé » |\n| Hébergement | Le service qui rend votre application accessible sur Internet | Vercel pour Créno |\n\nVous n'avez pas besoin de savoir programmer ces couches pour les décrire. Votre rôle, à ce stade, est de savoir **qui fait quoi**. C'est exactement ce que vous demanderez ensuite aux outils IA de réaliser, et c'est ce qui vous permettra de vérifier leur travail.","personas":["reconversion"]},{"id":"crs_mvp_ia_m04_l01_b_4","type":"texte","markdown":"## Où sont les couches si vous ne codez pas ?\n\nLes quatre couches existent dans toutes les applications, y compris celles construites sans écrire de code. Seuls les outils changent.\n\n| Couche | Avec Bolt.new + Supabase | En mode « concierge » (Airtable + n8n) |\n| --- | --- | --- |\n| Front | L'application générée par Bolt.new | Une page de réservation simple (formulaire) |\n| Back | Les fonctions serveur de Supabase (Edge Functions) et les règles de la base | Les scénarios n8n qui traitent chaque demande |\n| Base de données | Supabase | Airtable |\n| Services externes | Stripe, service d'email | Stripe (lien de paiement), service d'email |\n\nLe piège fréquent avec les générateurs d'applications : tout mettre dans le front, parce que « ça marche ». Quand vous demandez une fonctionnalité sensible (paiement, calcul de prix, envoi d'email), précisez dans votre prompt : « cette logique doit s'exécuter côté serveur, pas dans le navigateur, et aucune clé secrète ne doit apparaître dans le code du front ».","personas":["non_tech"]},{"id":"crs_mvp_ia_m04_l01_b_5","type":"texte","markdown":"## Pour les profils techniques : où s'exécute chaque morceau dans Next.js\n\n- Les **composants serveur** (par défaut dans l'App Router) lisent les données côté serveur : ni clé ni requête n'apparaissent dans le navigateur.\n- Les **composants client** (directive `\"use client\"`) gèrent l'interactivité. Tout ce qu'ils importent part dans le navigateur : aucune variable secrète ne doit y transiter.\n- Les **actions serveur** et les **routes API** (`route.ts`) sont des points d'entrée publics : la documentation de Next.js rappelle qu'on peut les appeler directement par une requête POST. Vérifiez l'authentification et les droits dans chacune.\n- Côté Supabase, distinguez trois clients : le client navigateur (clé publique, soumis à la RLS), le client serveur qui porte la session de l'utilisateur via les cookies (paquet `@supabase/ssr`, toujours soumis à la RLS) et le client administrateur (clé secrète, qui contourne la RLS), réservé au webhook Stripe et aux tâches planifiées.\n- Faites passer les écritures sensibles (réservation, annulation) par une action serveur plutôt que par un appel direct depuis le navigateur : vous y centralisez validation, contrôle des places et journalisation.","personas":["tech"]},{"id":"crs_mvp_ia_m04_l01_b_6","type":"exercice","title":"Le schéma d'architecture de votre MVP","instructions":"Appliquez la leçon à **votre projet**.\n\n1. Listez les éléments de chacune des quatre couches : front, back, base de données, services externes. Nommez les outils envisagés au module 3, même provisoirement.\n2. Dessinez le schéma textuel de votre architecture sur le modèle de celui de Créno (blocs entre crochets, flèches, nature des échanges).\n3. Choisissez l'action la plus importante de votre MVP, celle qui apporte la valeur. Décrivez son trajet en 6 à 10 étapes numérotées, de l'écran jusqu'à la base et aux services externes.\n4. Listez au moins quatre éléments qui doivent rester côté serveur dans votre projet, en justifiant chacun en une phrase.\n5. Relisez : chaque flèche de votre schéma correspond-elle à une étape de votre trajet ? Chaque étape à une flèche ?\n\nExemple attendu pour Créno (étape 3 du trajet) : « Le front envoie l'identifiant du créneau choisi, sans le prix. Le back relit le prix en base. »","deliverable":"texte","estimatedMinutes":25,"review":"auto","rubric":["Les quatre couches sont renseignées, avec des outils identifiés.","Le schéma textuel est lisible et cohérent avec le trajet décrit.","Le trajet de l'action clé comporte 6 à 10 étapes précises, du clic à la confirmation.","Les éléments à garder côté serveur sont justifiés (secrets, calculs, droits, paiements)."]},{"id":"crs_mvp_ia_m04_l01_b_7","type":"quiz","title":"Vérifiez vos acquis","graded":false,"questions":[{"id":"crs_mvp_ia_m04_l01_b_7_q_1","prompt":"Dans Créno, qui détermine le montant que Léa va payer ?","kind":"unique","options":[{"id":"crs_mvp_ia_m04_l01_b_7_q_1_o_1","label":"Le front, qui l'affiche et l'envoie au back","correct":false},{"id":"crs_mvp_ia_m04_l01_b_7_q_1_o_2","label":"Le back, à partir du prix enregistré en base","correct":true},{"id":"crs_mvp_ia_m04_l01_b_7_q_1_o_3","label":"Stripe, qui le devine à partir du créneau","correct":false},{"id":"crs_mvp_ia_m04_l01_b_7_q_1_o_4","label":"Léa, qui le saisit dans un champ","correct":false}],"explanation":"Tout ce qui vient du navigateur peut être modifié. Le back relit le prix dans la base avant de créer le paiement."},{"id":"crs_mvp_ia_m04_l01_b_7_q_2","prompt":"Comment l'application sait-elle de façon fiable qu'un paiement a réussi ?","kind":"unique","options":[{"id":"crs_mvp_ia_m04_l01_b_7_q_2_o_1","label":"Quand Léa arrive sur la page « Merci »","correct":false},{"id":"crs_mvp_ia_m04_l01_b_7_q_2_o_2","label":"Quand Léa clique sur « Payer »","correct":false},{"id":"crs_mvp_ia_m04_l01_b_7_q_2_o_3","label":"Grâce au webhook envoyé par Stripe et vérifié par le back","correct":true},{"id":"crs_mvp_ia_m04_l01_b_7_q_2_o_4","label":"Grâce à un email envoyé par Léa","correct":false}],"explanation":"La page « Merci » peut ne jamais s'afficher (onglet fermé) ou être ouverte sans paiement. Seul le webhook signé est une source fiable."},{"id":"crs_mvp_ia_m04_l01_b_7_q_3","prompt":"Laquelle de ces tâches peut s'exécuter côté client ?","kind":"unique","options":[{"id":"crs_mvp_ia_m04_l01_b_7_q_3_o_1","label":"Appeler l'API de Stripe avec la clé secrète","correct":false},{"id":"crs_mvp_ia_m04_l01_b_7_q_3_o_2","label":"Afficher un message si l'email saisi est mal formé","correct":true},{"id":"crs_mvp_ia_m04_l01_b_7_q_3_o_3","label":"Calculer une remise de fidélité","correct":false},{"id":"crs_mvp_ia_m04_l01_b_7_q_3_o_4","label":"Confirmer une réservation","correct":false}],"explanation":"La validation de confort peut se faire dans le navigateur, à condition d'être refaite côté serveur. Les secrets, calculs et confirmations restent côté serveur."},{"id":"crs_mvp_ia_m04_l01_b_7_q_4","prompt":"Dans l'analogie du restaurant, à quoi correspond la base de données ?","kind":"unique","options":[{"id":"crs_mvp_ia_m04_l01_b_7_q_4_o_1","label":"À la salle","correct":false},{"id":"crs_mvp_ia_m04_l01_b_7_q_4_o_2","label":"À la cuisine","correct":false},{"id":"crs_mvp_ia_m04_l01_b_7_q_4_o_3","label":"À la réserve","correct":true},{"id":"crs_mvp_ia_m04_l01_b_7_q_4_o_4","label":"Aux fournisseurs","correct":false}],"explanation":"La salle est le front, la cuisine le back, la réserve la base de données, les fournisseurs les services externes."}]}]$q$::jsonb)
on conflict (id) do nothing;

insert into crm.academy_lessons (id, course_id, module_id, position, title, summary, estimated_minutes, is_preview, blocks)
values ($q$crs_mvp_ia_m04_l02$q$, $q$crs_mvp_ia$q$, $q$crs_mvp_ia_m04$q$, 1, $q$Modéliser ses données$q$, $q$Transformer les « choses » que gère votre produit en tables, colonnes, relations et contraintes, puis les écrire en SQL pour Supabase ou les construire dans Airtable.$q$, 80, false, $q$[{"id":"crs_mvp_ia_m04_l02_b_1","type":"texte","markdown":"**À la fin de cette leçon**, vous saurez construire le modèle de données de votre MVP (tables, colonnes, relations, contraintes) et l'écrire en SQL pour Supabase ou le reproduire dans Airtable.\n\n## Le vocabulaire du modèle de données\n\nUn **modèle de données** décrit ce que votre application mémorise et comment ces informations sont reliées. Cinq notions suffisent pour commencer.\n\n- **Entité** : une « chose » que l'application gère (un créneau, une réservation). Chaque entité devient une **table**.\n- **Attribut** : une caractéristique de l'entité (l'heure de début d'un créneau). Chaque attribut devient une **colonne** ; chaque élément enregistré est une **ligne**.\n- **Type** : la nature de la valeur : texte (`text`), nombre entier (`integer`), vrai / faux (`boolean`), date et heure (`timestamptz`), identifiant unique (`uuid`).\n- **Identifiant** (ou clé primaire) : une valeur unique et stable qui désigne une ligne. Utilisez un identifiant technique, jamais un nom ou un email, qui peuvent changer ou se répéter.\n- **Relation** : un lien entre deux tables, matérialisé par une **clé étrangère**, une colonne qui contient l'identifiant d'une ligne d'une autre table (`coach_id` dans la table des créneaux).\n\nMéthode pratique : relisez vos user stories du module 1. Les **noms** récurrents (coach, créneau, réservation) sont vos entités candidates ; les **compléments** (« un créneau d'une heure à 35 € ») sont vos attributs.\n\n## Les relations : 1-n et n-n\n\n**Un à plusieurs (1-n).** Un coach publie plusieurs créneaux ; un créneau appartient à un seul coach. La clé étrangère se place du côté « plusieurs » : la table des créneaux contient `coach_id`.\n\n**Plusieurs à plusieurs (n-n).** Un client réserve plusieurs créneaux ; un créneau collectif accueille plusieurs clients. Aucune colonne ne peut porter ce lien seule : on crée une **table de liaison**. Chez Créno, c'est la table des réservations : chaque ligne relie un client à un créneau, et porte ses propres informations (statut, annulation, rappel envoyé).\n\n## Les contraintes : laisser la base protéger vos données\n\nUne **contrainte** est une règle que la base refuse de violer, quel que soit le programme qui écrit : votre front, un scénario n8n ou du code généré par l'IA.\n\n- `not null` : valeur obligatoire (un créneau a toujours une heure de début) ;\n- `unique` : pas de doublon (un client ne réserve pas deux fois le même créneau) ;\n- `check` : condition à respecter (la fin après le début, un statut dans une liste fermée) ;\n- `references` : la clé étrangère pointe vers une ligne existante ;\n- `default` : valeur par défaut (statut « en attente », date de création).\n\n## Dates et montants : deux pièges classiques\n\n**Les montants en centimes.** Les ordinateurs représentent mal certains nombres à virgule : en JavaScript, `0.1 + 0.2` donne `0.30000000000000004`. Stockez les montants en **centimes**, sous forme d'entier (3500 pour 35,00 €), avec la devise. Stripe utilise lui aussi la plus petite unité de la devise.\n\n**Les dates avec fuseau horaire.** Utilisez `timestamptz` : Postgres enregistre un instant précis (en temps universel, UTC) et le convertit à l'affichage. Une séance à 18 h à Paris correspond à 16 h UTC en été et à 17 h UTC en hiver : stockez « 18:00 » sans fuseau, et vos rappels seront décalés d'une heure une partie de l'année. Enregistrez aussi le fuseau d'affichage de chaque utilisateur.\n\n## Le modèle de Créno en tableau\n\n| Table | Colonnes principales | Relations | Contraintes clés |\n| --- | --- | --- | --- |\n| `profiles` (profils) | id, role, full_name, phone, timezone | 1-1 avec le compte de connexion | rôle « coach » ou « client » |\n| `slots` (créneaux) | id, coach_id, starts_at, ends_at, price_cents, capacity, status | n-1 vers profiles (le coach) | fin après début, prix positif ou nul |\n| `bookings` (réservations) | id, slot_id, client_id, status, reminder_sent_at, cancelled_at | table de liaison clients / créneaux | une seule réservation par client et par créneau |\n| `payments` (paiements) | id, booking_id, amount_cents, currency, status, provider_payment_id, paid_at | n-1 vers bookings | identifiant Stripe unique |\n\nLes noms sont en anglais, au pluriel, en minuscules séparées par des tirets bas (`snake_case`). C'est une convention courante, que les outils IA suivent spontanément ; l'important est de la choisir et de s'y tenir.\n\n## Le même modèle en SQL (Supabase / Postgres)\n\nLe **SQL** est le langage standard des bases de données relationnelles. Voici le modèle de Créno, à exécuter dans l'éditeur SQL de Supabase ou à placer dans une migration.\n\n```sql\n-- Profils : un par compte (le compte lui-même est géré par Supabase Auth)\ncreate table public.profiles (\n  id uuid primary key references auth.users (id) on delete cascade,\n  role text not null check (role in ('coach', 'client')),\n  full_name text not null,\n  phone text,                                     -- facultatif (minimisation)\n  timezone text not null default 'Europe/Paris',  -- fuseau d'affichage\n  created_at timestamptz not null default now()\n);\n\n-- Créneaux publiés par un coach\ncreate table public.slots (\n  id uuid primary key default gen_random_uuid(),\n  coach_id uuid not null references public.profiles (id),\n  starts_at timestamptz not null,\n  ends_at timestamptz not null,\n  price_cents integer not null check (price_cents >= 0),  -- 3500 = 35,00 €\n  capacity integer not null default 1 check (capacity >= 1),\n  status text not null default 'open' check (status in ('open', 'cancelled')),\n  created_at timestamptz not null default now(),\n  check (ends_at > starts_at)\n);\n\n-- Réservations : table de liaison entre clients et créneaux\ncreate table public.bookings (\n  id uuid primary key default gen_random_uuid(),\n  slot_id uuid not null references public.slots (id),\n  client_id uuid not null references public.profiles (id),\n  status text not null default 'pending'\n    check (status in ('pending', 'confirmed', 'cancelled')),\n  reminder_sent_at timestamptz,  -- rempli par n8n : évite les doubles rappels\n  cancelled_at timestamptz,\n  created_at timestamptz not null default now(),\n  unique (slot_id, client_id)\n);\n\n-- Paiements : une réservation peut connaître plusieurs tentatives\ncreate table public.payments (\n  id uuid primary key default gen_random_uuid(),\n  booking_id uuid not null references public.bookings (id),\n  amount_cents integer not null check (amount_cents > 0),\n  currency text not null default 'eur',\n  status text not null default 'pending'\n    check (status in ('pending', 'succeeded', 'failed', 'refunded')),\n  provider_payment_id text unique,  -- identifiant Stripe\n  paid_at timestamptz,\n  created_at timestamptz not null default now()\n);\n\ncreate index on public.slots (coach_id, starts_at);\ncreate index on public.bookings (client_id);\n```\n\nDeux choix à remarquer. Par défaut, la base refuse de supprimer une ligne encore référencée : on **annule** un créneau (`status`) au lieu de le supprimer, et l'historique des paiements est préservé. Et le nombre de places restantes se contrôle dans le back au moment de réserver : une simple contrainte ne suffit pas.\n\n## L'équivalent dans Airtable\n\nPour un MVP « concierge », créez quatre tables : Profils, Créneaux, Réservations, Paiements. Les relations deviennent des champs **« lien vers un autre enregistrement »** ; les champs **recherche** (lookup) affichent une information de la table liée, les champs **cumul** (rollup) calculent à partir des liens, par exemple le nombre de réservations confirmées d'un créneau. Airtable accepte un lien direct n-n entre clients et créneaux, mais gardez une vraie table Réservations : c'est elle qui porte le statut et le paiement."},{"id":"crs_mvp_ia_m04_l02_b_2","type":"texte","markdown":"## Si vous débutez : un modèle de données, c'est un classeur bien rangé\n\nImaginez un classeur de tableur. Chaque **onglet** est une table (Créneaux, Réservations). Chaque **colonne** est un attribut (date, prix). Chaque **ligne** est un élément (le créneau de mardi 18 h). L'**identifiant** fonctionne comme un numéro de dossier : il ne change jamais, même si le client change d'email.\n\nLa différence avec un tableur ordinaire : la base de données **refuse** les erreurs que vous lui avez interdites (un prix négatif, un créneau sans date). C'est un filet de sécurité précieux quand plusieurs outils écrivent dans les mêmes tables.\n\nLe SQL vous impressionne ? Lisez-le comme une phrase : `create table public.slots` signifie « crée la table des créneaux » ; `price_cents integer not null` signifie « le prix en centimes est un nombre entier obligatoire ». Vous n'avez pas à l'écrire de mémoire. Vous devez être capable de le **relire** et de vérifier qu'il correspond à votre tableau.","personas":["reconversion"]},{"id":"crs_mvp_ia_m04_l02_b_3","type":"texte","markdown":"## Pour les profils non techniques : construire le modèle sans écrire de SQL\n\n- **Avec Bolt.new + Supabase.** Collez votre tableau dans le prompt et demandez : « Crée les tables Supabase correspondant exactement à ce modèle, avec les contraintes indiquées, les montants en centimes et les dates avec fuseau horaire. Montre-moi le SQL et explique chaque table avant de l'appliquer. » Relisez ensuite le SQL avec le tableau de cette leçon : noms de tables, colonnes obligatoires, statuts autorisés.\n- **Avec Airtable.** Créez d'abord les quatre tables, puis les champs simples, puis les liens. Utilisez un champ « sélection unique » pour les statuts et un champ devise pour les montants, et vérifiez l'option de fuseau horaire des champs date. Donnez au premier champ de chaque table (le champ principal) une valeur lisible : par exemple une formule qui assemble la date et le nom du coach pour un créneau.\n\nDans les deux cas, une règle : une information n'est saisie qu'à un seul endroit. Si le nom du coach apparaît dans la table des créneaux, il doit venir d'un lien, pas d'une recopie.","personas":["non_tech"]},{"id":"crs_mvp_ia_m04_l02_b_4","type":"texte","markdown":"## Pour les profils techniques : aller plus loin avec Postgres\n\n- **Migrations.** Une fois le projet lancé, ne modifiez plus le schéma à la main : créez des migrations versionnées (`supabase migration new create_bookings` avec la CLI Supabase) et appliquez-les dans chaque environnement.\n- **Types générés.** La CLI génère les types TypeScript de votre schéma (`supabase gen types typescript`) : votre code et vos agents travaillent sur des noms de colonnes exacts.\n- **Listes fermées.** Une contrainte `check (status in (...))` évolue plus facilement qu'un type `enum` Postgres, dont les valeurs sont délicates à renommer ou à supprimer.\n- **Chevauchements.** Pour empêcher un coach de publier deux créneaux ouverts qui se recouvrent, utilisez une contrainte d'exclusion :\n\n```sql\ncreate extension if not exists btree_gist with schema extensions;\n\nalter table public.slots\n  add constraint slots_no_overlap\n  exclude using gist (coach_id with =, tstzrange(starts_at, ends_at) with &&)\n  where (status = 'open');\n```\n\n- **Concurrence.** Deux clients peuvent réserver la dernière place au même instant. Faites la réservation dans une fonction SQL appelée par le back, qui verrouille le créneau (`select ... for update`), compte les réservations actives, puis insère ou refuse.","personas":["tech"]},{"id":"crs_mvp_ia_m04_l02_b_5","type":"prompt","title":"Faire relire son modèle de données par l'IA","tool":"Claude","prompt":"Tu es un architecte de bases de données qui accompagne un porteur de projet sur son MVP.\n\nContexte du produit : [décrivez votre produit en 3 phrases : utilisateurs, problème, fonctionnalité principale]\nOutil de base de données : [Supabase (Postgres) ou Airtable]\nParcours principal : [décrivez l'action clé en 5 étapes]\n\nVoici mon modèle de données :\n[collez votre tableau ou votre SQL, sans aucune donnée réelle ni clé d'API]\n\nRelis ce modèle et réponds en quatre parties :\n1. Les entités ou relations manquantes pour réaliser le parcours principal.\n2. Les erreurs de type ou de contrainte : montants, dates et fuseaux horaires, identifiants, valeurs obligatoires, doublons possibles.\n3. Les risques pour la suite : données personnelles non nécessaires, informations dupliquées, suppressions qui casseraient l'historique.\n4. Les 3 corrections prioritaires, avec le SQL (ou la structure Airtable) corrigé.\n\nSi une règle métier n'est pas claire, pose-moi d'abord jusqu'à 3 questions. Ne propose pas de fonctionnalités hors du périmètre du MVP.","tips":"Testez ensuite votre modèle avec trois questions concrètes que l'application devra résoudre (par exemple « combien de places reste-t-il sur ce créneau ? »). Si la réponse exige du bricolage, le modèle doit évoluer. Relisez chaque correction proposée : l'IA ajoute parfois des tables inutiles."},{"id":"crs_mvp_ia_m04_l02_b_6","type":"exercice","title":"Le modèle de données de votre MVP","instructions":"Construisez le modèle de données de **votre projet**. Il servira de base à tout le module 6.\n\n1. **Entités.** À partir de vos user stories (module 1), listez 3 à 6 entités. Au-delà, demandez-vous si chacune est vraiment nécessaire au MVP.\n2. **Tableau.** Pour chaque entité : nom de table, colonnes, type de chaque colonne, colonnes obligatoires, valeurs uniques, valeurs autorisées (statuts).\n3. **Relations.** Indiquez chaque relation (1-n ou n-n) et créez une table de liaison pour chaque relation n-n.\n4. **Dates et montants.** Vérifiez : montants en centimes (entier) avec la devise, dates en `timestamptz`, fuseau d'affichage prévu.\n5. **Traduction.** Écrivez le SQL (`create table`) de votre modèle **ou** construisez-le dans Airtable (captures d'écran de chaque table et de ses champs).\n6. **Relecture par l'IA.** Utilisez le prompt de cette leçon. Notez les corrections retenues et celles que vous avez refusées, avec une phrase de justification pour chacune.\n7. **Test.** Écrivez trois questions que votre application devra résoudre et expliquez comment le modèle y répond.\n\nLivrable : un seul document (PDF ou Markdown) regroupant le tableau, le SQL ou les captures Airtable, et vos notes de relecture. Aucune donnée réelle de clients.","deliverable":"fichier","estimatedMinutes":55,"review":"formateur","rubric":["Les entités couvrent le parcours clé du MVP, sans table superflue.","Types, identifiants et contraintes sont adaptés (montants en centimes, dates avec fuseau, statuts en liste fermée).","Les relations sont correctes, avec une table de liaison pour chaque relation n-n.","Le SQL est valide, ou la structure Airtable est cohérente avec le tableau.","La relecture par l'IA est exploitée de façon critique (corrections justifiées)."]},{"id":"crs_mvp_ia_m04_l02_b_7","type":"quiz","title":"Vérifiez vos acquis","graded":false,"questions":[{"id":"crs_mvp_ia_m04_l02_b_7_q_1","prompt":"Comment représenter la relation entre les clients et les créneaux de Créno ?","kind":"unique","options":[{"id":"crs_mvp_ia_m04_l02_b_7_q_1_o_1","label":"Une colonne client_id dans la table des créneaux","correct":false},{"id":"crs_mvp_ia_m04_l02_b_7_q_1_o_2","label":"Une table de liaison (les réservations) qui relie un client à un créneau","correct":true},{"id":"crs_mvp_ia_m04_l02_b_7_q_1_o_3","label":"Une liste de noms de clients dans une colonne texte du créneau","correct":false},{"id":"crs_mvp_ia_m04_l02_b_7_q_1_o_4","label":"Une table par coach","correct":false}],"explanation":"C'est une relation n-n : un client réserve plusieurs créneaux, un créneau accueille plusieurs clients. La table de liaison porte aussi le statut de la réservation."},{"id":"crs_mvp_ia_m04_l02_b_7_q_2","prompt":"Comment stocker un prix de 35,00 € ?","kind":"unique","options":[{"id":"crs_mvp_ia_m04_l02_b_7_q_2_o_1","label":"Le texte « 35 € »","correct":false},{"id":"crs_mvp_ia_m04_l02_b_7_q_2_o_2","label":"Le nombre décimal 35.0","correct":false},{"id":"crs_mvp_ia_m04_l02_b_7_q_2_o_3","label":"L'entier 3500 dans une colonne en centimes, avec la devise","correct":true},{"id":"crs_mvp_ia_m04_l02_b_7_q_2_o_4","label":"L'entier 35, en supposant les euros","correct":false}],"explanation":"Les entiers en centimes évitent les erreurs d'arrondi des nombres à virgule. La devise est enregistrée à part."},{"id":"crs_mvp_ia_m04_l02_b_7_q_3","prompt":"Pourquoi ne pas utiliser l'email comme identifiant d'un profil ?","kind":"unique","options":[{"id":"crs_mvp_ia_m04_l02_b_7_q_3_o_1","label":"Parce qu'un email peut changer, alors qu'un identifiant doit rester stable","correct":true},{"id":"crs_mvp_ia_m04_l02_b_7_q_3_o_2","label":"Parce qu'un email est trop long pour une base de données","correct":false},{"id":"crs_mvp_ia_m04_l02_b_7_q_3_o_3","label":"Parce que Supabase interdit les emails dans les tables","correct":false},{"id":"crs_mvp_ia_m04_l02_b_7_q_3_o_4","label":"Parce qu'un email ne peut pas être unique","correct":false}],"explanation":"Un identifiant technique (uuid) ne change jamais, ce qui garantit que toutes les relations restent valides."},{"id":"crs_mvp_ia_m04_l02_b_7_q_4","prompt":"Où placer la clé étrangère d'une relation 1-n entre un coach et ses créneaux ?","kind":"unique","options":[{"id":"crs_mvp_ia_m04_l02_b_7_q_4_o_1","label":"Dans la table des profils (colonne slot_id)","correct":false},{"id":"crs_mvp_ia_m04_l02_b_7_q_4_o_2","label":"Dans la table des créneaux (colonne coach_id)","correct":true},{"id":"crs_mvp_ia_m04_l02_b_7_q_4_o_3","label":"Dans une table de liaison obligatoire","correct":false},{"id":"crs_mvp_ia_m04_l02_b_7_q_4_o_4","label":"Dans les deux tables","correct":false}],"explanation":"La clé étrangère se place toujours du côté « plusieurs » de la relation."}]}]$q$::jsonb)
